INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C1','sci',6,1,'u1',1,'보물 찾기 활동 — 『과학』 놀이공원 지도에서 보물을 숨길 장소를 정하고, 그 장소에는 제빵 소다 용액을 한 방울, 나머지 장소에는 물을 떨어뜨림(맨눈으로 구별할 수 없도록 비슷한 양) · 마르면 친구와 지도를 바꾸고 숨긴 곳을 예상해 페놀프탈레인 용액을 한 방울 떨어뜨림 · 못 찾으면 다시 예상하고 확인 · 유리 기구 조심, 함부로 맛보거나 냄새 맡지 않기, 피부·눈에 튀지 않게(들어가면 흐르는 물로), 끝나면 정리 · 빨리 찾는 경쟁보다 색깔 변화 관찰에 집중',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C2','sci',6,1,'u1',1,'용액을 섞을 때의 색깔 변화 — 제빵 소다 용액을 떨어뜨린 곳에 페놀프탈레인 용액을 떨어뜨리면 붉은색으로 변하고, 물을 떨어뜨린 곳에서는 아무 변화가 없음 · 용액을 섞으면 다른 색깔로 변하는 경우도 있고 변하지 않는 경우도 있음 · 그 색깔 변화를 이용해 보물을 숨긴 곳을 찾을 수 있음 · 왜 색깔이 변하는지는 다음 시간부터 알아봄',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C3','sci',6,1,'u1',2,'여러 가지 용액의 관찰 — 점적병에 담긴 식초(노란색·투명·냄새), 레몬즙(연한 노란색·불투명·냄새), 빨랫비누 물(흰색·불투명·흔들면 거품 유지·냄새), 석회수(색깔 없음·투명·냄새 안 남), 묽은 염산(색깔 없음·투명·자극성이 강해 냄새를 맡지 않음), 묽은 수산화 나트륨 용액(색깔 없음·투명·냄새 안 남) · 색깔은 흰 종이를, 투명한 정도는 글씨가 쓰인 흰 종이를 뒤에 대고 관찰 · 냄새는 손으로 바람을 일으켜 맡음 · 실험복·보안경·실험용 장갑, 맛보거나 맨손으로 만지지 않기',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C4','sci',6,1,'u1',2,'투명하다와 색깔이 없다 — 「투명하다」는 속까지 환히 비치도록 맑다는 뜻으로 「색깔이 없다」와는 다른 뜻 · 식초처럼 색깔이 있어도 투명한 용액이 있음 · 석회수는 색깔이 없고 투명함',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C5','sci',6,1,'u1',2,'분류 기준 세우기 — 용액을 관찰해 비슷한 점과 다른 점을 찾아 분류 기준을 정하고 분류함 · 분류 기준은 객관적이고 명확한 질문(「색깔이 있는가?」, 「투명한가?」, 「흔들었을 때 거품이 5초 이상 유지되는가?」) · 「용액이 예쁜가?」처럼 사람마다 다르게 판단하는 기준은 알맞지 않음 · 알맞은 기준이면 누가 분류해도 결과가 같음 · 겉보기 성질이 비슷한 용액은 쉽게 구분되지 않아 분류하기 어려움',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C6','sci',6,1,'u1',3,'지시약 — 어떤 용액을 만났을 때 그 용액의 성질에 따라 색깔 변화가 나타나는 물질 · 리트머스 시험지, 페놀프탈레인 용액, 붉은 양배추 용액 등 여러 가지가 있음 · 색깔이 없고 투명해 겉보기 성질로 구별하기 어려운 용액도 지시약으로 분류할 수 있음',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C7','sci',6,1,'u1',3,'리트머스 시험지와 페놀프탈레인 용액 — 산성 용액: 푸른색 리트머스 시험지가 붉은색으로 변함, 붉은색 리트머스 시험지는 변화 없음, 페놀프탈레인 용액은 변화 없음 · 염기성 용액: 붉은색 리트머스 시험지가 푸른색으로 변함, 푸른색 리트머스 시험지는 변화 없음, 페놀프탈레인 용액이 붉은색으로 변함 · 24홈판·실험 도움판, 핀셋으로 시험지를 옮겨 용액이 섞이지 않게',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C8','sci',6,1,'u1',3,'붉은 양배추 용액 — 산성 용액에서는 붉은색 계열, 염기성 용액에서는 푸른색이나 노란색 계열로 변함 · 같은 지시약이라도 용액의 농도에 따라 색깔에 차이가 있으므로 특정 색을 찾기보다 비슷한 계열의 색으로 변했는지 관찰 · 분류한 결과는 리트머스 시험지·페놀프탈레인 용액으로 분류한 결과와 같음',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C9','sci',6,1,'u1',3,'산성 용액과 염기성 용액 — 지시약의 색깔 변화로 여섯 용액이 두 무리로 나뉨 · 산성 용액: 식초, 레몬즙, 묽은 염산 · 염기성 용액: 빨랫비누 물, 석회수, 묽은 수산화 나트륨 용액 · 서로 다른 지시약이라도 분류한 결과는 같음 · 실험복·보안경·실험용 장갑, 피부·눈에 닿으면 흐르는 물로 충분히',ARRAY['여러 가지 용액을 관찰하여 분류하고, 지시약을 이용하여 산성 용액과 염기성 용액으로 분류(문구 초안 — 성취기준 코드 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C10','sci',6,1,'u1',4,'산성 용액의 성질 — 묽은 염산에 달걀 껍데기·조개껍데기를 넣으면 기포가 발생하며 녹고, 삶은 달걀흰자·삶은 닭 가슴살은 변화 없음 · 달걀 껍데기와 조개껍데기의 주요 성분은 탄산 칼슘이며 산성 용액은 탄산 칼슘과 반응함 · 식초에 메추리알을 넣으면 껍데기에서 기포가 발생하며 녹음',ARRAY['산성 용액과 염기성 용액의 성질을 비교하고, 두 용액을 섞을 때의 변화를 관찰(문구 초안 — 성취기준 코드 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C11','sci',6,1,'u1',4,'염기성 용액의 성질 — 묽은 수산화 나트륨 용액에 삶은 달걀흰자·삶은 닭 가슴살을 넣으면 시간이 지나면서 녹아 흐물흐물해지고, 달걀 껍데기·조개껍데기는 변화 없음 · 삶은 달걀흰자와 삶은 닭 가슴살의 주요 성분은 단백질이며 염기성 용액은 단백질과 반응함 · 이 반응은 오래 걸릴 수 있음 · 그래서 산성 용액과 염기성 용액은 서로 다른 성질이 있음',ARRAY['산성 용액과 염기성 용액의 성질을 비교하고, 두 용액을 섞을 때의 변화를 관찰(문구 초안 — 성취기준 코드 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C12','sci',6,1,'u1',4,'성질 비교 실험의 방법과 안전 — 6홈판에 같은 물질을 두 용액에 각각 넣어 비교 · 다른 차시보다 좀 더 진한 용액을 쓰므로 실험복·보안경·실험용 장갑을 반드시 착용, 핀셋으로 용액이 튀지 않게 넣기, 환기, 맛보거나 냄새 맡지 않기, 피부·눈에 닿으면 흐르는 물로 충분히 씻기',ARRAY['산성 용액과 염기성 용액의 성질을 비교하고, 두 용액을 섞을 때의 변화를 관찰(문구 초안 — 성취기준 코드 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C13','sci',6,1,'u1',5,'섞을 때의 색깔 변화 — 붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 많이 넣을수록 붉은색 계열에서 노란색 계열로 변함 · 반대로 묽은 수산화 나트륨 용액에 묽은 염산을 많이 넣을수록 노란색 계열에서 붉은색 계열로 변함 · 색깔 변화표와 비교하면 색이 변하는 것으로 용액의 성질이 변한다는 것을 알 수 있음',ARRAY['산성 용액과 염기성 용액의 성질을 비교하고, 두 용액을 섞을 때의 변화를 관찰(문구 초안 — 성취기준 코드 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C14','sci',6,1,'u1',5,'섞을 때의 성질 변화 — 산성 용액에 염기성 용액을 계속 넣으면 산성이 점점 약해지다가 염기성으로 변함 · 염기성 용액에 산성 용액을 계속 넣으면 염기성이 점점 약해지다가 산성으로 변함 · 두 용액이 만나면 처음의 성질이 점점 약해지고, 더 많이 넣은 용액의 성질을 나타내게 됨',ARRAY['산성 용액과 염기성 용액의 성질을 비교하고, 두 용액을 섞을 때의 변화를 관찰(문구 초안 — 성취기준 코드 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C15','sci',6,1,'u1',5,'섞을 때의 성질 변화 이용 — 산성이 강해진 흙에 염기성을 띤 석회 가루를 뿌려 식물이 잘 자라게 함 · 운반 차량에서 염산이 새어 나오면 염기성을 띤 석회 가루를 뿌려 산성을 약하게 함 · 섞을 때의 성질 변화는 생활에 도움을 줌',ARRAY['산성 용액과 염기성 용액의 성질을 비교하고, 두 용액을 섞을 때의 변화를 관찰(문구 초안 — 성취기준 코드 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C16','sci',6,1,'u1',6,'산성 용액을 이용하는 예 — 식초: 생선을 손질한 도마의 비린내를 약하게 함, 요리에 신맛 · 레몬즙: 생선 요리의 비린내를 약하게 함, 음식에 신맛 · 변기 청소용 세제: 염기성인 변기의 때와 냄새를 없앰 · 구연산 용액: 싱크대를 소독하고 냄새를 없앰',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C17','sci',6,1,'u1',6,'염기성 용액을 이용하는 예 — 욕실 청소용 표백제: 단백질을 녹여 욕실의 때와 세균을 없앰 · 제빵 소다 용액: 주방의 기름때, 과일·채소 껍질에 남은 농약을 없앰 · 제산제: 속이 쓰릴 때 먹어 위의 산성 물질을 약하게 함 · 하수구 세정제: 단백질을 녹여 막힌 하수구의 머리카락을 없앰',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C18','sci',6,1,'u1',6,'반대되는 성질의 용액 이용 — 생선의 비린내는 염기성 물질이라 산성인 식초로 닦으면 약해짐 · 위액은 산성이라 염기성인 제산제를 먹으면 속 쓰림이 약해짐 · 변기의 때와 냄새는 염기성이라 산성 세제를 씀 · 없애려는 물질과 반대되는 성질의 용액을 이용하면 서로 반응하여 성질이 약해짐 · 두 용액의 성질을 직접 이용하기도 함(하수구 세정제가 단백질인 머리카락을 녹임)',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C19','sci',6,1,'u1',7,'산성화 — 어떤 물질이 기존의 성질에서 점차 산성으로 변하는 것 · 산성비: 보통 때보다 산성을 띠는 비(대기 중의 오염 물질이 빗물에 녹음) · 해양 산성화: 바닷물이 산성을 띠는 현상(주된 원인은 이산화 탄소) · 토양 산성화: 땅(흙)이 산성을 띠는 현상',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C20','sci',6,1,'u1',7,'산성화로 인한 피해 — 산성비: 삼림 황폐, 대리암으로 만든 조각상·건축물 훼손(대리암의 주요 성분인 탄산 칼슘이 산성 용액에 녹음), 호수·강의 어류·플랑크톤 피해 · 해양 산성화: 조개껍데기가 얇아짐, 산호가 잘 자라지 못함(조개껍데기·산호의 주요 성분인 탄산 칼슘), 해양 생물 다양성 감소 · 산호초 백화 현상은 해수온 상승·해양 산성화·염분 농도 변화·유해 물질 등 여러 원인 · 토양 산성화: 식물 생장 억제, 토양 미생물 활동 저하 · 생태계를 파괴하고 건물과 문화재도 훼손',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C21','sci',6,1,'u1',7,'산성화의 원인과 대책 — 원인: 화석 연료의 연소, 자동차 배기가스, 산업 활동 등 사람의 활동, 화학 비료나 농약의 과도한 사용 · 대책: 친환경 에너지 이용, 자전거·대중교통 이용으로 대기로 나가는 오염 물질과 이산화 탄소 줄이기 · 산성화된 호수에 염기성 물질을 뿌리면 산성이 약해짐 · 산성화는 전 세계적으로 발생하는 환경 문제로 우리와 관계있음',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C22','sci',6,1,'u1',8,'산성화 알림 동영상 — ① 조사해요: 모둠별로 주제(산성비·해양 산성화·토양 산성화 등)를 고르고 역할을 나누어 원인·현황·전망·대책 조사 → ② 계획해요: 제작 방법과 넣을 내용 협의 → ③ 만들어요: 동영상 편집 애플리케이션 → ④ 공유해요: 누리망·사회 관계망 서비스에 올리고 다른 모둠 동영상에 잘한 점을 댓글로 · 목적: 피해 사례를 소개하고 산성화를 줄이는 노력에 함께하도록 알림 · 자료를 공유할 때는 출처를 밝히거나 인터넷 주소를 링크로 연결(저작권·출처 존중)',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u1-C23','sci',6,1,'u1',8,'환경 과학자 — 토양, 공기, 물 등을 조사하고 분석하여 산성화와 같은 환경 문제의 원인을 찾고 개선하기 위해 연구함 · 토양 환경 과학자: 토양의 산성도 등 상태 분석, 식물이 잘 자랄 환경 연구, 화학 비료·농약을 줄이는 방법과 친환경 퇴비 안내, 토양 오염을 줄이는 기술 개발 · 대기 환경 과학자: 대기 상태 측정·분석, 산성 대기 오염 물질 검출과 배출원 파악, 깨끗한 대기 환경을 위해 노력 · 수질 환경 과학자: 하천·저수지·호수의 수질 측정, 물의 온도·산성도를 재어 호수·해양 산성화와 수질 오염의 원인 파악, 수질 정화 방법 연구',ARRAY['우리 생활에서 산성 용액과 염기성 용액을 이용하는 예를 찾고, 산성화가 환경에 미치는 영향을 조사·공유(문구 초안 — 성취기준 코드 W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X01','sci',6,'u1',ARRAY['SC6-1-u1-C1','SC6-1-u1-C2']::text[],'보물을 숨긴 곳과 숨기지 않은 곳의 결과를 뒤바꾸거나, 물이 페놀프탈레인 용액을 붉게 만든다고 여긴다','붉어진 곳은 제빵 소다 용액 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X02','sci',6,'u1',ARRAY['SC6-1-u1-C1']::text[],'보물 찾기 활동의 순서·방법·안전을 잘못 안다(양을 다르게 떨어뜨리기, 마르기 전에 바꾸기, 맛보기, 빨리 찾는 경쟁에만 매달리기 등)','비슷한 양 · 마른 뒤 바꾸기 · 맛보지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X03','sci',6,'u1',ARRAY['SC6-1-u1-C2']::text[],'용액을 섞으면 언제나 색깔이 변한다고, 또는 결코 변하지 않는다고 여긴다','변하기도 하고 변하지 않기도 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X04','sci',6,'u1',ARRAY['SC6-1-u1-C3','SC6-1-u1-C9','SC6-1-u1-C12']::text[],'용액을 관찰하거나 실험할 때 지킬 것을 잘못 안다(맛보기, 코를 대고 냄새 맡기, 묽은 염산 냄새 맡기, 맨손으로 만지기, 보호 장비 없이 하기 등)','손으로 바람 · 보안경·장갑 · 맛보지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X05','sci',6,'u1',ARRAY['SC6-1-u1-C3']::text[],'여섯 가지 용액의 관찰 결과(색깔·투명한 정도·거품·냄새)를 서로 바꾸어 안다','관찰 기록을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X06','sci',6,'u1',ARRAY['SC6-1-u1-C4']::text[],'투명한 용액은 색깔이 없다고 여기거나, 색깔이 있는 용액은 모두 불투명하다고 여긴다','식초는 노란색인데 투명해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X07','sci',6,'u1',ARRAY['SC6-1-u1-C5']::text[],'분류 기준을 「예쁜가?」, 「마음에 드는가?」처럼 사람마다 다르게 판단하는 질문으로 세운다','객관적이고 명확한 질문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X08','sci',6,'u1',ARRAY['SC6-1-u1-C5','SC6-1-u1-C6']::text[],'겉보기 성질만으로 모든 용액을 나눌 수 있다고 여기거나, 색깔이 없고 투명한 용액은 지시약으로도 나눌 수 없다고 여긴다','겉보기가 비슷하면 지시약을 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X09','sci',6,'u1',ARRAY['SC6-1-u1-C6']::text[],'지시약의 뜻을 잘못 안다(쇠붙이를 끌어당기는 물질, 빛을 내는 물질, 온도에 따라 어는 물질 등으로)','성질에 따라 색깔이 변하는 물질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X10','sci',6,'u1',ARRAY['SC6-1-u1-C6','SC6-1-u1-C9']::text[],'지시약은 한 종류뿐이라고 여기거나, 어느 지시약이든 같은 용액에서 같은 색으로 변한다고 여긴다','지시약마다 색깔 변화가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X11','sci',6,'u1',ARRAY['SC6-1-u1-C7']::text[],'푸른색·붉은색 리트머스 시험지가 어느 용액에서 어떤 색으로 변하는지 거꾸로 안다','푸른색은 산성에서 붉게, 붉은색은 염기성에서 푸르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X12','sci',6,'u1',ARRAY['SC6-1-u1-C7']::text[],'페놀프탈레인 용액이 산성 용액에서 붉은색으로 변한다고, 또는 두 용액 모두에서 변한다고 여긴다','염기성에서만 붉은색') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X13','sci',6,'u1',ARRAY['SC6-1-u1-C8']::text[],'붉은 양배추 용액이 산성·염기성 용액에서 띠는 색깔 계열을 거꾸로 안다','산성 붉은색 계열 · 염기성 푸른색이나 노란색 계열') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X14','sci',6,'u1',ARRAY['SC6-1-u1-C8']::text[],'지시약의 색은 하나로 딱 정해져 있다고 여겨 비슷한 계열의 색으로 관찰해야 함(농도에 따른 차이)을 놓친다','특정 색보다 비슷한 계열') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X15','sci',6,'u1',ARRAY['SC6-1-u1-C9']::text[],'여섯 용액을 산성 용액과 염기성 용액으로 잘못 가른다(석회수를 산성으로, 레몬즙을 염기성으로 등)','식초·레몬즙·묽은 염산이 한 무리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X16','sci',6,'u1',ARRAY['SC6-1-u1-C9']::text[],'지시약이 다르면 산성·염기성으로 분류한 결과도 달라진다고 여긴다','색깔은 달라도 분류 결과는 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X17','sci',6,'u1',ARRAY['SC6-1-u1-C10']::text[],'산성 용액이 삶은 달걀흰자·삶은 닭 가슴살을 녹인다고 여기거나, 달걀 껍데기·조개껍데기가 산성 용액에서 변하지 않는다고 여긴다','산성 용액은 껍데기를 녹여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X18','sci',6,'u1',ARRAY['SC6-1-u1-C11']::text[],'염기성 용액이 달걀 껍데기·조개껍데기를 녹인다고 여기거나, 삶은 달걀흰자·삶은 닭 가슴살이 염기성 용액에서 변하지 않는다고 여긴다','염기성 용액은 흰자·닭 가슴살을 녹여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X19','sci',6,'u1',ARRAY['SC6-1-u1-C11']::text[],'염기성 용액과 단백질의 반응이 곧바로 나타난다고 여기거나, 넣자마자 변화가 없다고 성급히 결론 짓는다','시간이 지나면서 나타나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X20','sci',6,'u1',ARRAY['SC6-1-u1-C10','SC6-1-u1-C11']::text[],'주요 성분(탄산 칼슘·단백질)과 반응하는 용액을 바꾸어 짝짓거나, 두 용액이 같은 물질을 녹인다고 여긴다','탄산 칼슘 ↔ 산성 · 단백질 ↔ 염기성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X21','sci',6,'u1',ARRAY['SC6-1-u1-C12']::text[],'두 용액의 성질을 견주는 실험에서 같게 할 조건(같은 물질·같은 크기·같은 관찰 시간)을 놓친다','용액만 다르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X22','sci',6,'u1',ARRAY['SC6-1-u1-C13']::text[],'두 용액을 섞을 때 붉은 양배추 용액의 색깔이 변하는 방향을 거꾸로 안다','염기성을 넣을수록 노란색 계열 쪽으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X23','sci',6,'u1',ARRAY['SC6-1-u1-C13','SC6-1-u1-C14']::text[],'산성 용액과 염기성 용액을 섞어도 성질이 변하지 않는다고, 또는 두 성질이 모두 더 강해진다고 여긴다','처음 성질이 약해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X24','sci',6,'u1',ARRAY['SC6-1-u1-C14']::text[],'두 용액을 섞으면 곧바로 물이 되거나 용액이 사라진다고 여긴다','색으로 성질 변화를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X25','sci',6,'u1',ARRAY['SC6-1-u1-C14']::text[],'넣는 양과 관계없이 결과가 같다고 여겨, 많이 넣을수록 성질이 차례로 변하고 더 많이 넣은 용액의 성질을 나타냄을 놓친다','넣을수록 차례로 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X26','sci',6,'u1',ARRAY['SC6-1-u1-C15']::text[],'섞을 때의 성질 변화를 이용하는 예를 잘못 안다(산성이 강한 흙이나 염산이 샌 곳에 산성 물질을 더 뿌린다 등)','염기성인 석회 가루') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X27','sci',6,'u1',ARRAY['SC6-1-u1-C16','SC6-1-u1-C17']::text[],'생활에서 이용하는 용액의 성질(산성·염기성)을 바꾸어 가른다','식초·레몬즙·변기 세제·구연산은 산성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X28','sci',6,'u1',ARRAY['SC6-1-u1-C18']::text[],'없애려는 물질과 같은 성질의 용액을 써야 한다고 여기거나, 반대 성질의 용액을 이용하는 까닭을 잇지 못한다','반대 성질과 만나면 약해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X29','sci',6,'u1',ARRAY['SC6-1-u1-C16','SC6-1-u1-C17']::text[],'산성 용액과 염기성 용액은 위험해서 실험실에서만 쓰고 생활에는 이용하지 않는다고 여긴다','요리·청소·약에도 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X30','sci',6,'u1',ARRAY['SC6-1-u1-C19']::text[],'산성화의 뜻을 잘못 안다(온도가 높아지는 것, 색깔이 진해지는 것, 공기 중으로 날아가는 것 등으로)','점차 산성으로 변하는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X31','sci',6,'u1',ARRAY['SC6-1-u1-C19']::text[],'산성비·해양 산성화·토양 산성화의 뜻이나 주된 원인을 서로 바꾸어 안다','비 · 바닷물 · 흙') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X32','sci',6,'u1',ARRAY['SC6-1-u1-C20']::text[],'피해 사례를 다른 산성화의 피해로 바꾸어 가르거나, 산성화가 생물에게 이롭다고 여긴다','조개껍데기는 바다, 식물 생장은 흙') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X33','sci',6,'u1',ARRAY['SC6-1-u1-C20']::text[],'산성화는 생물에게만 피해를 주고 건물·조각상·문화재에는 영향이 없다고 여긴다','대리암 조각상도 훼손돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X34','sci',6,'u1',ARRAY['SC6-1-u1-C20']::text[],'산호초 백화 현상의 원인을 해양 산성화 하나로만 단정한다','수온·염분·유해 물질도 원인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X35','sci',6,'u1',ARRAY['SC6-1-u1-C21','SC6-1-u1-C22']::text[],'산성화는 우리와 관계없는 먼 곳의 일이라 알리거나 줄일 필요가 없다고 여긴다','전 세계적인 환경 문제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X36','sci',6,'u1',ARRAY['SC6-1-u1-C21']::text[],'산성화는 사람의 활동과 관계없이 저절로 생기고, 시간이 지나면 저절로 사라진다고 여긴다','사람의 활동이 원인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X37','sci',6,'u1',ARRAY['SC6-1-u1-C21']::text[],'산성화의 원인과 대책을 바꾸어 가르거나, 오염 물질을 늘리는 행동을 대책으로 여긴다','친환경 에너지 · 대중교통') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X38','sci',6,'u1',ARRAY['SC6-1-u1-C22']::text[],'알림 동영상을 만드는 순서나 조사할 내용을 잘못 안다(조사 없이 만들기, 공유부터 하기 등)','조사 → 계획 → 만들기 → 공유') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X39','sci',6,'u1',ARRAY['SC6-1-u1-C22']::text[],'자료를 만들고 나누는 태도를 잘못 안다(출처 없이 가져다 쓰기, 꾸밈만 중시하기, 비난하는 댓글, 혼자 다 하기 등)','출처 · 협력 · 잘한 점 댓글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X40','sci',6,'u1',ARRAY['SC6-1-u1-C23']::text[],'환경 과학자가 하는 일이나 토양·대기·수질 분야가 맡는 일을 잘못 안다','흙 · 공기 · 물을 조사·분석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u1-X41','sci',6,'u1',ARRAY['SC6-1-u1-C20','SC6-1-u1-C10']::text[],'조개껍데기·산호·대리암이 산성에 피해를 입는 까닭(주요 성분인 탄산 칼슘이 산성 용액에 녹음)을 산성화 피해와 잇지 못한다','탄산 칼슘은 산성 용액에 녹아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#1','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C1',1,'mc','auto','보물을 숨길 장소에는 무엇을 떨어뜨리나요?',ARRAY['SC6-1-u1-X02']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C1","difficulty":1,"kind":"mc","stem":"보물을 숨길 장소에는 무엇을 떨어뜨리나요?","options":[{"t":"제빵 소다 용액","correct":true},{"t":"물","mis":"SC6-1-u1-X02"},{"t":"페놀프탈레인 용액","mis":"SC6-1-u1-X02"},{"t":"우유","mis":"SC6-1-u1-X02"}],"explanation":["순서 ②를 읽어요.","숨길 곳과 나머지 곳이 달라요.","숨길 곳은 제빵 소다 용액이에요."],"asset":{"type":"passage","lines":["① 놀이공원 지도에서 보물을 숨길 장소를 정한다.","② 그 장소에는 제빵 소다 용액을, 나머지 장소에는 물을 한 방울씩 떨어뜨린다.","③ 떨어뜨린 것이 마르면 친구와 지도를 바꾼다.","④ 보물을 숨겼을 것 같은 곳을 예상한다.","⑤ 예상한 곳에 페놀프탈레인 용액을 한 방울 떨어뜨린다.","⑥ 찾지 못하면 ④부터 다시 한다.","⑦ 숨긴 곳과 숨기지 않은 곳의 색깔 변화를 비교한다."],"title":"보물 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#2','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C2',1,'mc','auto','보물을 숨겨 놓은 장소에 페놀프탈레인 용액을 떨어뜨리면 어떻게 되나요?',ARRAY['SC6-1-u1-X01']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C2","difficulty":1,"kind":"mc","stem":"보물을 숨겨 놓은 장소에 페놀프탈레인 용액을 떨어뜨리면 어떻게 되나요?","options":[{"t":"붉은색으로 변한다","correct":true},{"t":"아무 변화가 없다","mis":"SC6-1-u1-X01"},{"t":"푸른색으로 변한다","mis":"SC6-1-u1-X01"},{"t":"노란색으로 변한다","mis":"SC6-1-u1-X01"}],"explanation":["제빵 소다 용액 자리예요.","색깔이 변했어요.","붉은색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#3','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C2',1,'ox','auto','물을 떨어뜨린 곳에 페놀프탈레인 용액을 떨어뜨려도 붉은색으로 변해요.',ARRAY['SC6-1-u1-X01']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C2","difficulty":1,"kind":"ox","stem":"물을 떨어뜨린 곳에 페놀프탈레인 용액을 떨어뜨려도 붉은색으로 변해요.","answer":"X","reason_options":[{"t":"물을 떨어뜨린 곳에서는 아무 변화가 없기 때문에","correct":true},{"t":"물이 페놀프탈레인 용액을 붉게 만들기 때문에","mis":"SC6-1-u1-X01"}],"mis":"SC6-1-u1-X01","explanation":["보물을 숨기지 않은 곳이에요.","물 자리는 그대로였어요.","붉게 변하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#4','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C1',1,'sa','auto','보물이 있다고 예상한 곳에 한 방울 떨어뜨리는 용액은 무엇인가요? (□□□□□ 용액)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C1","difficulty":1,"kind":"sa","stem":"보물이 있다고 예상한 곳에 한 방울 떨어뜨리는 용액은 무엇인가요? (□□□□□ 용액)","answer":["페놀프탈레인","페놀프탈레인 용액"],"explanation":["찾을 때 쓰는 용액이에요.","순서 ⑤를 읽어요.","페놀프탈레인 용액이에요."],"asset":{"type":"passage","lines":["① 놀이공원 지도에서 보물을 숨길 장소를 정한다.","② 그 장소에는 제빵 소다 용액을, 나머지 장소에는 물을 한 방울씩 떨어뜨린다.","③ 떨어뜨린 것이 마르면 친구와 지도를 바꾼다.","④ 보물을 숨겼을 것 같은 곳을 예상한다.","⑤ 예상한 곳에 페놀프탈레인 용액을 한 방울 떨어뜨린다.","⑥ 찾지 못하면 ④부터 다시 한다.","⑦ 숨긴 곳과 숨기지 않은 곳의 색깔 변화를 비교한다."],"title":"보물 찾기 순서"},"mis":"SC6-1-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#5','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C1',2,'mc','auto','보물을 숨기지 않은 나머지 장소에 물을 떨어뜨리는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X02','SC6-1-u1-X01']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C1","difficulty":2,"kind":"mc","stem":"보물을 숨기지 않은 나머지 장소에 물을 떨어뜨리는 까닭은 무엇인가요?","options":[{"t":"보물을 숨긴 곳을 맨눈으로 구별할 수 없게 하려고","correct":true},{"t":"지도를 깨끗하게 씻어 내려고","mis":"SC6-1-u1-X02"},{"t":"물이 페놀프탈레인 용액을 붉게 만들게 하려고","mis":"SC6-1-u1-X01"},{"t":"지도 종이를 더 단단하게 만들려고","mis":"SC6-1-u1-X02"}],"explanation":["맨눈으로 보면 어떨까요?","모두 젖은 자국이 생겨요.","숨긴 곳을 들키지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#6','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C1',2,'match','auto','준비물과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u1-C1","difficulty":2,"kind":"match","stem":"준비물과 하는 일을 알맞게 이으세요.","pairs":[{"l":"제빵 소다 용액","r":"보물을 숨길 장소에 떨어뜨린다"},{"l":"물","r":"보물을 숨기지 않은 장소에 떨어뜨린다"},{"l":"페놀프탈레인 용액","r":"예상한 곳에 떨어뜨려 색깔 변화를 본다"},{"l":"놀이공원 지도","r":"보물을 숨기고 찾는 판이 된다"}],"mis":"SC6-1-u1-X02","explanation":["숨길 때 쓰는 것이 둘이에요.","찾을 때 쓰는 것이 하나예요.","지도는 판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#7','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C1',2,'blank','auto','「떨어뜨린 제빵 소다 용액과 물이 (    ) 친구와 놀이공원 지도를 바꿉니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X02','SC6-1-u1-X01']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C1","difficulty":2,"kind":"blank","stem":"「떨어뜨린 제빵 소다 용액과 물이 (    ) 친구와 놀이공원 지도를 바꿉니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"마르면","correct":true},{"t":"떨어뜨리자마자","mis":"SC6-1-u1-X02"},{"t":"붉게 변하면","mis":"SC6-1-u1-X01"},{"t":"모두 닦아 내면","mis":"SC6-1-u1-X02"}],"explanation":["순서 ③이에요.","젖어 있으면 티가 나요.","마르면 바꿔요."],"asset":{"type":"passage","lines":["① 놀이공원 지도에서 보물을 숨길 장소를 정한다.","② 그 장소에는 제빵 소다 용액을, 나머지 장소에는 물을 한 방울씩 떨어뜨린다.","③ 떨어뜨린 것이 마르면 친구와 지도를 바꾼다.","④ 보물을 숨겼을 것 같은 곳을 예상한다.","⑤ 예상한 곳에 페놀프탈레인 용액을 한 방울 떨어뜨린다.","⑥ 찾지 못하면 ④부터 다시 한다.","⑦ 숨긴 곳과 숨기지 않은 곳의 색깔 변화를 비교한다."],"title":"보물 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#8','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C1',2,'error','auto','활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X02']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C1","difficulty":2,"kind":"error","stem":"활동하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「누가 먼저 찾는지 경쟁하는 게 가장 중요해.」","correct":true,"mis_target":"SC6-1-u1-X02"},{"t":"하린 — 「못 찾으면 다시 예상해 보자.」","mis":"SC6-1-u1-X02"},{"t":"지민 — 「용액이 눈에 들어가면 흐르는 물로 씻자.」","mis":"SC6-1-u1-X02"}],"explanation":["무엇에 집중하나요?","색깔 변화 관찰이에요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#9','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C1',2,'ox','auto','실험에 쓰는 용액은 맛을 보아 확인해도 괜찮아요.',ARRAY['SC6-1-u1-X02']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C1","difficulty":2,"kind":"ox","stem":"실험에 쓰는 용액은 맛을 보아 확인해도 괜찮아요.","answer":"X","reason_options":[{"t":"실험에 쓰는 물질은 함부로 맛보거나 냄새 맡지 않아야 하기 때문에","correct":true},{"t":"맛을 보아야 보물을 빨리 찾을 수 있기 때문에","mis":"SC6-1-u1-X02"}],"mis":"SC6-1-u1-X02","explanation":["실험 물질이에요.","먹으면 위험해요.","맛보지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_basic#10','sci',6,1,'u1','L01','g6_1_sci_u1_L01_basic','lesson_basic','SC6-1-u1-C2',3,'mc','auto','보물 찾기 활동으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u1-X03','SC6-1-u1-X01']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C2","difficulty":3,"kind":"mc","stem":"보물 찾기 활동으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"용액을 섞으면 다른 색깔로 변하는 경우도 있고 변하지 않는 경우도 있다","correct":true},{"t":"용액을 섞으면 언제나 색깔이 변한다","mis":"SC6-1-u1-X03"},{"t":"용액을 섞어도 색깔은 절대 변하지 않는다","mis":"SC6-1-u1-X03"},{"t":"물에 페놀프탈레인 용액을 섞으면 붉게 변한다","mis":"SC6-1-u1-X01"}],"explanation":["두 자리를 견줘요.","한 자리만 변했어요.","변하기도, 않기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#1','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C1',2,'sa','auto','보물을 숨길 장소에 한 방울 떨어뜨리는 용액은 무엇인가요? (□□ □□ 용액)','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C1","difficulty":2,"kind":"sa","stem":"보물을 숨길 장소에 한 방울 떨어뜨리는 용액은 무엇인가요? (□□ □□ 용액)","answer":["제빵 소다","제빵 소다 용액","제빵소다","제빵소다 용액"],"explanation":["숨길 때 쓰는 용액이에요.","빵을 만들 때 쓰는 가루예요.","제빵 소다 용액이에요."],"asset":{"type":"passage","lines":["① 놀이공원 지도에서 보물을 숨길 장소를 정한다.","② 그 장소에는 제빵 소다 용액을, 나머지 장소에는 물을 한 방울씩 떨어뜨린다.","③ 떨어뜨린 것이 마르면 친구와 지도를 바꾼다.","④ 보물을 숨겼을 것 같은 곳을 예상한다.","⑤ 예상한 곳에 페놀프탈레인 용액을 한 방울 떨어뜨린다.","⑥ 찾지 못하면 ④부터 다시 한다.","⑦ 숨긴 곳과 숨기지 않은 곳의 색깔 변화를 비교한다."],"title":"보물 찾기 순서"},"mis":"SC6-1-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#2','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C1',2,'ox','auto','보물을 숨겨 놓은 장소를 찾지 못하면 다시 예상하고 확인해요.',ARRAY['SC6-1-u1-X02']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C1","difficulty":2,"kind":"ox","stem":"보물을 숨겨 놓은 장소를 찾지 못하면 다시 예상하고 확인해요.","answer":"O","reason_options":[{"t":"찾지 못하면 숨긴 곳을 다시 예상해 페놀프탈레인 용액을 떨어뜨려 보기 때문에","correct":true},{"t":"한 번 찾지 못하면 활동이 끝나기 때문에","mis":"SC6-1-u1-X02"}],"mis":"SC6-1-u1-X02","explanation":["순서 ⑥을 읽어요.","다시 해요.","맞는 말이에요."],"asset":{"type":"passage","lines":["① 놀이공원 지도에서 보물을 숨길 장소를 정한다.","② 그 장소에는 제빵 소다 용액을, 나머지 장소에는 물을 한 방울씩 떨어뜨린다.","③ 떨어뜨린 것이 마르면 친구와 지도를 바꾼다.","④ 보물을 숨겼을 것 같은 곳을 예상한다.","⑤ 예상한 곳에 페놀프탈레인 용액을 한 방울 떨어뜨린다.","⑥ 찾지 못하면 ④부터 다시 한다.","⑦ 숨긴 곳과 숨기지 않은 곳의 색깔 변화를 비교한다."],"title":"보물 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#3','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C1',3,'mc','auto','숨길 곳에만 제빵 소다 용액을 많이 떨어뜨리고 나머지 곳에는 물을 아주 조금 떨어뜨리면 어떤 문제가 생기나요?',ARRAY['SC6-1-u1-X01','SC6-1-u1-X02']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C1","difficulty":3,"kind":"mc","stem":"숨길 곳에만 제빵 소다 용액을 많이 떨어뜨리고 나머지 곳에는 물을 아주 조금 떨어뜨리면 어떤 문제가 생기나요?","options":[{"t":"보물을 숨긴 곳이 맨눈으로 드러나 버린다","correct":true},{"t":"페놀프탈레인 용액의 색깔이 변하지 않는다","mis":"SC6-1-u1-X01"},{"t":"물을 떨어뜨린 곳이 붉게 변한다","mis":"SC6-1-u1-X01"},{"t":"지도가 더 빨리 마른다","mis":"SC6-1-u1-X02"}],"explanation":["자국의 크기가 달라요.","눈으로 보여요.","숨긴 곳이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#4','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C2',3,'error','auto','결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X01']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C2","difficulty":3,"kind":"error","stem":"결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「붉게 변한 곳에는 물이 떨어져 있었어.」","correct":true,"mis_target":"SC6-1-u1-X01"},{"t":"예준 — 「붉게 변한 곳이 보물을 숨긴 곳이야.」","mis":"SC6-1-u1-X01"},{"t":"다인 — 「물을 떨어뜨린 곳은 변화가 없었어.」","mis":"SC6-1-u1-X01"}],"explanation":["붉어진 곳을 떠올려요.","제빵 소다 용액 자리예요.","수아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#5','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C2',3,'mc','auto','보물 찾기 활동에서 색깔 변화가 나타난 경우는 어느 것인가요?',ARRAY['SC6-1-u1-X01','SC6-1-u1-X03']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C2","difficulty":3,"kind":"mc","stem":"보물 찾기 활동에서 색깔 변화가 나타난 경우는 어느 것인가요?","options":[{"t":"제빵 소다 용액이 마른 자리에 페놀프탈레인 용액을 떨어뜨린 경우","correct":true},{"t":"물이 마른 자리에 페놀프탈레인 용액을 떨어뜨린 경우","mis":"SC6-1-u1-X01"},{"t":"지도에 물만 떨어뜨린 경우","mis":"SC6-1-u1-X03"},{"t":"아무것도 떨어뜨리지 않은 경우","mis":"SC6-1-u1-X03"}],"explanation":["두 용액이 만나야 해요.","물 자리는 그대로예요.","제빵 소다 용액 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#6','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C2',3,'match','auto','장소와 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u1-C2","difficulty":3,"kind":"match","stem":"장소와 알맞은 설명을 이으세요.","pairs":[{"l":"보물을 숨긴 장소","r":"페놀프탈레인 용액이 붉은색으로 변한다"},{"l":"보물을 숨기지 않은 장소","r":"페놀프탈레인 용액에 변화가 없다"},{"l":"다 마른 뒤 바꾼 지도","r":"맨눈으로는 숨긴 곳을 알 수 없다"}],"mis":"SC6-1-u1-X01","explanation":["숨긴 곳은 변해요.","숨기지 않은 곳은 그대로예요.","마르면 티가 나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#7','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C1',3,'mc','auto','활동할 때 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u1-X02']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C1","difficulty":3,"kind":"mc","stem":"활동할 때 알맞은 행동은 어느 것인가요?","options":[{"t":"용액이 피부나 눈에 튀지 않게 조심한다","correct":true},{"t":"남은 용액으로 친구와 장난을 친다","mis":"SC6-1-u1-X02"},{"t":"유리 기구를 책상 끝에 아무렇게나 둔다","mis":"SC6-1-u1-X02"},{"t":"끝난 뒤 정리하지 않고 자리를 뜬다","mis":"SC6-1-u1-X02"}],"explanation":["안전을 떠올려요.","튀면 위험해요.","조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#8','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C2',4,'mc','auto','「왜 제빵 소다 용액 자리에서만 색깔이 변해?」라고 묻는 친구에게 오늘 할 수 있는 가장 알맞은 대답은 어느 것인가요?',ARRAY['SC6-1-u1-X01','SC6-1-u1-X03','SC6-1-u1-X02']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C2","difficulty":4,"kind":"mc","stem":"「왜 제빵 소다 용액 자리에서만 색깔이 변해?」라고 묻는 친구에게 오늘 할 수 있는 가장 알맞은 대답은 어느 것인가요?","options":[{"t":"오늘은 색깔이 변하는 경우와 변하지 않는 경우를 관찰했고, 그 까닭은 다음 시간부터 하나씩 알아봐","correct":true},{"t":"물이 페놀프탈레인 용액과 만나 붉어지기 때문이야","mis":"SC6-1-u1-X01"},{"t":"용액은 섞으면 언제나 붉게 변하기 때문이야","mis":"SC6-1-u1-X03"},{"t":"까닭은 알 수 없으니 관찰하지 않아도 돼","mis":"SC6-1-u1-X02"}],"explanation":["오늘 한 일을 떠올려요.","관찰까지 했어요.","까닭은 다음 시간부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#9','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C1',4,'mc','auto','친구와 지도를 바꾼 뒤 보물을 찾는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X02']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C1","difficulty":4,"kind":"mc","stem":"친구와 지도를 바꾼 뒤 보물을 찾는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"숨긴 곳 예상하기 → 페놀프탈레인 용액 떨어뜨리기 → 색깔 변화 비교하기","correct":true},{"t":"페놀프탈레인 용액 떨어뜨리기 → 숨긴 곳 예상하기 → 색깔 변화 비교하기","mis":"SC6-1-u1-X02"},{"t":"색깔 변화 비교하기 → 숨긴 곳 예상하기 → 페놀프탈레인 용액 떨어뜨리기","mis":"SC6-1-u1-X02"},{"t":"제빵 소다 용액 떨어뜨리기 → 숨긴 곳 예상하기 → 색깔 변화 비교하기","mis":"SC6-1-u1-X02"}],"explanation":["먼저 예상해요.","그다음 확인해요.","마지막에 비교해요."],"asset":{"type":"passage","lines":["① 놀이공원 지도에서 보물을 숨길 장소를 정한다.","② 그 장소에는 제빵 소다 용액을, 나머지 장소에는 물을 한 방울씩 떨어뜨린다.","③ 떨어뜨린 것이 마르면 친구와 지도를 바꾼다.","④ 보물을 숨겼을 것 같은 곳을 예상한다.","⑤ 예상한 곳에 페놀프탈레인 용액을 한 방울 떨어뜨린다.","⑥ 찾지 못하면 ④부터 다시 한다.","⑦ 숨긴 곳과 숨기지 않은 곳의 색깔 변화를 비교한다."],"title":"보물 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L01_challenge#10','sci',6,1,'u1','L01','g6_1_sci_u1_L01_challenge','lesson_challenge','SC6-1-u1-C2',4,'essay','teacher','보물을 숨긴 장소와 숨기지 않은 장소에 페놀프탈레인 용액을 떨어뜨린 결과를 각각 쓰고, 이 결과로 보물을 찾을 수 있었던 까닭과 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C2","difficulty":4,"kind":"essay","stem":"보물을 숨긴 장소와 숨기지 않은 장소에 페놀프탈레인 용액을 떨어뜨린 결과를 각각 쓰고, 이 결과로 보물을 찾을 수 있었던 까닭과 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 보물을 숨긴 장소에는 제빵 소다 용액을 떨어뜨렸는데, 그곳에 페놀프탈레인 용액을 떨어뜨리면 붉은색으로 변했다. 물을 떨어뜨린 장소에서는 아무 변화가 없었다. 두 곳은 마른 뒤 맨눈으로는 구별할 수 없었지만 색깔 변화로 숨긴 곳을 찾을 수 있었다. 용액을 섞으면 다른 색깔로 변하는 경우도 있고 변하지 않는 경우도 있다는 것을 알게 되었다.","scoring_points":["두 장소의 결과를 바르게 썼는가","색깔 변화로 찾을 수 있었던 까닭을 썼는가","변하는 경우와 변하지 않는 경우가 있음을 썼는가"]},"explanation":["결과 둘을 써요.","찾을 수 있었던 까닭을 써요.","알게 된 점을 써요."],"asset":{"type":"passage","lines":["① 놀이공원 지도에서 보물을 숨길 장소를 정한다.","② 그 장소에는 제빵 소다 용액을, 나머지 장소에는 물을 한 방울씩 떨어뜨린다.","③ 떨어뜨린 것이 마르면 친구와 지도를 바꾼다.","④ 보물을 숨겼을 것 같은 곳을 예상한다.","⑤ 예상한 곳에 페놀프탈레인 용액을 한 방울 떨어뜨린다.","⑥ 찾지 못하면 ④부터 다시 한다.","⑦ 숨긴 곳과 숨기지 않은 곳의 색깔 변화를 비교한다."],"title":"보물 찾기 순서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#1','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C3',1,'mc','auto','흰색이고 흔들었을 때 거품이 유지되는 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C3","difficulty":1,"kind":"mc","stem":"흰색이고 흔들었을 때 거품이 유지되는 용액은 어느 것인가요?","options":[{"t":"빨랫비누 물","correct":true},{"t":"식초","mis":"SC6-1-u1-X05"},{"t":"석회수","mis":"SC6-1-u1-X05"},{"t":"레몬즙","mis":"SC6-1-u1-X05"}],"explanation":["관찰 기록을 읽어요.","거품이 유지된 것은 하나예요.","빨랫비누 물이에요."],"asset":{"type":"passage","lines":["식초 — 노란색 · 투명함 · 거품 유지 안 됨 · 냄새 남","레몬즙 — 연한 노란색 · 불투명함 · 거품 유지 안 됨 · 냄새 남","빨랫비누 물 — 흰색 · 불투명함 · 거품 유지됨 · 냄새 남","석회수 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남","묽은 염산 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 맡지 않음","묽은 수산화 나트륨 용액 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남"],"title":"여섯 가지 용액 관찰 기록(거품은 흔들고 5초 뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#2','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C5',1,'blank','auto','「용액을 관찰하고 비슷한 점과 다른 점을 찾아 (    )을 세워 분류합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X07']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C5","difficulty":1,"kind":"blank","stem":"「용액을 관찰하고 비슷한 점과 다른 점을 찾아 (    )을 세워 분류합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"분류 기준","correct":true},{"t":"용액의 이름","mis":"SC6-1-u1-X07"},{"t":"용액의 무게","mis":"SC6-1-u1-X07"},{"t":"좋아하는 순서","mis":"SC6-1-u1-X07"}],"explanation":["분류하려면 무엇이 필요할까요?","나누는 잣대예요.","분류 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#3','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C3',1,'ox','auto','묽은 염산은 코를 가까이 대고 냄새를 맡아 관찰해요.',ARRAY['SC6-1-u1-X04']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C3","difficulty":1,"kind":"ox","stem":"묽은 염산은 코를 가까이 대고 냄새를 맡아 관찰해요.","answer":"X","reason_options":[{"t":"묽은 염산은 자극성이 강해 냄새를 맡지 않기 때문에","correct":true},{"t":"냄새를 맡아야 정확하게 분류할 수 있기 때문에","mis":"SC6-1-u1-X04"}],"mis":"SC6-1-u1-X04","explanation":["묽은 염산을 떠올려요.","자극성이 강해요.","냄새를 맡지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#4','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C3',1,'sa','auto','용액을 한 방울씩 떨어뜨릴 수 있게 담아 두는 병을 무엇이라고 하나요? (□□병)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C3","difficulty":1,"kind":"sa","stem":"용액을 한 방울씩 떨어뜨릴 수 있게 담아 두는 병을 무엇이라고 하나요? (□□병)","answer":["점적병"],"explanation":["한 방울씩 떨어뜨려요.","세 글자예요.","점적병이에요."],"mis":"SC6-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#5','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C3',2,'mc','auto','용액의 투명한 정도를 관찰하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X04','SC6-1-u1-X05']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C3","difficulty":2,"kind":"mc","stem":"용액의 투명한 정도를 관찰하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"글씨가 쓰인 흰 종이를 용액 뒤에 대고 본다","correct":true},{"t":"용액을 조금 맛본다","mis":"SC6-1-u1-X04"},{"t":"용액을 손가락으로 만져 본다","mis":"SC6-1-u1-X04"},{"t":"용액을 흔들어 거품을 센다","mis":"SC6-1-u1-X05"}],"explanation":["속까지 비치는지 봐요.","글씨가 보이나요?","글씨가 쓰인 흰 종이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#6','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C4',2,'mc','auto','다음 중 옳은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X06']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C4","difficulty":2,"kind":"mc","stem":"다음 중 옳은 것은 어느 것인가요?","options":[{"t":"식초처럼 색깔이 있어도 투명한 용액이 있다","correct":true},{"t":"투명한 용액은 모두 색깔이 없다","mis":"SC6-1-u1-X06"},{"t":"색깔이 있는 용액은 모두 불투명하다","mis":"SC6-1-u1-X06"},{"t":"불투명한 용액에는 색깔이 없다","mis":"SC6-1-u1-X06"}],"explanation":["식초를 떠올려요.","노란색인데 비쳐요.","색깔과 투명함은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#7','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C3',2,'match','auto','용액과 관찰 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-1-u1-C3","difficulty":2,"kind":"match","stem":"용액과 관찰 결과를 알맞게 이으세요.","pairs":[{"l":"빨랫비누 물","r":"흰색이고 흔들면 거품이 유지된다"},{"l":"식초","r":"노란색이며 투명하다"},{"l":"석회수","r":"색깔이 없고 투명하며 냄새가 나지 않는다"},{"l":"레몬즙","r":"연한 노란색이며 불투명하다"}],"mis":"SC6-1-u1-X05","explanation":["거품은 빨랫비누 물이에요.","노란색 둘을 가려요.","석회수는 색깔이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#8','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C5',2,'ox','auto','「용액이 예쁜가?」는 알맞은 분류 기준이에요.',ARRAY['SC6-1-u1-X07']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C5","difficulty":2,"kind":"ox","stem":"「용액이 예쁜가?」는 알맞은 분류 기준이에요.","answer":"X","reason_options":[{"t":"사람마다 다르게 판단하는 기준이라 알맞지 않기 때문에","correct":true},{"t":"보기 좋은 용액끼리 모으면 되기 때문에","mis":"SC6-1-u1-X07"}],"mis":"SC6-1-u1-X07","explanation":["누가 해도 같은 결과일까요?","예쁜 것은 사람마다 달라요.","알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#9','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C5',2,'mc','auto','분류 기준으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X07','SC6-1-u1-X04']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C5","difficulty":2,"kind":"mc","stem":"분류 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"흔들었을 때 거품이 5초 이상 유지되는가?","correct":true},{"t":"용액이 예쁜가?","mis":"SC6-1-u1-X07"},{"t":"내 마음에 드는가?","mis":"SC6-1-u1-X07"},{"t":"맛이 좋은가?","mis":"SC6-1-u1-X04"}],"explanation":["객관적인 질문을 찾아요.","누가 봐도 같아야 해요.","거품 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_basic#10','sci',6,1,'u1','L02','g6_1_sci_u1_L02_basic','lesson_basic','SC6-1-u1-C5',3,'mc','auto','「투명한가?」로 분류할 때 「그렇지 않다」에 들어가는 용액끼리 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X06']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C5","difficulty":3,"kind":"mc","stem":"「투명한가?」로 분류할 때 「그렇지 않다」에 들어가는 용액끼리 모은 것은 어느 것인가요?","options":[{"t":"레몬즙, 빨랫비누 물","correct":true},{"t":"식초, 석회수","mis":"SC6-1-u1-X06"},{"t":"묽은 염산, 묽은 수산화 나트륨 용액","mis":"SC6-1-u1-X06"},{"t":"식초, 레몬즙","mis":"SC6-1-u1-X06"}],"explanation":["불투명한 것을 찾아요.","식초는 투명해요.","레몬즙과 빨랫비누 물이에요."],"asset":{"type":"passage","lines":["식초 — 노란색 · 투명함 · 거품 유지 안 됨 · 냄새 남","레몬즙 — 연한 노란색 · 불투명함 · 거품 유지 안 됨 · 냄새 남","빨랫비누 물 — 흰색 · 불투명함 · 거품 유지됨 · 냄새 남","석회수 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남","묽은 염산 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 맡지 않음","묽은 수산화 나트륨 용액 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남"],"title":"여섯 가지 용액 관찰 기록(거품은 흔들고 5초 뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#1','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C4',2,'sa','auto','「투명하다」는 속까지 환히 비치도록 □□는 뜻이에요. □□에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C4","difficulty":2,"kind":"sa","stem":"「투명하다」는 속까지 환히 비치도록 □□는 뜻이에요. □□에 알맞은 두 글자를 쓰세요.","answer":["맑다"],"explanation":["비치는 모습이에요.","흐리다의 반대예요.","맑다예요."],"mis":"SC6-1-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#2','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C3',2,'ox','auto','용액의 냄새는 손으로 바람을 일으켜 맡아요.',ARRAY['SC6-1-u1-X04']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C3","difficulty":2,"kind":"ox","stem":"용액의 냄새는 손으로 바람을 일으켜 맡아요.","answer":"O","reason_options":[{"t":"코를 직접 대면 위험할 수 있기 때문에","correct":true},{"t":"냄새는 코를 용액에 바짝 대야 정확하기 때문에","mis":"SC6-1-u1-X04"}],"mis":"SC6-1-u1-X04","explanation":["냄새 맡는 법이에요.","손으로 부쳐요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#3','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C5',3,'mc','auto','「투명한가?」로 분류할 때 「그렇다」에 들어가는 용액은 모두 몇 가지인가요?',ARRAY['SC6-1-u1-X06']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C5","difficulty":3,"kind":"mc","stem":"「투명한가?」로 분류할 때 「그렇다」에 들어가는 용액은 모두 몇 가지인가요?","options":[{"t":"네 가지","correct":true},{"t":"두 가지","mis":"SC6-1-u1-X06"},{"t":"여섯 가지","mis":"SC6-1-u1-X06"},{"t":"한 가지","mis":"SC6-1-u1-X06"}],"explanation":["투명한 것을 세요.","식초도 투명해요.","네 가지예요."],"asset":{"type":"passage","lines":["식초 — 노란색 · 투명함 · 거품 유지 안 됨 · 냄새 남","레몬즙 — 연한 노란색 · 불투명함 · 거품 유지 안 됨 · 냄새 남","빨랫비누 물 — 흰색 · 불투명함 · 거품 유지됨 · 냄새 남","석회수 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남","묽은 염산 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 맡지 않음","묽은 수산화 나트륨 용액 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남"],"title":"여섯 가지 용액 관찰 기록(거품은 흔들고 5초 뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
