INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#5','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C4',3,'error','auto','관찰을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X06','SC6-1-u1-X05']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C4","difficulty":3,"kind":"error","stem":"관찰을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「식초는 노란색이니까 투명하지 않아.」","correct":true,"mis_target":"SC6-1-u1-X06"},{"t":"소이 — 「석회수는 색깔이 없고 투명해.」","mis":"SC6-1-u1-X06"},{"t":"건우 — 「레몬즙은 연한 노란색이고 불투명해.」","mis":"SC6-1-u1-X05"}],"explanation":["식초를 떠올려요.","색깔이 있어도 비쳐요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#6','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C5',3,'mc','auto','분류 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X07']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C5","difficulty":3,"kind":"mc","stem":"분류 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"냄새가 좋은가?","correct":true},{"t":"투명한가?","mis":"SC6-1-u1-X07"},{"t":"색깔이 있는가?","mis":"SC6-1-u1-X07"},{"t":"흔들었을 때 거품이 5초 이상 유지되는가?","mis":"SC6-1-u1-X07"}],"explanation":["사람마다 다른 것을 찾아요.","좋은 냄새는 사람마다 달라요.","냄새가 좋은가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#7','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C5',3,'mc','auto','알맞은 분류 기준으로 나누었더니 친구들의 분류 결과가 모두 같았어요. 그 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X07','SC6-1-u1-X08']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C5","difficulty":3,"kind":"mc","stem":"알맞은 분류 기준으로 나누었더니 친구들의 분류 결과가 모두 같았어요. 그 까닭은 무엇인가요?","options":[{"t":"객관적이고 명확한 질문이라 누가 해도 같은 답이 나오기 때문에","correct":true},{"t":"친구끼리 결과를 베꼈기 때문에","mis":"SC6-1-u1-X07"},{"t":"여섯 용액의 겉보기 성질이 모두 같기 때문에","mis":"SC6-1-u1-X08"},{"t":"기준과 관계없이 분류 결과는 늘 같기 때문에","mis":"SC6-1-u1-X07"}],"explanation":["기준의 조건을 떠올려요.","분명한 질문이에요.","누가 해도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#8','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C5',4,'mc','auto','「투명한가?」에 「그렇다」이면서 「색깔이 있는가?」에도 「그렇다」인 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X06']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C5","difficulty":4,"kind":"mc","stem":"「투명한가?」에 「그렇다」이면서 「색깔이 있는가?」에도 「그렇다」인 용액은 어느 것인가요?","options":[{"t":"식초","correct":true},{"t":"석회수","mis":"SC6-1-u1-X06"},{"t":"레몬즙","mis":"SC6-1-u1-X06"},{"t":"묽은 염산","mis":"SC6-1-u1-X06"}],"explanation":["투명한 넷을 먼저 골라요.","그중 색깔 있는 것을 찾아요.","식초예요."],"asset":{"type":"passage","lines":["식초 — 노란색 · 투명함 · 거품 유지 안 됨 · 냄새 남","레몬즙 — 연한 노란색 · 불투명함 · 거품 유지 안 됨 · 냄새 남","빨랫비누 물 — 흰색 · 불투명함 · 거품 유지됨 · 냄새 남","석회수 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남","묽은 염산 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 맡지 않음","묽은 수산화 나트륨 용액 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남"],"title":"여섯 가지 용액 관찰 기록(거품은 흔들고 5초 뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#9','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C3',4,'mc','auto','관찰 방법을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X04']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C3","difficulty":4,"kind":"mc","stem":"관찰 방법을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"색깔 — 흰 종이를 뒤에 댄다 · 투명한 정도 — 글씨가 쓰인 흰 종이를 뒤에 댄다 · 냄새 — 손으로 바람을 일으킨다","correct":true},{"t":"색깔 — 맛을 본다 · 투명한 정도 — 흔들어 본다 · 냄새 — 코를 바짝 댄다","mis":"SC6-1-u1-X04"},{"t":"색깔 — 글씨가 쓰인 흰 종이를 댄다 · 투명한 정도 — 맨손으로 만진다 · 냄새 — 손으로 바람을 일으킨다","mis":"SC6-1-u1-X04"},{"t":"색깔 — 흰 종이를 뒤에 댄다 · 투명한 정도 — 흰 종이를 댄다 · 냄새 — 묽은 염산도 코를 대고 맡는다","mis":"SC6-1-u1-X04"}],"explanation":["세 가지를 하나씩 따져요.","냄새는 손으로 부쳐요.","모두 맞는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L02_challenge#10','sci',6,1,'u1','L02','g6_1_sci_u1_L02_challenge','lesson_challenge','SC6-1-u1-C5',4,'essay','teacher','여섯 가지 용액을 나눌 분류 기준을 두 가지 정해 각각 「그렇다」와 「그렇지 않다」로 분류하세요. 그리고 알맞은 분류 기준이 갖추어야 할 조건을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C5","difficulty":4,"kind":"essay","stem":"여섯 가지 용액을 나눌 분류 기준을 두 가지 정해 각각 「그렇다」와 「그렇지 않다」로 분류하세요. 그리고 알맞은 분류 기준이 갖추어야 할 조건을 쓰세요.","answer_guide":{"answer":"예: 첫째 기준 「투명한가?」 — 그렇다: 식초, 석회수, 묽은 염산, 묽은 수산화 나트륨 용액 / 그렇지 않다: 레몬즙, 빨랫비누 물. 둘째 기준 「흔들었을 때 거품이 5초 이상 유지되는가?」 — 그렇다: 빨랫비누 물 / 그렇지 않다: 나머지 다섯 가지. 알맞은 분류 기준은 「예쁜가?」처럼 사람마다 다르게 판단하는 것이 아니라 누가 분류해도 같은 결과가 나오는 객관적이고 명확한 질문이어야 한다.","scoring_points":["기준 두 가지를 질문으로 세웠는가","각 기준으로 바르게 분류했는가","객관적이고 명확한 질문이라는 조건을 썼는가"]},"explanation":["기준을 질문으로 써요.","두 무리로 나눠요.","조건을 써요."],"asset":{"type":"passage","lines":["식초 — 노란색 · 투명함 · 거품 유지 안 됨 · 냄새 남","레몬즙 — 연한 노란색 · 불투명함 · 거품 유지 안 됨 · 냄새 남","빨랫비누 물 — 흰색 · 불투명함 · 거품 유지됨 · 냄새 남","석회수 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남","묽은 염산 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 맡지 않음","묽은 수산화 나트륨 용액 — 색깔 없음 · 투명함 · 거품 유지 안 됨 · 냄새 안 남"],"title":"여섯 가지 용액 관찰 기록(거품은 흔들고 5초 뒤)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#1','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C6',1,'mc','auto','지시약이란 무엇인가요?',ARRAY['SC6-1-u1-X09']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C6","difficulty":1,"kind":"mc","stem":"지시약이란 무엇인가요?","options":[{"t":"용액의 성질에 따라 색깔 변화가 나타나는 물질","correct":true},{"t":"쇠붙이를 끌어당기는 물질","mis":"SC6-1-u1-X09"},{"t":"온도가 낮으면 어는 물질","mis":"SC6-1-u1-X09"},{"t":"어두운 곳에서 빛을 내는 물질","mis":"SC6-1-u1-X09"}],"explanation":["지시약의 뜻이에요.","색깔이 변해요.","성질에 따라 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#2','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C7',1,'mc','auto','산성 용액에 푸른색 리트머스 시험지를 대면 어떻게 되나요?',ARRAY['SC6-1-u1-X11']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C7","difficulty":1,"kind":"mc","stem":"산성 용액에 푸른색 리트머스 시험지를 대면 어떻게 되나요?","options":[{"t":"붉은색으로 변한다","correct":true},{"t":"변화가 없다","mis":"SC6-1-u1-X11"},{"t":"노란색으로 변한다","mis":"SC6-1-u1-X11"},{"t":"푸른색이 더 진해진다","mis":"SC6-1-u1-X11"}],"explanation":["푸른색 시험지예요.","산성에서 변해요.","붉은색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#3','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C7',1,'ox','auto','페놀프탈레인 용액은 염기성 용액에서 붉은색으로 변해요.',ARRAY['SC6-1-u1-X12']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C7","difficulty":1,"kind":"ox","stem":"페놀프탈레인 용액은 염기성 용액에서 붉은색으로 변해요.","answer":"O","reason_options":[{"t":"산성 용액에서는 변하지 않고 염기성 용액에서만 붉은색으로 변하기 때문에","correct":true},{"t":"페놀프탈레인 용액은 어느 용액에서나 붉어지기 때문에","mis":"SC6-1-u1-X12"}],"mis":"SC6-1-u1-X12","explanation":["페놀프탈레인 용액이에요.","염기성에서 변해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#4','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C9',1,'sa','auto','식초·레몬즙·묽은 염산처럼 푸른색 리트머스 시험지를 붉은색으로 변하게 하는 용액을 무엇이라고 하나요? (□□ 용액)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C9","difficulty":1,"kind":"sa","stem":"식초·레몬즙·묽은 염산처럼 푸른색 리트머스 시험지를 붉은색으로 변하게 하는 용액을 무엇이라고 하나요? (□□ 용액)","answer":["산성","산성 용액"],"explanation":["㉮ 무리예요.","두 글자예요.","산성 용액이에요."],"mis":"SC6-1-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#5','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C8',2,'mc','auto','붉은 양배추 용액이 붉은색 계열로 변하는 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X13']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C8","difficulty":2,"kind":"mc","stem":"붉은 양배추 용액이 붉은색 계열로 변하는 용액은 어느 것인가요?","options":[{"t":"레몬즙","correct":true},{"t":"빨랫비누 물","mis":"SC6-1-u1-X13"},{"t":"석회수","mis":"SC6-1-u1-X13"},{"t":"묽은 수산화 나트륨 용액","mis":"SC6-1-u1-X13"}],"explanation":["붉은색 계열은 산성이에요.","산성 용액을 찾아요.","레몬즙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#6','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C7',2,'match','auto','지시약과 염기성 용액에서의 변화를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u1-C7","difficulty":2,"kind":"match","stem":"지시약과 염기성 용액에서의 변화를 알맞게 이으세요.","pairs":[{"l":"붉은색 리트머스 시험지","r":"푸른색으로 변한다"},{"l":"페놀프탈레인 용액","r":"붉은색으로 변한다"},{"l":"푸른색 리트머스 시험지","r":"변화가 없다"},{"l":"붉은 양배추 용액","r":"푸른색이나 노란색 계열로 변한다"}],"mis":"SC6-1-u1-X11","explanation":["염기성 용액에서예요.","푸른 시험지는 그대로예요.","하나씩 이어요."],"asset":{"type":"passage","lines":["푸른색 리트머스 시험지 — ㉮ 무리: 붉은색으로 변함 · ㉯ 무리: 변화 없음","붉은색 리트머스 시험지 — ㉮ 무리: 변화 없음 · ㉯ 무리: 푸른색으로 변함","페놀프탈레인 용액 — ㉮ 무리: 변화 없음 · ㉯ 무리: 붉은색으로 변함","붉은 양배추 용액 — ㉮ 무리: 붉은색 계열 · ㉯ 무리: 푸른색이나 노란색 계열","㉮ 무리 — 식초, 레몬즙, 묽은 염산","㉯ 무리 — 빨랫비누 물, 석회수, 묽은 수산화 나트륨 용액"],"title":"지시약으로 여섯 용액을 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#7','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C9',2,'blank','auto','「지시약을 이용하면 용액을 산성 용액과 (    )으로 분류할 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X08','SC6-1-u1-X09']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C9","difficulty":2,"kind":"blank","stem":"「지시약을 이용하면 용액을 산성 용액과 (    )으로 분류할 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"염기성 용액","correct":true},{"t":"투명한 용액","mis":"SC6-1-u1-X08"},{"t":"색깔 있는 용액","mis":"SC6-1-u1-X08"},{"t":"차가운 용액","mis":"SC6-1-u1-X09"}],"explanation":["두 무리예요.","산성과 짝이에요.","염기성 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#8','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C6',2,'ox','auto','지시약은 리트머스 시험지 한 종류뿐이에요.',ARRAY['SC6-1-u1-X10']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C6","difficulty":2,"kind":"ox","stem":"지시약은 리트머스 시험지 한 종류뿐이에요.","answer":"X","reason_options":[{"t":"페놀프탈레인 용액, 붉은 양배추 용액 등 여러 가지가 있기 때문에","correct":true},{"t":"리트머스 시험지만 색깔이 변하기 때문에","mis":"SC6-1-u1-X10"}],"mis":"SC6-1-u1-X10","explanation":["실험에 쓴 지시약을 세요.","넷이었어요.","한 종류가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#9','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C8',2,'error','auto','붉은 양배추 용액을 관찰하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X14','SC6-1-u1-X04']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C8","difficulty":2,"kind":"error","stem":"붉은 양배추 용액을 관찰하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「교과서와 똑같은 색 하나를 찾아야 해.」","correct":true,"mis_target":"SC6-1-u1-X14"},{"t":"도겸 — 「비슷한 계열의 색으로 변했는지 보자.」","mis":"SC6-1-u1-X14"},{"t":"채원 — 「용액이 섞이지 않게 조심하자.」","mis":"SC6-1-u1-X04"}],"explanation":["농도에 따라 색이 조금씩 달라요.","계열로 봐요.","라희가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_basic#10','sci',6,1,'u1','L03','g6_1_sci_u1_L03_basic','lesson_basic','SC6-1-u1-C9',3,'mc','auto','석회수에 페놀프탈레인 용액을 떨어뜨렸더니 붉은색으로 변했어요. 석회수는 어떤 용액인가요?',ARRAY['SC6-1-u1-X15','SC6-1-u1-X09','SC6-1-u1-X08']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C9","difficulty":3,"kind":"mc","stem":"석회수에 페놀프탈레인 용액을 떨어뜨렸더니 붉은색으로 변했어요. 석회수는 어떤 용액인가요?","options":[{"t":"염기성 용액","correct":true},{"t":"산성 용액","mis":"SC6-1-u1-X15"},{"t":"지시약","mis":"SC6-1-u1-X09"},{"t":"색깔이 없으니 알 수 없다","mis":"SC6-1-u1-X08"}],"explanation":["붉어진 까닭을 따져요.","페놀프탈레인은 염기성에서 붉어요.","염기성 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#1','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C6',2,'sa','auto','어떤 용액을 만났을 때 그 용액의 성질에 따라 색깔 변화가 나타나는 물질을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C6","difficulty":2,"kind":"sa","stem":"어떤 용액을 만났을 때 그 용액의 성질에 따라 색깔 변화가 나타나는 물질을 세 글자로 쓰세요.","answer":["지시약"],"explanation":["리트머스 시험지도 이것이에요.","세 글자예요.","지시약이에요."],"mis":"SC6-1-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#2','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C9',2,'ox','auto','겉보기 성질로 구별하기 어려운 용액도 지시약으로 분류할 수 있어요.',ARRAY['SC6-1-u1-X08']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C9","difficulty":2,"kind":"ox","stem":"겉보기 성질로 구별하기 어려운 용액도 지시약으로 분류할 수 있어요.","answer":"O","reason_options":[{"t":"색깔이 없고 투명한 용액도 지시약의 색깔 변화로 나뉘기 때문에","correct":true},{"t":"색깔이 없는 용액에는 지시약을 쓸 수 없기 때문에","mis":"SC6-1-u1-X08"}],"mis":"SC6-1-u1-X08","explanation":["석회수와 묽은 염산을 떠올려요.","겉보기는 비슷해요.","지시약으로 나뉘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#3','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C9',3,'mc','auto','지시약으로 나눈 결과 염기성 용액끼리 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X15']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C9","difficulty":3,"kind":"mc","stem":"지시약으로 나눈 결과 염기성 용액끼리 모은 것은 어느 것인가요?","options":[{"t":"빨랫비누 물, 석회수, 묽은 수산화 나트륨 용액","correct":true},{"t":"식초, 레몬즙, 묽은 염산","mis":"SC6-1-u1-X15"},{"t":"식초, 석회수, 묽은 염산","mis":"SC6-1-u1-X15"},{"t":"레몬즙, 빨랫비누 물, 석회수","mis":"SC6-1-u1-X15"}],"explanation":["염기성은 붉은색 리트머스를 푸르게 해요.","세 용액이에요.","빨랫비누 물 무리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#4','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C7',3,'mc','auto','어떤 용액에서 붉은색 리트머스 시험지는 그대로이고 푸른색 리트머스 시험지는 붉은색으로 변했어요. 이 용액에 페놀프탈레인 용액을 떨어뜨리면 어떻게 될까요?',ARRAY['SC6-1-u1-X12','SC6-1-u1-X11','SC6-1-u1-X13']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C7","difficulty":3,"kind":"mc","stem":"어떤 용액에서 붉은색 리트머스 시험지는 그대로이고 푸른색 리트머스 시험지는 붉은색으로 변했어요. 이 용액에 페놀프탈레인 용액을 떨어뜨리면 어떻게 될까요?","options":[{"t":"변화가 없다","correct":true},{"t":"붉은색으로 변한다","mis":"SC6-1-u1-X12"},{"t":"푸른색으로 변한다","mis":"SC6-1-u1-X11"},{"t":"노란색 계열로 변한다","mis":"SC6-1-u1-X13"}],"explanation":["먼저 용액의 성질을 찾아요.","산성 용액이에요.","산성에서는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#5','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C9',3,'mc','auto','리트머스 시험지, 페놀프탈레인 용액, 붉은 양배추 용액으로 분류한 결과를 견주면 어떤가요?',ARRAY['SC6-1-u1-X16','SC6-1-u1-X10']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C9","difficulty":3,"kind":"mc","stem":"리트머스 시험지, 페놀프탈레인 용액, 붉은 양배추 용액으로 분류한 결과를 견주면 어떤가요?","options":[{"t":"지시약마다 색깔 변화는 달라도 분류한 결과는 같다","correct":true},{"t":"지시약마다 분류한 결과가 다르다","mis":"SC6-1-u1-X16"},{"t":"어떤 지시약이든 산성 용액에서 같은 색으로 변한다","mis":"SC6-1-u1-X10"},{"t":"붉은 양배추 용액으로만 나눌 수 있다","mis":"SC6-1-u1-X10"}],"explanation":["세 지시약의 무리를 견줘요.","같은 용액끼리 모였어요.","결과가 같아요."],"asset":{"type":"passage","lines":["푸른색 리트머스 시험지 — ㉮ 무리: 붉은색으로 변함 · ㉯ 무리: 변화 없음","붉은색 리트머스 시험지 — ㉮ 무리: 변화 없음 · ㉯ 무리: 푸른색으로 변함","페놀프탈레인 용액 — ㉮ 무리: 변화 없음 · ㉯ 무리: 붉은색으로 변함","붉은 양배추 용액 — ㉮ 무리: 붉은색 계열 · ㉯ 무리: 푸른색이나 노란색 계열","㉮ 무리 — 식초, 레몬즙, 묽은 염산","㉯ 무리 — 빨랫비누 물, 석회수, 묽은 수산화 나트륨 용액"],"title":"지시약으로 여섯 용액을 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#6','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C7',3,'error','auto','실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X12','SC6-1-u1-X11']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C7","difficulty":3,"kind":"error","stem":"실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「페놀프탈레인 용액은 식초에서 붉게 변해.」","correct":true,"mis_target":"SC6-1-u1-X12"},{"t":"지후 — 「붉은색 리트머스 시험지는 석회수에서 푸르게 변해.」","mis":"SC6-1-u1-X11"},{"t":"나연 — 「푸른색 리트머스 시험지는 레몬즙에서 붉게 변해.」","mis":"SC6-1-u1-X11"}],"explanation":["식초는 산성이에요.","페놀프탈레인은 산성에서 그대로예요.","하율이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#7','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C8',3,'mc','auto','같은 붉은 양배추 용액인데 모둠마다 색이 조금씩 달랐어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X15','SC6-1-u1-X14','SC6-1-u1-X09']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C8","difficulty":3,"kind":"mc","stem":"같은 붉은 양배추 용액인데 모둠마다 색이 조금씩 달랐어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"용액의 농도에 따라 색깔에 차이가 있기 때문에","correct":true},{"t":"산성과 염기성이 모둠마다 바뀌기 때문에","mis":"SC6-1-u1-X15"},{"t":"지시약은 색이 하나로 딱 정해져 있어 한 모둠만 맞았기 때문에","mis":"SC6-1-u1-X14"},{"t":"붉은 양배추 용액은 지시약이 아니기 때문에","mis":"SC6-1-u1-X09"}],"explanation":["같은 지시약이에요.","진하기가 달라요.","농도 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#8','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C9',4,'mc','auto','알 수 없는 용액에 붉은 양배추 용액을 떨어뜨렸더니 푸른색 계열로 변했어요. 이 용액에 붉은색 리트머스 시험지와 페놀프탈레인 용액을 쓰면 어떻게 될까요?',ARRAY['SC6-1-u1-X11','SC6-1-u1-X12','SC6-1-u1-X13']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C9","difficulty":4,"kind":"mc","stem":"알 수 없는 용액에 붉은 양배추 용액을 떨어뜨렸더니 푸른색 계열로 변했어요. 이 용액에 붉은색 리트머스 시험지와 페놀프탈레인 용액을 쓰면 어떻게 될까요?","options":[{"t":"붉은색 리트머스 시험지는 푸른색으로, 페놀프탈레인 용액은 붉은색으로 변한다","correct":true},{"t":"붉은색 리트머스 시험지는 그대로, 페놀프탈레인 용액은 붉은색으로 변한다","mis":"SC6-1-u1-X11"},{"t":"붉은색 리트머스 시험지는 푸른색으로 변하고, 페놀프탈레인 용액은 그대로이다","mis":"SC6-1-u1-X12"},{"t":"두 지시약 모두 변화가 없다","mis":"SC6-1-u1-X13"}],"explanation":["먼저 성질을 정해요.","염기성 용액이에요.","두 지시약 모두 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#9','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C9',4,'mc','auto','지시약 실험을 바르게 하는 방법을 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X04']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C9","difficulty":4,"kind":"mc","stem":"지시약 실험을 바르게 하는 방법을 모은 것은 어느 것인가요?","options":[{"t":"핀셋으로 시험지를 옮기고, 용액이 서로 섞이지 않게 하며, 실험복·보안경·실험용 장갑을 착용한다","correct":true},{"t":"맨손으로 시험지를 옮기고, 한 칸에 여러 용액을 섞어 본다","mis":"SC6-1-u1-X04"},{"t":"보안경은 빼고, 용액 냄새를 코를 대고 맡는다","mis":"SC6-1-u1-X04"},{"t":"색깔이 잘 보이도록 용액을 맛보며 확인한다","mis":"SC6-1-u1-X04"}],"explanation":["안전을 떠올려요.","섞이지 않게 해요.","보호 장비를 갖춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L03_challenge#10','sci',6,1,'u1','L03','g6_1_sci_u1_L03_challenge','lesson_challenge','SC6-1-u1-C9',4,'essay','teacher','색깔이 없고 투명한 석회수와 묽은 염산을 구별하려고 해요. 지시약 두 가지를 골라 각 용액에서 나타날 결과를 쓰고, 두 용액이 각각 어떤 성질의 용액인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C9","difficulty":4,"kind":"essay","stem":"색깔이 없고 투명한 석회수와 묽은 염산을 구별하려고 해요. 지시약 두 가지를 골라 각 용액에서 나타날 결과를 쓰고, 두 용액이 각각 어떤 성질의 용액인지 쓰세요.","answer_guide":{"answer":"예: 두 용액은 겉보기 성질이 비슷해 지시약을 쓴다. 푸른색 리트머스 시험지를 대면 묽은 염산에서는 붉은색으로 변하고 석회수에서는 변화가 없다. 페놀프탈레인 용액을 떨어뜨리면 석회수에서는 붉은색으로 변하고 묽은 염산에서는 변화가 없다. 따라서 묽은 염산은 산성 용액이고 석회수는 염기성 용액이다.","scoring_points":["지시약 두 가지를 골랐는가","두 용액에서의 결과를 바르게 썼는가","산성·염기성을 바르게 판단했는가"]},"explanation":["지시약을 골라요.","결과를 예상해요.","성질을 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_basic#1','sci',6,1,'u1','L04','g6_1_sci_u1_L04_basic','lesson_basic','SC6-1-u1-C10',1,'mc','auto','묽은 염산에 달걀 껍데기를 넣으면 어떻게 되나요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X18']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C10","difficulty":1,"kind":"mc","stem":"묽은 염산에 달걀 껍데기를 넣으면 어떻게 되나요?","options":[{"t":"기포가 발생하며 녹는다","correct":true},{"t":"아무 변화가 없다","mis":"SC6-1-u1-X17"},{"t":"녹아 흐물흐물해진다","mis":"SC6-1-u1-X18"},{"t":"푸른색으로 변한다","mis":"SC6-1-u1-X17"}],"explanation":["산성 용액이에요.","껍데기가 반응해요.","기포가 생기며 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_basic#2','sci',6,1,'u1','L04','g6_1_sci_u1_L04_basic','lesson_basic','SC6-1-u1-C11',1,'mc','auto','묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣으면 어떻게 되나요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X19','SC6-1-u1-X18']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C11","difficulty":1,"kind":"mc","stem":"묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣으면 어떻게 되나요?","options":[{"t":"시간이 지나면서 녹아 흐물흐물해진다","correct":true},{"t":"기포가 발생하며 녹는다","mis":"SC6-1-u1-X17"},{"t":"곧바로 딱딱해진다","mis":"SC6-1-u1-X19"},{"t":"붉은색으로 변한다","mis":"SC6-1-u1-X18"}],"explanation":["염기성 용액이에요.","흰자가 반응해요.","시간이 지나며 흐물흐물해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_basic#3','sci',6,1,'u1','L04','g6_1_sci_u1_L04_basic','lesson_basic','SC6-1-u1-C10',1,'ox','auto','산성 용액은 조개껍데기를 녹여요.',ARRAY['SC6-1-u1-X18']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C10","difficulty":1,"kind":"ox","stem":"산성 용액은 조개껍데기를 녹여요.","answer":"O","reason_options":[{"t":"묽은 염산에 넣으면 조개껍데기가 기포를 내며 녹았기 때문에","correct":true},{"t":"조개껍데기는 염기성 용액에서만 녹기 때문에","mis":"SC6-1-u1-X18"}],"mis":"SC6-1-u1-X18","explanation":["결과를 읽어요.","묽은 염산에서 녹았어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["묽은 염산 — 달걀 껍데기·조개껍데기: 기포가 발생하며 녹음","묽은 염산 — 삶은 달걀흰자·삶은 닭 가슴살: 변화 없음","묽은 수산화 나트륨 용액 — 달걀 껍데기·조개껍데기: 변화 없음","묽은 수산화 나트륨 용액 — 삶은 달걀흰자·삶은 닭 가슴살:","　　시간이 지나면서 녹아 흐물흐물해짐"],"title":"두 용액에 네 가지 물질을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_basic#4','sci',6,1,'u1','L04','g6_1_sci_u1_L04_basic','lesson_basic','SC6-1-u1-C10',1,'sa','auto','달걀 껍데기와 조개껍데기의 주요 성분은 무엇인가요? (□□ □□)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C10","difficulty":1,"kind":"sa","stem":"달걀 껍데기와 조개껍데기의 주요 성분은 무엇인가요? (□□ □□)","answer":["탄산 칼슘","탄산칼슘"],"explanation":["산성 용액과 반응해요.","네 글자예요.","탄산 칼슘이에요."],"mis":"SC6-1-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_basic#5','sci',6,1,'u1','L04','g6_1_sci_u1_L04_basic','lesson_basic','SC6-1-u1-C10',2,'match','auto','물질·성분과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u1-C10","difficulty":2,"kind":"match","stem":"물질·성분과 알맞은 설명을 이으세요.","pairs":[{"l":"달걀 껍데기","r":"주요 성분이 탄산 칼슘이다"},{"l":"삶은 닭 가슴살","r":"주요 성분이 단백질이다"},{"l":"탄산 칼슘","r":"산성 용액과 반응한다"},{"l":"단백질","r":"염기성 용액과 반응한다"}],"mis":"SC6-1-u1-X20","explanation":["물질의 성분을 먼저 이어요.","성분과 용액을 이어요.","두 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
