INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#2','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C12',2,'ox','auto','이 실험은 다른 실험보다 좀 더 진한 용액을 써서 안전 수칙을 더 철저히 지켜요.',ARRAY['SC6-1-u1-X04']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C12","difficulty":2,"kind":"ox","stem":"이 실험은 다른 실험보다 좀 더 진한 용액을 써서 안전 수칙을 더 철저히 지켜요.","answer":"O","reason_options":[{"t":"진한 용액은 피부나 눈에 닿으면 더 위험하기 때문에","correct":true},{"t":"용액이 묽어서 맨손으로 만져도 되기 때문에","mis":"SC6-1-u1-X04"}],"mis":"SC6-1-u1-X04","explanation":["용액의 진하기를 떠올려요.","더 조심해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#3','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C10',3,'mc','auto','묽은 염산에 넣었을 때 변화가 없는 것끼리 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X20']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C10","difficulty":3,"kind":"mc","stem":"묽은 염산에 넣었을 때 변화가 없는 것끼리 모은 것은 어느 것인가요?","options":[{"t":"삶은 달걀흰자, 삶은 닭 가슴살","correct":true},{"t":"달걀 껍데기, 조개껍데기","mis":"SC6-1-u1-X17"},{"t":"달걀 껍데기, 삶은 닭 가슴살","mis":"SC6-1-u1-X20"},{"t":"조개껍데기, 삶은 달걀흰자","mis":"SC6-1-u1-X20"}],"explanation":["산성 용액은 껍데기를 녹여요.","단백질은 그대로예요.","흰자와 닭 가슴살이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#4','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C11',3,'mc','auto','묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣고 바로 보았더니 아직 그대로예요. 어떻게 하면 좋을까요?',ARRAY['SC6-1-u1-X19','SC6-1-u1-X17','SC6-1-u1-X04']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C11","difficulty":3,"kind":"mc","stem":"묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣고 바로 보았더니 아직 그대로예요. 어떻게 하면 좋을까요?","options":[{"t":"시간을 두고 더 지켜본다","correct":true},{"t":"염기성 용액은 단백질과 반응하지 않는다고 결론 짓는다","mis":"SC6-1-u1-X19"},{"t":"흰자를 묽은 염산으로 옮겨 넣는다","mis":"SC6-1-u1-X17"},{"t":"흰자를 꺼내 맛을 본다","mis":"SC6-1-u1-X04"}],"explanation":["반응 시간을 떠올려요.","오래 걸릴 수 있어요.","더 지켜봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#5','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C10',3,'error','auto','두 용액의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X18','SC6-1-u1-X17']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C10","difficulty":3,"kind":"error","stem":"두 용액의 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「조개껍데기는 염기성 용액에서 기포를 내며 녹아.」","correct":true,"mis_target":"SC6-1-u1-X18"},{"t":"아린 — 「달걀 껍데기는 산성 용액에서 녹아.」","mis":"SC6-1-u1-X17"},{"t":"도하 — 「삶은 달걀흰자는 염기성 용액에서 흐물흐물해져.」","mis":"SC6-1-u1-X18"}],"explanation":["껍데기를 녹인 용액이에요.","산성 용액이에요.","시우가 잘못 말했어요."],"asset":{"type":"passage","lines":["묽은 염산 — 달걀 껍데기·조개껍데기: 기포가 발생하며 녹음","묽은 염산 — 삶은 달걀흰자·삶은 닭 가슴살: 변화 없음","묽은 수산화 나트륨 용액 — 달걀 껍데기·조개껍데기: 변화 없음","묽은 수산화 나트륨 용액 — 삶은 달걀흰자·삶은 닭 가슴살:","　　시간이 지나면서 녹아 흐물흐물해짐"],"title":"두 용액에 네 가지 물질을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#6','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C10',3,'mc','auto','두 용액이 서로 다른 물질을 녹이는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X20','SC6-1-u1-X17']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C10","difficulty":3,"kind":"mc","stem":"두 용액이 서로 다른 물질을 녹이는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산성 용액은 탄산 칼슘과, 염기성 용액은 단백질과 반응하기 때문에","correct":true},{"t":"산성 용액은 단백질과, 염기성 용액은 탄산 칼슘과 반응하기 때문에","mis":"SC6-1-u1-X20"},{"t":"두 용액 모두 같은 성분과 반응하기 때문에","mis":"SC6-1-u1-X20"},{"t":"껍데기가 흰자보다 단단하기 때문에","mis":"SC6-1-u1-X17"}],"explanation":["성분을 떠올려요.","껍데기와 흰자는 성분이 달라요.","반응하는 성분이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#7','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C12',3,'mc','auto','두 용액의 성질을 공정하게 견주려면 같게 해야 할 것은 어느 것인가요?',ARRAY['SC6-1-u1-X21']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C12","difficulty":3,"kind":"mc","stem":"두 용액의 성질을 공정하게 견주려면 같게 해야 할 것은 어느 것인가요?","options":[{"t":"두 용액에 넣는 물질의 종류와 크기","correct":true},{"t":"두 용액의 이름","mis":"SC6-1-u1-X21"},{"t":"한쪽 용액만 더 오래 관찰하는 것","mis":"SC6-1-u1-X21"},{"t":"용액마다 서로 다른 물질을 넣는 것","mis":"SC6-1-u1-X21"}],"explanation":["다르게 할 것은 용액뿐이에요.","물질은 같게 해요.","종류와 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#8','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C11',4,'mc','auto','알 수 없는 용액 ㉠에 조개껍데기를 넣었더니 변화가 없었고, 삶은 달걀흰자는 시간이 지나면서 흐물흐물해졌어요. ㉠은 어떤 용액인가요?',ARRAY['SC6-1-u1-X18','SC6-1-u1-X20','SC6-1-u1-X19']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C11","difficulty":4,"kind":"mc","stem":"알 수 없는 용액 ㉠에 조개껍데기를 넣었더니 변화가 없었고, 삶은 달걀흰자는 시간이 지나면서 흐물흐물해졌어요. ㉠은 어떤 용액인가요?","options":[{"t":"염기성 용액","correct":true},{"t":"산성 용액","mis":"SC6-1-u1-X18"},{"t":"껍데기와 흰자를 모두 녹이는 용액","mis":"SC6-1-u1-X20"},{"t":"알 수 없다","mis":"SC6-1-u1-X19"}],"explanation":["두 결과를 함께 봐요.","단백질을 녹였어요.","염기성 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#9','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C10',4,'mc','auto','실험 결과를 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u1-X20','SC6-1-u1-X17','SC6-1-u1-X19']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C10","difficulty":4,"kind":"mc","stem":"실험 결과를 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"산성 용액은 껍데기류를, 염기성 용액은 단백질이 든 것을 녹이므로 두 용액은 서로 다른 성질이 있다","correct":true},{"t":"두 용액은 같은 물질을 녹이므로 성질이 같다","mis":"SC6-1-u1-X20"},{"t":"산성 용액은 넣은 물질을 모두 녹인다","mis":"SC6-1-u1-X17"},{"t":"염기성 용액은 아무것도 녹이지 못한다","mis":"SC6-1-u1-X19"}],"explanation":["네 물질의 결과를 모아요.","녹인 것이 달라요.","성질이 서로 달라요."],"asset":{"type":"passage","lines":["묽은 염산 — 달걀 껍데기·조개껍데기: 기포가 발생하며 녹음","묽은 염산 — 삶은 달걀흰자·삶은 닭 가슴살: 변화 없음","묽은 수산화 나트륨 용액 — 달걀 껍데기·조개껍데기: 변화 없음","묽은 수산화 나트륨 용액 — 삶은 달걀흰자·삶은 닭 가슴살:","　　시간이 지나면서 녹아 흐물흐물해짐"],"title":"두 용액에 네 가지 물질을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L04_challenge#10','sci',6,1,'u1','L04','g6_1_sci_u1_L04_challenge','lesson_challenge','SC6-1-u1-C11',4,'essay','teacher','두 용액에 네 가지 물질을 넣은 결과를 용액별로 정리하고, 두 용액이 서로 다른 물질을 녹이는 까닭을 주요 성분으로 설명하세요. 결과를 관찰할 때 주의할 점도 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C11","difficulty":4,"kind":"essay","stem":"두 용액에 네 가지 물질을 넣은 결과를 용액별로 정리하고, 두 용액이 서로 다른 물질을 녹이는 까닭을 주요 성분으로 설명하세요. 결과를 관찰할 때 주의할 점도 하나 쓰세요.","answer_guide":{"answer":"예: 묽은 염산에서는 달걀 껍데기와 조개껍데기가 기포가 발생하며 녹았고, 삶은 달걀흰자와 삶은 닭 가슴살은 변화가 없었다. 묽은 수산화 나트륨 용액에서는 삶은 달걀흰자와 삶은 닭 가슴살이 시간이 지나면서 녹아 흐물흐물해졌고, 껍데기류는 변화가 없었다. 껍데기의 주요 성분은 탄산 칼슘으로 산성 용액과 반응하고, 흰자와 닭 가슴살의 주요 성분은 단백질로 염기성 용액과 반응하기 때문이다. 단백질과의 반응은 오래 걸릴 수 있으므로 시간을 두고 관찰해야 한다.","scoring_points":["용액별 결과를 바르게 썼는가","탄산 칼슘·단백질로 까닭을 설명했는가","시간이나 안전에 관한 주의점을 썼는가"]},"explanation":["결과를 용액별로 써요.","성분으로 설명해요.","주의점을 써요."],"asset":{"type":"passage","lines":["묽은 염산 — 달걀 껍데기·조개껍데기: 기포가 발생하며 녹음","묽은 염산 — 삶은 달걀흰자·삶은 닭 가슴살: 변화 없음","묽은 수산화 나트륨 용액 — 달걀 껍데기·조개껍데기: 변화 없음","묽은 수산화 나트륨 용액 — 삶은 달걀흰자·삶은 닭 가슴살:","　　시간이 지나면서 녹아 흐물흐물해짐"],"title":"두 용액에 네 가지 물질을 넣은 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#1','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C14',1,'mc','auto','산성 용액에 염기성 용액을 계속 넣으면 어떻게 되나요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X24']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C14","difficulty":1,"kind":"mc","stem":"산성 용액에 염기성 용액을 계속 넣으면 어떻게 되나요?","options":[{"t":"산성이 점점 약해지다가 염기성으로 변한다","correct":true},{"t":"성질이 변하지 않는다","mis":"SC6-1-u1-X23"},{"t":"산성이 점점 더 강해진다","mis":"SC6-1-u1-X23"},{"t":"곧바로 물이 된다","mis":"SC6-1-u1-X24"}],"explanation":["반대 성질을 넣어요.","처음 성질이 약해져요.","염기성으로 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#2','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C13',1,'mc','auto','붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 넣을수록 색은 어떻게 변하나요?',ARRAY['SC6-1-u1-X22','SC6-1-u1-X23']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C13","difficulty":1,"kind":"mc","stem":"붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 넣을수록 색은 어떻게 변하나요?","options":[{"t":"붉은색 계열에서 노란색 계열로 변한다","correct":true},{"t":"노란색 계열에서 붉은색 계열로 변한다","mis":"SC6-1-u1-X22"},{"t":"붉은색 계열 그대로이다","mis":"SC6-1-u1-X23"},{"t":"노란색 계열 그대로이다","mis":"SC6-1-u1-X23"}],"explanation":["처음은 산성이에요.","염기성을 넣어요.","노란색 계열 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#3','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C14',1,'ox','auto','산성 용액과 염기성 용액을 섞으면 용액의 성질이 변해요.',ARRAY['SC6-1-u1-X23']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C14","difficulty":1,"kind":"ox","stem":"산성 용액과 염기성 용액을 섞으면 용액의 성질이 변해요.","answer":"O","reason_options":[{"t":"지시약의 색깔이 변하는 것으로 성질이 변함을 알 수 있기 때문에","correct":true},{"t":"두 용액은 섞어도 처음 성질 그대로이기 때문에","mis":"SC6-1-u1-X23"}],"mis":"SC6-1-u1-X23","explanation":["색이 변했어요.","성질도 변했어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#4','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C13',1,'sa','auto','섞을 때의 성질 변화를 알아보려고 넣은 지시약은 무엇인가요? (붉은 □□□ 용액)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C13","difficulty":1,"kind":"sa","stem":"섞을 때의 성질 변화를 알아보려고 넣은 지시약은 무엇인가요? (붉은 □□□ 용액)","answer":["양배추","붉은 양배추","붉은 양배추 용액"],"explanation":["색 계열로 봐요.","채소로 만들어요.","붉은 양배추 용액이에요."],"mis":"SC6-1-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#5','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C14',2,'mc','auto','산성 용액을 계속 넣을 때 염기성 용액의 성질 변화로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X24']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C14","difficulty":2,"kind":"mc","stem":"산성 용액을 계속 넣을 때 염기성 용액의 성질 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"염기성이 점점 약해지다가 산성으로 변한다","correct":true},{"t":"염기성이 점점 더 강해진다","mis":"SC6-1-u1-X23"},{"t":"곧바로 딱딱하게 굳는다","mis":"SC6-1-u1-X24"},{"t":"처음 성질 그대로 남는다","mis":"SC6-1-u1-X23"}],"explanation":["반대 방향이에요.","염기성이 약해져요.","산성으로 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#6','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C13',2,'match','auto','실험과 색의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u1-C13","difficulty":2,"kind":"match","stem":"실험과 색의 모습을 알맞게 이으세요.","pairs":[{"l":"묽은 염산에 묽은 수산화 나트륨 용액을 넣음","r":"붉은색 계열에서 노란색 계열로 변한다"},{"l":"묽은 수산화 나트륨 용액에 묽은 염산을 넣음","r":"노란색 계열에서 붉은색 계열로 변한다"},{"l":"처음의 묽은 염산","r":"붉은 양배추 용액에서 붉은색 계열을 띤다"},{"l":"처음의 묽은 수산화 나트륨 용액","r":"붉은 양배추 용액에서 노란색 계열을 띤다"}],"mis":"SC6-1-u1-X22","explanation":["처음 색부터 이어요.","넣는 쪽으로 색이 가요.","방향을 확인해요."],"asset":{"type":"passage","lines":["㉮ 붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 조금씩 넣음","　　처음: 붉은색 계열 → 넣을수록 → 마지막: 노란색 계열","㉯ 붉은 양배추 용액을 넣은 묽은 수산화 나트륨 용액에 묽은 염산을 조금씩 넣음","　　처음: 노란색 계열 → 넣을수록 → 마지막: 붉은색 계열"],"title":"섞으며 붉은 양배추 용액의 색깔 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#7','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C14',2,'blank','auto','「산성 용액과 염기성 용액을 섞으면 더 많이 넣은 용액의 (    )을 나타내게 됩니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X25']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C14","difficulty":2,"kind":"blank","stem":"「산성 용액과 염기성 용액을 섞으면 더 많이 넣은 용액의 (    )을 나타내게 됩니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"성질","correct":true},{"t":"이름","mis":"SC6-1-u1-X25"},{"t":"양","mis":"SC6-1-u1-X25"},{"t":"온도","mis":"SC6-1-u1-X25"}],"explanation":["무엇이 남을까요?","많이 넣은 쪽이에요.","성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#8','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C13',2,'ox','auto','섞는 동안 붉은 양배추 용액의 색이 변한 것은 용액의 성질이 변하고 있다는 뜻이에요.',ARRAY['SC6-1-u1-X23']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C13","difficulty":2,"kind":"ox","stem":"섞는 동안 붉은 양배추 용액의 색이 변한 것은 용액의 성질이 변하고 있다는 뜻이에요.","answer":"O","reason_options":[{"t":"붉은 양배추 용액은 성질에 따라 색이 달라지는 지시약이기 때문에","correct":true},{"t":"색은 성질과 관계없이 그냥 섞여서 변한 것이기 때문에","mis":"SC6-1-u1-X23"}],"mis":"SC6-1-u1-X23","explanation":["지시약의 뜻을 떠올려요.","성질에 따라 변해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#9','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C14',2,'error','auto','섞기 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X25']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C14","difficulty":2,"kind":"error","stem":"섞기 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「두 용액을 섞으면 두 성질이 모두 더 강해져.」","correct":true,"mis_target":"SC6-1-u1-X23"},{"t":"보람 — 「산성 용액에 염기성 용액을 넣으면 산성이 약해져.」","mis":"SC6-1-u1-X23"},{"t":"세진 — 「많이 넣은 쪽 용액의 성질을 나타내.」","mis":"SC6-1-u1-X25"}],"explanation":["처음 성질은 어떻게 되나요?","약해져요.","윤호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_basic#10','sci',6,1,'u1','L05','g6_1_sci_u1_L05_basic','lesson_basic','SC6-1-u1-C15',3,'mc','auto','산성이 강해진 흙에서 식물이 잘 자라게 하려고 뿌리는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X26','SC6-1-u1-X23']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C15","difficulty":3,"kind":"mc","stem":"산성이 강해진 흙에서 식물이 잘 자라게 하려고 뿌리는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"염기성을 띤 석회 가루","correct":true},{"t":"산성을 띤 용액","mis":"SC6-1-u1-X26"},{"t":"산성을 더 강하게 하는 물질","mis":"SC6-1-u1-X26"},{"t":"아무것도 뿌리지 않는다","mis":"SC6-1-u1-X23"}],"explanation":["흙의 산성을 약하게 해요.","반대 성질이 필요해요.","석회 가루예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#1','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C14',2,'sa','auto','「산성 용액에 염기성 용액을 계속 넣으면 산성이 점점 약해지다가 □□□ 용액으로 변합니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C14","difficulty":2,"kind":"sa","stem":"「산성 용액에 염기성 용액을 계속 넣으면 산성이 점점 약해지다가 □□□ 용액으로 변합니다.」 □□□에 알맞은 말을 쓰세요.","answer":["염기성"],"explanation":["넣은 쪽 성질이에요.","세 글자예요.","염기성이에요."],"mis":"SC6-1-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#2','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C15',2,'ox','auto','운반 차량에서 염산이 새어 나왔을 때 염기성을 띤 석회 가루를 뿌려 산성을 약하게 해요.',ARRAY['SC6-1-u1-X26']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C15","difficulty":2,"kind":"ox","stem":"운반 차량에서 염산이 새어 나왔을 때 염기성을 띤 석회 가루를 뿌려 산성을 약하게 해요.","answer":"O","reason_options":[{"t":"산성과 염기성이 만나면 산성이 약해지는 성질을 이용하기 때문에","correct":true},{"t":"산성 물질을 더 뿌려야 산성이 약해지기 때문에","mis":"SC6-1-u1-X26"}],"mis":"SC6-1-u1-X26","explanation":["염산은 산성이에요.","반대 성질을 뿌려요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#3','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C13',3,'mc','auto','붉은 양배추 용액을 넣은 묽은 수산화 나트륨 용액에 묽은 염산을 계속 넣었더니 노란색 계열에서 붉은색 계열로 변했어요. 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X24']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C13","difficulty":3,"kind":"mc","stem":"붉은 양배추 용액을 넣은 묽은 수산화 나트륨 용액에 묽은 염산을 계속 넣었더니 노란색 계열에서 붉은색 계열로 변했어요. 알 수 있는 것은 어느 것인가요?","options":[{"t":"염기성이 약해지다가 산성으로 변했다","correct":true},{"t":"용액의 성질은 변하지 않았다","mis":"SC6-1-u1-X23"},{"t":"염기성이 점점 더 강해졌다","mis":"SC6-1-u1-X23"},{"t":"곧바로 물로 변했다","mis":"SC6-1-u1-X24"}],"explanation":["처음과 마지막 색을 봐요.","붉은색 계열은 산성이에요.","산성으로 변했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#4','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C14',3,'mc','auto','묽은 염산에 묽은 수산화 나트륨 용액을 아주 많이 넣으면 용액은 마지막에 어떻게 되나요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X24']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C14","difficulty":3,"kind":"mc","stem":"묽은 염산에 묽은 수산화 나트륨 용액을 아주 많이 넣으면 용액은 마지막에 어떻게 되나요?","options":[{"t":"염기성으로 변한다","correct":true},{"t":"산성이 그대로 남는다","mis":"SC6-1-u1-X23"},{"t":"산성이 더 강해진다","mis":"SC6-1-u1-X23"},{"t":"용액이 모두 사라진다","mis":"SC6-1-u1-X24"}],"explanation":["넣은 쪽이 더 많아요.","많이 넣은 쪽 성질이에요.","염기성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#5','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C13',3,'error','auto','색 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X22']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C13","difficulty":3,"kind":"error","stem":"색 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연우 — 「묽은 염산에 묽은 수산화 나트륨 용액을 넣으니 노란색에서 붉은색이 됐어.」","correct":true,"mis_target":"SC6-1-u1-X22"},{"t":"다은 — 「처음 묽은 염산은 붉은색 계열이었어.」","mis":"SC6-1-u1-X22"},{"t":"승호 — 「넣을수록 노란색 계열 쪽으로 바뀌었어.」","mis":"SC6-1-u1-X22"}],"explanation":["처음 색을 떠올려요.","산성은 붉은색 계열이에요.","연우가 거꾸로 말했어요."],"asset":{"type":"passage","lines":["㉮ 붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 조금씩 넣음","　　처음: 붉은색 계열 → 넣을수록 → 마지막: 노란색 계열","㉯ 붉은 양배추 용액을 넣은 묽은 수산화 나트륨 용액에 묽은 염산을 조금씩 넣음","　　처음: 노란색 계열 → 넣을수록 → 마지막: 붉은색 계열"],"title":"섞으며 붉은 양배추 용액의 색깔 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#6','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C14',3,'mc','auto','반대 용액을 한꺼번에 붓지 않고 조금씩 넣으며 관찰하는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X25','SC6-1-u1-X24','SC6-1-u1-X23']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C14","difficulty":3,"kind":"mc","stem":"반대 용액을 한꺼번에 붓지 않고 조금씩 넣으며 관찰하는 까닭은 무엇인가요?","options":[{"t":"넣는 양에 따라 색이 차례로 변하는 모습을 관찰하려고","correct":true},{"t":"색은 넣는 양과 관계없기 때문에","mis":"SC6-1-u1-X25"},{"t":"용액을 빨리 없애려고","mis":"SC6-1-u1-X24"},{"t":"성질이 변하지 않음을 보여 주려고","mis":"SC6-1-u1-X23"}],"explanation":["조금씩 넣는 까닭이에요.","변하는 과정을 봐요.","차례로 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#7','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C15',3,'mc','auto','두 용액을 섞을 때의 성질 변화를 이용한 예는 어느 것인가요?',ARRAY['SC6-1-u1-X26']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C15","difficulty":3,"kind":"mc","stem":"두 용액을 섞을 때의 성질 변화를 이용한 예는 어느 것인가요?","options":[{"t":"산성이 강해진 흙에 석회 가루를 뿌린다","correct":true},{"t":"산성이 강한 흙에 산성 용액을 더 뿌린다","mis":"SC6-1-u1-X26"},{"t":"염산이 샌 곳에 산성 물질을 붓는다","mis":"SC6-1-u1-X26"},{"t":"석회 가루를 뿌려 흙을 더 산성으로 만든다","mis":"SC6-1-u1-X26"}],"explanation":["반대 성질을 섞어요.","석회 가루는 염기성이에요.","흙에 뿌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#8','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C14',4,'mc','auto','두 섞기 실험의 결과로 가장 알맞은 결론은 어느 것인가요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X25','SC6-1-u1-X24']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C14","difficulty":4,"kind":"mc","stem":"두 섞기 실험의 결과로 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"두 용액을 섞으면 처음의 성질이 점점 약해지고, 계속 넣으면 넣은 용액의 성질로 변한다","correct":true},{"t":"두 용액은 섞어도 처음의 성질을 그대로 지닌다","mis":"SC6-1-u1-X23"},{"t":"섞으면 언제나 산성이 된다","mis":"SC6-1-u1-X25"},{"t":"섞으면 언제나 곧바로 물이 된다","mis":"SC6-1-u1-X24"}],"explanation":["두 실험을 함께 봐요.","처음 성질이 약해져요.","넣은 쪽 성질로 가요."],"asset":{"type":"passage","lines":["㉮ 붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 조금씩 넣음","　　처음: 붉은색 계열 → 넣을수록 → 마지막: 노란색 계열","㉯ 붉은 양배추 용액을 넣은 묽은 수산화 나트륨 용액에 묽은 염산을 조금씩 넣음","　　처음: 노란색 계열 → 넣을수록 → 마지막: 붉은색 계열"],"title":"섞으며 붉은 양배추 용액의 색깔 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#9','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C13',4,'mc','auto','㉮ 실험의 처음 용액과 마지막 용액의 성질을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X22','SC6-1-u1-X23']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C13","difficulty":4,"kind":"mc","stem":"㉮ 실험의 처음 용액과 마지막 용액의 성질을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"처음 산성 — 마지막 염기성","correct":true},{"t":"처음 염기성 — 마지막 산성","mis":"SC6-1-u1-X22"},{"t":"처음 산성 — 마지막 산성","mis":"SC6-1-u1-X23"},{"t":"처음 염기성 — 마지막 염기성","mis":"SC6-1-u1-X23"}],"explanation":["처음 색을 봐요.","마지막 색을 봐요.","붉은색 계열에서 노란색 계열이에요."],"asset":{"type":"passage","lines":["㉮ 붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 조금씩 넣음","　　처음: 붉은색 계열 → 넣을수록 → 마지막: 노란색 계열","㉯ 붉은 양배추 용액을 넣은 묽은 수산화 나트륨 용액에 묽은 염산을 조금씩 넣음","　　처음: 노란색 계열 → 넣을수록 → 마지막: 붉은색 계열"],"title":"섞으며 붉은 양배추 용액의 색깔 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L05_challenge#10','sci',6,1,'u1','L05','g6_1_sci_u1_L05_challenge','lesson_challenge','SC6-1-u1-C14',4,'essay','teacher','두 섞기 실험(㉮·㉯)에서 붉은 양배추 용액의 색이 어떻게 변했는지 쓰고, 이 결과로 알 수 있는 용액의 성질 변화를 쓰세요. 이 성질 변화를 우리 생활에서 이용하는 예도 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C14","difficulty":4,"kind":"essay","stem":"두 섞기 실험(㉮·㉯)에서 붉은 양배추 용액의 색이 어떻게 변했는지 쓰고, 이 결과로 알 수 있는 용액의 성질 변화를 쓰세요. 이 성질 변화를 우리 생활에서 이용하는 예도 하나 쓰세요.","answer_guide":{"answer":"예: ㉮ 묽은 염산에 묽은 수산화 나트륨 용액을 넣을수록 붉은색 계열에서 노란색 계열로 변했다. ㉯ 묽은 수산화 나트륨 용액에 묽은 염산을 넣을수록 노란색 계열에서 붉은색 계열로 변했다. 산성 용액에 염기성 용액을 계속 넣으면 산성이 약해지다가 염기성으로 변하고, 반대로 넣으면 염기성이 약해지다가 산성으로 변한다. 생활에서는 산성이 강해진 흙에 염기성을 띤 석회 가루를 뿌려 식물이 잘 자라게 한다.","scoring_points":["두 실험의 색 변화를 바르게 썼는가","성질이 약해지다가 반대 성질로 변함을 썼는가","생활 속 이용 예를 썼는가"]},"explanation":["색 변화를 써요.","성질 변화를 써요.","이용 예를 들어요."],"asset":{"type":"passage","lines":["㉮ 붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 조금씩 넣음","　　처음: 붉은색 계열 → 넣을수록 → 마지막: 노란색 계열","㉯ 붉은 양배추 용액을 넣은 묽은 수산화 나트륨 용액에 묽은 염산을 조금씩 넣음","　　처음: 노란색 계열 → 넣을수록 → 마지막: 붉은색 계열"],"title":"섞으며 붉은 양배추 용액의 색깔 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#1','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C16',1,'mc','auto','생선을 손질한 도마의 비린내를 약하게 하려고 닦을 때 쓰는 것은 어느 것인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C16","difficulty":1,"kind":"mc","stem":"생선을 손질한 도마의 비린내를 약하게 하려고 닦을 때 쓰는 것은 어느 것인가요?","options":[{"t":"식초","correct":true},{"t":"제산제","mis":"SC6-1-u1-X27"},{"t":"하수구 세정제","mis":"SC6-1-u1-X27"},{"t":"욕실 청소용 표백제","mis":"SC6-1-u1-X27"}],"explanation":["비린내는 염기성이에요.","산성 용액을 써요.","식초예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#2','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C17',1,'mc','auto','속이 쓰릴 때 먹는 염기성 물질은 어느 것인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C17","difficulty":1,"kind":"mc","stem":"속이 쓰릴 때 먹는 염기성 물질은 어느 것인가요?","options":[{"t":"제산제","correct":true},{"t":"구연산 용액","mis":"SC6-1-u1-X27"},{"t":"레몬즙","mis":"SC6-1-u1-X27"},{"t":"식초","mis":"SC6-1-u1-X27"}],"explanation":["위액은 산성이에요.","염기성 약이에요.","제산제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#3','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C16',1,'ox','auto','산성 용액과 염기성 용액은 실험실에서만 쓰여요.',ARRAY['SC6-1-u1-X29']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C16","difficulty":1,"kind":"ox","stem":"산성 용액과 염기성 용액은 실험실에서만 쓰여요.","answer":"X","reason_options":[{"t":"요리·청소·약 등 우리 생활에서 다양하게 이용되기 때문에","correct":true},{"t":"위험해서 생활에서는 쓰지 않기 때문에","mis":"SC6-1-u1-X29"}],"mis":"SC6-1-u1-X29","explanation":["우리 집을 떠올려요.","식초도 산성이에요.","실험실에서만은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#4','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C17',1,'sa','auto','위에서 나온 산성 물질을 약하게 해 속 쓰림을 줄이는 약을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C17","difficulty":1,"kind":"sa","stem":"위에서 나온 산성 물질을 약하게 해 속 쓰림을 줄이는 약을 세 글자로 쓰세요.","answer":["제산제"],"explanation":["염기성 약이에요.","세 글자예요.","제산제예요."],"mis":"SC6-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#5','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C17',2,'match','auto','용액과 이용하는 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u1-C17","difficulty":2,"kind":"match","stem":"용액과 이용하는 예를 알맞게 이으세요.","pairs":[{"l":"욕실 청소용 표백제","r":"욕실의 때와 세균을 없앤다"},{"l":"레몬즙","r":"음식에 신맛을 낸다"},{"l":"하수구 세정제","r":"막힌 하수구의 머리카락을 없앤다"},{"l":"제산제","r":"속 쓰림을 약하게 한다"}],"mis":"SC6-1-u1-X27","explanation":["청소·요리·약을 가려요.","신맛은 레몬즙이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#6','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C16',2,'mc','auto','변기의 때를 없앨 때 변기 청소용 세제 대신 쓸 수 있는 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X28']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C16","difficulty":2,"kind":"mc","stem":"변기의 때를 없앨 때 변기 청소용 세제 대신 쓸 수 있는 용액은 어느 것인가요?","options":[{"t":"구연산 용액","correct":true},{"t":"빨랫비누 물","mis":"SC6-1-u1-X28"},{"t":"제산제","mis":"SC6-1-u1-X28"},{"t":"제빵 소다 용액","mis":"SC6-1-u1-X28"}],"explanation":["변기의 때는 염기성이에요.","산성 용액을 찾아요.","구연산 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#7','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C18',2,'blank','auto','「없애려는 물질과 (    ) 성질의 용액을 이용하면 서로 반응하여 성질이 약해집니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X28']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C18","difficulty":2,"kind":"blank","stem":"「없애려는 물질과 (    ) 성질의 용액을 이용하면 서로 반응하여 성질이 약해집니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"반대되는","correct":true},{"t":"같은","mis":"SC6-1-u1-X28"},{"t":"색깔이 있는","mis":"SC6-1-u1-X28"},{"t":"더 차가운","mis":"SC6-1-u1-X28"}],"explanation":["비린내와 식초를 떠올려요.","염기성과 산성이에요.","반대되는 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#8','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C18',2,'ox','auto','생선의 비린내는 염기성 물질이라 산성인 식초로 닦으면 약해져요.',ARRAY['SC6-1-u1-X28']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C18","difficulty":2,"kind":"ox","stem":"생선의 비린내는 염기성 물질이라 산성인 식초로 닦으면 약해져요.","answer":"O","reason_options":[{"t":"반대 성질의 용액과 만나 성질이 약해지기 때문에","correct":true},{"t":"같은 염기성 용액으로 닦아야 냄새가 약해지기 때문에","mis":"SC6-1-u1-X28"}],"mis":"SC6-1-u1-X28","explanation":["비린내의 성질이에요.","식초는 산성이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#9','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C17',2,'error','auto','이용하는 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C17","difficulty":2,"kind":"error","stem":"이용하는 예를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「제빵 소다 용액은 산성이라 기름때를 없애.」","correct":true,"mis_target":"SC6-1-u1-X27"},{"t":"채아 — 「제빵 소다 용액으로 과일 껍질의 농약을 씻어 내.」","mis":"SC6-1-u1-X27"},{"t":"로운 — 「하수구 세정제는 머리카락을 녹여.」","mis":"SC6-1-u1-X27"}],"explanation":["제빵 소다 용액의 성질이에요.","염기성이에요.","이든이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_basic#10','sci',6,1,'u1','L06','g6_1_sci_u1_L06_basic','lesson_basic','SC6-1-u1-C18',3,'mc','auto','하수구 세정제로 머리카락이 막은 하수구를 뚫을 수 있는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X28']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C18","difficulty":3,"kind":"mc","stem":"하수구 세정제로 머리카락이 막은 하수구를 뚫을 수 있는 까닭은 무엇인가요?","options":[{"t":"머리카락의 주요 성분인 단백질을 염기성 용액이 녹이기 때문에","correct":true},{"t":"산성 용액이 단백질을 녹이기 때문에","mis":"SC6-1-u1-X17"},{"t":"세정제가 머리카락을 얼게 하기 때문에","mis":"SC6-1-u1-X28"},{"t":"물만 부어도 머리카락이 녹기 때문에","mis":"SC6-1-u1-X28"}],"explanation":["머리카락은 단백질이에요.","단백질은 염기성과 반응해요.","세정제는 염기성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#1','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C18',2,'sa','auto','생선을 손질한 도마에 남은 비린내는 어떤 성질의 물질인가요? (□□□)','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C18","difficulty":2,"kind":"sa","stem":"생선을 손질한 도마에 남은 비린내는 어떤 성질의 물질인가요? (□□□)","answer":["염기성","염기성 물질"],"explanation":["식초로 닦아요.","식초와 반대예요.","염기성이에요."],"mis":"SC6-1-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#2','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C16',2,'ox','auto','구연산 용액은 싱크대를 소독하고 냄새를 없애는 데 쓰여요.',ARRAY['SC6-1-u1-X29']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C16","difficulty":2,"kind":"ox","stem":"구연산 용액은 싱크대를 소독하고 냄새를 없애는 데 쓰여요.","answer":"O","reason_options":[{"t":"산성인 구연산 용액의 성질을 생활에 이용하기 때문에","correct":true},{"t":"구연산 용액은 생활에서 쓰지 않기 때문에","mis":"SC6-1-u1-X29"}],"mis":"SC6-1-u1-X29","explanation":["구연산 용액이에요.","산성 용액이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#3','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C17',3,'mc','auto','염기성 용액을 이용하는 예만 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C17","difficulty":3,"kind":"mc","stem":"염기성 용액을 이용하는 예만 모은 것은 어느 것인가요?","options":[{"t":"제산제 먹기, 하수구 세정제로 하수구 뚫기, 표백제로 욕실 청소하기","correct":true},{"t":"식초로 도마 닦기, 레몬즙으로 신맛 내기, 변기 청소용 세제로 변기 닦기","mis":"SC6-1-u1-X27"},{"t":"제산제 먹기, 식초로 도마 닦기, 표백제로 욕실 청소하기","mis":"SC6-1-u1-X27"},{"t":"구연산 용액으로 싱크대 닦기, 하수구 세정제로 하수구 뚫기, 레몬즙으로 신맛 내기","mis":"SC6-1-u1-X27"}],"explanation":["염기성 용액을 떠올려요.","산성이 섞이면 안 돼요.","세 가지 모두 염기성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#4','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C18',3,'mc','auto','위액이 많이 나와 속이 쓰릴 때 제산제가 도움이 되는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X28']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C18","difficulty":3,"kind":"mc","stem":"위액이 많이 나와 속이 쓰릴 때 제산제가 도움이 되는 까닭은 무엇인가요?","options":[{"t":"산성인 위액과 반대 성질인 염기성 제산제가 만나 산성이 약해지기 때문에","correct":true},{"t":"제산제도 산성이라 위액과 힘을 합치기 때문에","mis":"SC6-1-u1-X28"},{"t":"제산제가 위를 차갑게 하기 때문에","mis":"SC6-1-u1-X28"},{"t":"제산제가 위액의 색만 바꾸기 때문에","mis":"SC6-1-u1-X28"}],"explanation":["위액의 성질이에요.","제산제는 반대 성질이에요.","산성이 약해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#5','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C18',3,'error','auto','변기 청소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X28']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C18","difficulty":3,"kind":"error","stem":"변기 청소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「변기의 때는 염기성이니 염기성 세제로 닦아야 잘 없어져.」","correct":true,"mis_target":"SC6-1-u1-X28"},{"t":"주원 — 「변기의 때는 염기성이라 산성 세제를 써.」","mis":"SC6-1-u1-X28"},{"t":"예린 — 「위액은 산성이라 염기성인 제산제를 먹어.」","mis":"SC6-1-u1-X28"}],"explanation":["반대 성질을 써요.","변기 세제는 산성이에요.","하람이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
