INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#7','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C17',3,'mc','auto','과일 껍질에 남아 있는 농약을 없애는 데 쓰는 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C17","difficulty":3,"kind":"mc","stem":"과일 껍질에 남아 있는 농약을 없애는 데 쓰는 용액은 어느 것인가요?","options":[{"t":"제빵 소다 용액","correct":true},{"t":"변기 청소용 세제","mis":"SC6-1-u1-X27"},{"t":"하수구 세정제","mis":"SC6-1-u1-X27"},{"t":"구연산 용액","mis":"SC6-1-u1-X27"}],"explanation":["주방에서 써요.","염기성 용액이에요.","제빵 소다 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#8','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C18',4,'mc','auto','변기 냄새, 도마의 비린내, 머리카락이 막은 하수구를 해결할 용액을 차례대로 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X28']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C18","difficulty":4,"kind":"mc","stem":"변기 냄새, 도마의 비린내, 머리카락이 막은 하수구를 해결할 용액을 차례대로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"산성 세제 — 식초 — 염기성 세정제","correct":true},{"t":"염기성 세정제 — 식초 — 산성 세제","mis":"SC6-1-u1-X28"},{"t":"산성 세제 — 제산제 — 산성 세제","mis":"SC6-1-u1-X28"},{"t":"염기성 세정제 — 제빵 소다 용액 — 식초","mis":"SC6-1-u1-X28"}],"explanation":["없애려는 것의 성질을 따져요.","변기 때·비린내는 염기성이에요.","머리카락은 단백질이에요."],"asset":{"type":"passage","lines":["ㄱ 생선을 손질한 도마를 식초로 닦는다.","ㄴ 속이 쓰릴 때 제산제를 먹는다.","ㄷ 변기를 변기 청소용 세제로 청소한다.","ㄹ 막힌 하수구를 하수구 세정제로 뚫는다.","ㅁ 과일 껍질에 남은 농약을 제빵 소다 용액으로 씻어 낸다."],"title":"우리 주변에서 용액을 이용하는 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#9','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C16',4,'mc','auto','산성 용액과 염기성 용액의 이용을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u1-X29','SC6-1-u1-X28']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C16","difficulty":4,"kind":"mc","stem":"산성 용액과 염기성 용액의 이용을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"두 용액의 성질을 직접 이용하거나, 반대 성질과 만나 약해지는 것을 이용한다","correct":true},{"t":"생활에서는 산성 용액만 이용한다","mis":"SC6-1-u1-X29"},{"t":"모든 때는 산성 용액으로만 없앤다","mis":"SC6-1-u1-X28"},{"t":"같은 성질끼리 만나면 성질이 약해진다","mis":"SC6-1-u1-X28"}],"explanation":["두 갈래로 이용해요.","직접 쓰기와 약하게 하기예요.","둘 다 맞는 정리를 골라요."],"asset":{"type":"passage","lines":["ㄱ 생선을 손질한 도마를 식초로 닦는다.","ㄴ 속이 쓰릴 때 제산제를 먹는다.","ㄷ 변기를 변기 청소용 세제로 청소한다.","ㄹ 막힌 하수구를 하수구 세정제로 뚫는다.","ㅁ 과일 껍질에 남은 농약을 제빵 소다 용액으로 씻어 낸다."],"title":"우리 주변에서 용액을 이용하는 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L06_challenge#10','sci',6,1,'u1','L06','g6_1_sci_u1_L06_challenge','lesson_challenge','SC6-1-u1-C18',4,'essay','teacher','「도마를 식초로 닦기」와 「속이 쓰릴 때 제산제 먹기」를 각각 없애려는 물질의 성질과 이용하는 용액의 성질로 설명하고, 두 예의 공통점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C18","difficulty":4,"kind":"essay","stem":"「도마를 식초로 닦기」와 「속이 쓰릴 때 제산제 먹기」를 각각 없애려는 물질의 성질과 이용하는 용액의 성질로 설명하고, 두 예의 공통점을 쓰세요.","answer_guide":{"answer":"예: 생선을 손질한 도마의 비린내는 염기성 물질이므로 산성인 식초로 닦으면 냄새가 약해진다. 위에서 나온 위액은 산성이므로 염기성인 제산제를 먹으면 속 쓰림이 약해진다. 두 예 모두 없애려는 물질과 반대되는 성질의 용액을 이용해, 두 용액이 만나 성질이 약해지는 것을 이용했다.","scoring_points":["두 예에서 없애려는 물질의 성질을 썼는가","이용하는 용액의 성질을 썼는가","반대 성질을 이용한다는 공통점을 썼는가"]},"explanation":["도마부터 설명해요.","제산제를 설명해요.","공통점을 써요."],"asset":{"type":"passage","lines":["ㄱ 생선을 손질한 도마를 식초로 닦는다.","ㄴ 속이 쓰릴 때 제산제를 먹는다.","ㄷ 변기를 변기 청소용 세제로 청소한다.","ㄹ 막힌 하수구를 하수구 세정제로 뚫는다.","ㅁ 과일 껍질에 남은 농약을 제빵 소다 용액으로 씻어 낸다."],"title":"우리 주변에서 용액을 이용하는 예"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#1','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C19',1,'mc','auto','산성화란 무엇인가요?',ARRAY['SC6-1-u1-X30']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C19","difficulty":1,"kind":"mc","stem":"산성화란 무엇인가요?","options":[{"t":"어떤 물질이 기존의 성질에서 점차 산성으로 변하는 것","correct":true},{"t":"물질의 온도가 점점 높아지는 것","mis":"SC6-1-u1-X30"},{"t":"물질이 공기 중으로 날아가는 것","mis":"SC6-1-u1-X30"},{"t":"물질의 색깔이 점점 진해지는 것","mis":"SC6-1-u1-X30"}],"explanation":["산성화의 뜻이에요.","점차 변해요.","산성으로 변하는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#2','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C19',1,'mc','auto','대기 중의 오염 물질이 빗물에 녹아 보통 때보다 더 산성을 띠는 비를 무엇이라고 하나요?',ARRAY['SC6-1-u1-X31']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C19","difficulty":1,"kind":"mc","stem":"대기 중의 오염 물질이 빗물에 녹아 보통 때보다 더 산성을 띠는 비를 무엇이라고 하나요?","options":[{"t":"산성비","correct":true},{"t":"해양 산성화","mis":"SC6-1-u1-X31"},{"t":"토양 산성화","mis":"SC6-1-u1-X31"},{"t":"대기 오염 물질","mis":"SC6-1-u1-X31"}],"explanation":["비예요.","산성을 띠어요.","산성비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#3','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C20',1,'ox','auto','산성비로 대리암으로 만든 조각상이 훼손될 수 있어요.',ARRAY['SC6-1-u1-X33']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C20","difficulty":1,"kind":"ox","stem":"산성비로 대리암으로 만든 조각상이 훼손될 수 있어요.","answer":"O","reason_options":[{"t":"대리암의 주요 성분인 탄산 칼슘이 산성 용액에 녹기 때문에","correct":true},{"t":"산성화는 조각상이나 건물에는 영향을 주지 않기 때문에","mis":"SC6-1-u1-X33"}],"mis":"SC6-1-u1-X33","explanation":["대리암의 성분이에요.","탄산 칼슘이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#4','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C19',1,'sa','auto','바닷물이 산성을 띠는 현상을 무엇이라고 하나요? (□□ 산성화)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C19","difficulty":1,"kind":"sa","stem":"바닷물이 산성을 띠는 현상을 무엇이라고 하나요? (□□ 산성화)","answer":["해양","해양 산성화"],"explanation":["바다예요.","두 글자예요.","해양 산성화예요."],"asset":{"type":"passage","lines":["산성비 — 보통 때보다 산성을 띠는 비 · 대기 중의 오염 물질이 빗물에 녹음","해양 산성화 — 바닷물이 산성을 띠는 현상 · 주된 원인은 이산화 탄소","토양 산성화 — 땅(흙)이 산성을 띠는 현상 · 화학 비료나 농약의 과도한 사용, 산성비 등"],"title":"세 가지 산성화"},"mis":"SC6-1-u1-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#5','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C20',2,'mc','auto','해양 산성화로 인한 피해는 어느 것인가요?',ARRAY['SC6-1-u1-X32']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C20","difficulty":2,"kind":"mc","stem":"해양 산성화로 인한 피해는 어느 것인가요?","options":[{"t":"조개껍데기가 얇아진다","correct":true},{"t":"식물의 생장이 억제된다","mis":"SC6-1-u1-X32"},{"t":"토양의 미생물 활동이 줄어든다","mis":"SC6-1-u1-X32"},{"t":"대리암 조각상이 훼손된다","mis":"SC6-1-u1-X32"}],"explanation":["바다를 골라요.","바다 생물이에요.","조개껍데기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#6','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C20',2,'match','auto','피해 사례와 관계있는 산성화를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u1-C20","difficulty":2,"kind":"match","stem":"피해 사례와 관계있는 산성화를 알맞게 이으세요.","pairs":[{"l":"조개껍데기가 얇아진다","r":"해양 산성화"},{"l":"식물의 생장이 억제된다","r":"토양 산성화"},{"l":"대리암 조각상이 훼손된다","r":"산성비"}],"mis":"SC6-1-u1-X32","explanation":["바다·흙·비를 가려요.","조개는 바다예요.","조각상은 비를 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#7','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C21',2,'blank','auto','「친환경 에너지를 이용하고 자전거나 (    )을 이용하면 대기로 나가는 오염 물질을 줄일 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X37']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C21","difficulty":2,"kind":"blank","stem":"「친환경 에너지를 이용하고 자전거나 (    )을 이용하면 대기로 나가는 오염 물질을 줄일 수 있습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"대중교통","correct":true},{"t":"자가용 자동차","mis":"SC6-1-u1-X37"},{"t":"화석 연료","mis":"SC6-1-u1-X37"},{"t":"화학 비료","mis":"SC6-1-u1-X37"}],"explanation":["대책을 찾아요.","여럿이 함께 타요.","대중교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#8','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C21',2,'ox','auto','산성화는 먼 나라의 일이라 우리와 관계가 없어요.',ARRAY['SC6-1-u1-X35']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C21","difficulty":2,"kind":"ox","stem":"산성화는 먼 나라의 일이라 우리와 관계가 없어요.","answer":"X","reason_options":[{"t":"전 세계적으로 발생하는 환경 문제이기 때문에","correct":true},{"t":"우리나라에서는 산성화가 일어나지 않기 때문에","mis":"SC6-1-u1-X35"}],"mis":"SC6-1-u1-X35","explanation":["어디서 일어나나요?","전 세계예요.","우리와도 관계있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#9','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C21',2,'error','auto','산성화의 원인을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X36','SC6-1-u1-X37']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C21","difficulty":2,"kind":"error","stem":"산성화의 원인을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「산성화는 사람의 활동과 관계없이 저절로 생겨.」","correct":true,"mis_target":"SC6-1-u1-X36"},{"t":"규민 — 「화석 연료를 태우면 대기에 오염 물질이 늘어.」","mis":"SC6-1-u1-X36"},{"t":"소윤 — 「화학 비료나 농약을 지나치게 쓰면 흙이 산성을 띠어.」","mis":"SC6-1-u1-X37"}],"explanation":["원인을 떠올려요.","사람의 활동이에요.","태린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_basic#10','sci',6,1,'u1','L07','g6_1_sci_u1_L07_basic','lesson_basic','SC6-1-u1-C20',3,'mc','auto','바닷물이 산성을 띠면 조개와 산호가 잘 자라지 못하는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X41','SC6-1-u1-X20','SC6-1-u1-X33']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C20","difficulty":3,"kind":"mc","stem":"바닷물이 산성을 띠면 조개와 산호가 잘 자라지 못하는 까닭은 무엇인가요?","options":[{"t":"주요 성분인 탄산 칼슘이 산성 용액에 녹는 성질이 있기 때문에","correct":true},{"t":"바닷물이 점점 차가워지기 때문에","mis":"SC6-1-u1-X41"},{"t":"조개껍데기와 산호는 단백질이라 녹기 때문에","mis":"SC6-1-u1-X20"},{"t":"조개와 산호는 산성화와 관계없기 때문에","mis":"SC6-1-u1-X33"}],"explanation":["성분을 떠올려요.","탄산 칼슘이에요.","산성에 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#1','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C19',2,'sa','auto','땅(흙)이 산성을 띠는 현상을 무엇이라고 하나요? (□□ 산성화)','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C19","difficulty":2,"kind":"sa","stem":"땅(흙)이 산성을 띠는 현상을 무엇이라고 하나요? (□□ 산성화)","answer":["토양","토양 산성화"],"explanation":["흙이에요.","두 글자예요.","토양 산성화예요."],"mis":"SC6-1-u1-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#2','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C21',2,'ox','auto','산성화된 호수에 염기성 물질을 뿌리면 호수의 산성이 약해져요.',ARRAY['SC6-1-u1-X37']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C21","difficulty":2,"kind":"ox","stem":"산성화된 호수에 염기성 물질을 뿌리면 호수의 산성이 약해져요.","answer":"O","reason_options":[{"t":"산성과 반대 성질인 염기성 물질과 만나 산성이 약해지기 때문에","correct":true},{"t":"염기성 물질은 호수를 더 산성으로 만들기 때문에","mis":"SC6-1-u1-X37"}],"mis":"SC6-1-u1-X37","explanation":["반대 성질이에요.","만나면 약해져요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#3','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C21',3,'mc','auto','산성화의 원인끼리 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X37']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C21","difficulty":3,"kind":"mc","stem":"산성화의 원인끼리 모은 것은 어느 것인가요?","options":[{"t":"화석 연료 태우기, 화학 비료와 농약의 지나친 사용","correct":true},{"t":"자전거 이용, 친환경 에너지 이용","mis":"SC6-1-u1-X37"},{"t":"화석 연료 태우기, 대중교통 이용","mis":"SC6-1-u1-X37"},{"t":"친환경 에너지 이용, 농약의 지나친 사용","mis":"SC6-1-u1-X37"}],"explanation":["원인과 대책을 가려요.","오염을 늘리는 것이에요.","둘 다 원인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#4','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C20',3,'mc','auto','산호초 백화 현상에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X34','SC6-1-u1-X32']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C20","difficulty":3,"kind":"mc","stem":"산호초 백화 현상에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"해양 산성화뿐 아니라 해수온 상승, 염분 농도 변화, 유해 물질 등 여러 원인이 있다","correct":true},{"t":"해양 산성화 하나만이 원인이다","mis":"SC6-1-u1-X34"},{"t":"산호가 더 건강해진 모습이다","mis":"SC6-1-u1-X32"},{"t":"토양 산성화 때문에 생긴다","mis":"SC6-1-u1-X32"}],"explanation":["원인이 하나일까요?","여러 가지예요.","단정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#5','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C20',3,'error','auto','산성화의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X33','SC6-1-u1-X32']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C20","difficulty":3,"kind":"error","stem":"산성화의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「산성화는 생물에만 피해를 주고 건물은 괜찮아.」","correct":true,"mis_target":"SC6-1-u1-X33"},{"t":"선우 — 「산성비로 대리암 건축물이 훼손돼.」","mis":"SC6-1-u1-X33"},{"t":"예서 — 「호수가 산성화되면 물고기와 플랑크톤이 피해를 입어.」","mis":"SC6-1-u1-X32"}],"explanation":["건물과 문화재를 떠올려요.","대리암도 피해를 입어요.","지아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#6','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C19',3,'mc','auto','해양 산성화의 주된 원인은 무엇인가요?',ARRAY['SC6-1-u1-X31']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C19","difficulty":3,"kind":"mc","stem":"해양 산성화의 주된 원인은 무엇인가요?","options":[{"t":"이산화 탄소","correct":true},{"t":"화학 비료와 농약","mis":"SC6-1-u1-X31"},{"t":"석회 가루","mis":"SC6-1-u1-X31"},{"t":"조개껍데기","mis":"SC6-1-u1-X31"}],"explanation":["바닷물을 산성으로 만들어요.","기체예요.","이산화 탄소예요."],"asset":{"type":"passage","lines":["산성비 — 보통 때보다 산성을 띠는 비 · 대기 중의 오염 물질이 빗물에 녹음","해양 산성화 — 바닷물이 산성을 띠는 현상 · 주된 원인은 이산화 탄소","토양 산성화 — 땅(흙)이 산성을 띠는 현상 · 화학 비료나 농약의 과도한 사용, 산성비 등"],"title":"세 가지 산성화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#7','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C21',3,'mc','auto','산성화를 줄이는 대책으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X37','SC6-1-u1-X36','SC6-1-u1-X35']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C21","difficulty":3,"kind":"mc","stem":"산성화를 줄이는 대책으로 알맞은 것은 어느 것인가요?","options":[{"t":"가까운 곳은 걷거나 자전거를 탄다","correct":true},{"t":"화학 비료를 더 많이 쓴다","mis":"SC6-1-u1-X37"},{"t":"저절로 사라질 때까지 기다린다","mis":"SC6-1-u1-X36"},{"t":"먼 나라 일이니 신경 쓰지 않는다","mis":"SC6-1-u1-X35"}],"explanation":["오염 물질을 줄여요.","자동차를 덜 타요.","걷거나 자전거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#8','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C20',4,'mc','auto','토양 산성화의 원인과 피해를 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u1-X32','SC6-1-u1-X36']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C20","difficulty":4,"kind":"mc","stem":"토양 산성화의 원인과 피해를 바르게 정리한 것은 어느 것인가요?","options":[{"t":"화학 비료·농약의 과도한 사용과 산성비 등으로 생기며, 식물 생장이 억제되고 미생물 활동이 줄어든다","correct":true},{"t":"이산화 탄소가 주된 원인이며 조개껍데기가 얇아진다","mis":"SC6-1-u1-X32"},{"t":"저절로 생기며 아무 피해가 없다","mis":"SC6-1-u1-X36"},{"t":"대리암 조각상만 훼손시킨다","mis":"SC6-1-u1-X32"}],"explanation":["흙의 산성화예요.","원인은 비료·농약·산성비예요.","피해는 식물과 미생물이에요."],"asset":{"type":"passage","lines":["산성비 — 보통 때보다 산성을 띠는 비 · 대기 중의 오염 물질이 빗물에 녹음","해양 산성화 — 바닷물이 산성을 띠는 현상 · 주된 원인은 이산화 탄소","토양 산성화 — 땅(흙)이 산성을 띠는 현상 · 화학 비료나 농약의 과도한 사용, 산성비 등"],"title":"세 가지 산성화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#9','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C21',4,'mc','auto','산성비의 원인 — 피해 — 대책을 바르게 이은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X37','SC6-1-u1-X31','SC6-1-u1-X36']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C21","difficulty":4,"kind":"mc","stem":"산성비의 원인 — 피해 — 대책을 바르게 이은 것은 어느 것인가요?","options":[{"t":"화석 연료 연소·자동차 배기가스 — 삼림 황폐·건축물 훼손 — 친환경 에너지·대중교통 이용","correct":true},{"t":"친환경 에너지 이용 — 조개껍데기가 얇아짐 — 화석 연료 더 태우기","mis":"SC6-1-u1-X37"},{"t":"화학 비료 사용 — 바닷물이 산성을 띰 — 자동차 더 타기","mis":"SC6-1-u1-X31"},{"t":"저절로 생김 — 피해 없음 — 기다리기","mis":"SC6-1-u1-X36"}],"explanation":["원인부터 따져요.","피해는 숲과 건물이에요.","대책은 오염 줄이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L07_challenge#10','sci',6,1,'u1','L07','g6_1_sci_u1_L07_challenge','lesson_challenge','SC6-1-u1-C20',4,'essay','teacher','산성비, 해양 산성화, 토양 산성화 가운데 두 가지를 골라 각각의 피해 사례와 원인을 쓰고, 산성화를 줄이기 위해 우리가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C20","difficulty":4,"kind":"essay","stem":"산성비, 해양 산성화, 토양 산성화 가운데 두 가지를 골라 각각의 피해 사례와 원인을 쓰고, 산성화를 줄이기 위해 우리가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 산성비는 대기 중의 오염 물질이 빗물에 녹아 생기며, 삼림이 황폐해지고 대리암으로 만든 조각상이나 건축물이 훼손된다. 해양 산성화는 주로 이산화 탄소 때문에 바닷물이 산성을 띠는 현상으로, 조개껍데기가 얇아지고 산호가 잘 자라지 못한다. 산성화를 줄이려면 친환경 에너지를 이용하고 가까운 곳은 걷거나 자전거를 타며 대중교통을 이용해 대기로 나가는 오염 물질과 이산화 탄소를 줄여야 한다.","scoring_points":["두 가지 산성화의 피해를 썼는가","각각의 원인을 썼는가","우리가 할 수 있는 대책을 썼는가"]},"explanation":["두 가지를 골라요.","피해와 원인을 써요.","우리의 실천을 써요."],"asset":{"type":"passage","lines":["산성비 — 보통 때보다 산성을 띠는 비 · 대기 중의 오염 물질이 빗물에 녹음","해양 산성화 — 바닷물이 산성을 띠는 현상 · 주된 원인은 이산화 탄소","토양 산성화 — 땅(흙)이 산성을 띠는 현상 · 화학 비료나 농약의 과도한 사용, 산성비 등"],"title":"세 가지 산성화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#1','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C22',1,'mc','auto','산성화 알림 동영상을 만들 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['SC6-1-u1-X38']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C22","difficulty":1,"kind":"mc","stem":"산성화 알림 동영상을 만들 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"알릴 주제를 정하고 피해 사례를 조사하기","correct":true},{"t":"완성한 동영상을 누리망에 공유하기","mis":"SC6-1-u1-X38"},{"t":"동영상 편집 애플리케이션으로 만들기","mis":"SC6-1-u1-X38"},{"t":"다른 모둠 동영상에 댓글 달기","mis":"SC6-1-u1-X38"}],"explanation":["무엇을 알릴지 정해요.","조사가 먼저예요.","주제와 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#2','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C23',1,'mc','auto','환경 과학자는 어떤 일을 하는 사람인가요?',ARRAY['SC6-1-u1-X40']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C23","difficulty":1,"kind":"mc","stem":"환경 과학자는 어떤 일을 하는 사람인가요?","options":[{"t":"토양·공기·물을 조사·분석해 환경 문제의 원인을 찾고 개선하는 사람","correct":true},{"t":"건물이나 조각상을 예쁘게 꾸미는 사람","mis":"SC6-1-u1-X40"},{"t":"요리에 여러 가지 용액을 넣는 사람","mis":"SC6-1-u1-X40"},{"t":"동영상만 전문으로 만드는 사람","mis":"SC6-1-u1-X40"}],"explanation":["환경을 연구해요.","흙·공기·물이에요.","원인을 찾고 개선해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#3','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C22',1,'ox','auto','조사한 자료를 공유할 때는 출처를 밝혀요.',ARRAY['SC6-1-u1-X39']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C22","difficulty":1,"kind":"ox","stem":"조사한 자료를 공유할 때는 출처를 밝혀요.","answer":"O","reason_options":[{"t":"자료를 만든 사람을 존중하고 믿을 수 있게 하기 위해서","correct":true},{"t":"출처를 밝히면 동영상이 지저분해지기 때문에","mis":"SC6-1-u1-X39"}],"mis":"SC6-1-u1-X39","explanation":["남이 만든 자료예요.","누가 만들었는지 밝혀요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#4','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C23',1,'sa','auto','하천·호수의 수질 상태를 측정하는 환경 과학자를 무엇이라고 하나요? (□□ 환경 과학자)','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u1-C23","difficulty":1,"kind":"sa","stem":"하천·호수의 수질 상태를 측정하는 환경 과학자를 무엇이라고 하나요? (□□ 환경 과학자)","answer":["수질","수질 환경 과학자"],"explanation":["물을 연구해요.","두 글자예요.","수질 환경 과학자예요."],"mis":"SC6-1-u1-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#5','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C22',2,'mc','auto','피해 사례를 조사할 때 알아볼 네 가지로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X38']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"mc","stem":"피해 사례를 조사할 때 알아볼 네 가지로 알맞은 것은 어느 것인가요?","options":[{"t":"원인, 현황, 전망, 대책","correct":true},{"t":"색깔, 글꼴, 배경 음악, 효과음","mis":"SC6-1-u1-X38"},{"t":"원인 한 가지만","mis":"SC6-1-u1-X38"},{"t":"좋아하는 장면, 배우, 제목, 노래","mis":"SC6-1-u1-X38"}],"explanation":["왜·지금·앞으로·어떻게예요.","내용을 조사해요.","원인·현황·전망·대책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#6','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C23',2,'match','auto','환경 과학자와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u1-C23","difficulty":2,"kind":"match","stem":"환경 과학자와 하는 일을 알맞게 이으세요.","pairs":[{"l":"토양 환경 과학자","r":"흙의 산성도를 분석한다"},{"l":"대기 환경 과학자","r":"대기 오염 물질을 검출한다"},{"l":"수질 환경 과학자","r":"하천·호수의 수질을 측정한다"}],"mis":"SC6-1-u1-X40","explanation":["흙·공기·물을 가려요.","대기는 공기예요.","하나씩 이어요."],"asset":{"type":"passage","lines":["토양 환경 과학자 — 흙의 산성도 등 상태를 분석하고 식물이 잘 자랄 환경을 연구","대기 환경 과학자 — 공기의 상태를 재고 산성 대기 오염 물질과 배출원을 찾음","수질 환경 과학자 — 하천·호수의 수질과 물의 산성도를 재고 정화 방법을 연구"],"title":"환경 과학자가 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#7','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C22',2,'blank','auto','「완성한 동영상을 누리망이나 (    )에 올려 공유합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X38']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"blank","stem":"「완성한 동영상을 누리망이나 (    )에 올려 공유합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"사회 관계망 서비스","correct":true},{"t":"혼자만 보는 폴더","mis":"SC6-1-u1-X38"},{"t":"닫힌 서랍","mis":"SC6-1-u1-X38"},{"t":"아무도 모르는 비밀 공책","mis":"SC6-1-u1-X38"}],"explanation":["여러 사람이 봐야 해요.","함께 보는 곳이에요.","사회 관계망 서비스예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#8','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C22',2,'ox','auto','다른 모둠의 동영상을 보고 잘한 점을 댓글로 써요.',ARRAY['SC6-1-u1-X39']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"ox","stem":"다른 모둠의 동영상을 보고 잘한 점을 댓글로 써요.","answer":"O","reason_options":[{"t":"서로 배우고 격려할 수 있기 때문에","correct":true},{"t":"다른 모둠 것은 볼 필요가 없기 때문에","mis":"SC6-1-u1-X39"}],"mis":"SC6-1-u1-X39","explanation":["공유 단계예요.","잘한 점을 찾아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#9','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C22',2,'error','auto','동영상을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X39']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"error","stem":"동영상을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은찬 — 「남이 찍은 사진을 출처 없이 그대로 쓰자.」","correct":true,"mis_target":"SC6-1-u1-X39"},{"t":"나윤 — 「모둠원이 역할을 나누어 조사하자.」","mis":"SC6-1-u1-X39"},{"t":"도윤 — 「자료의 인터넷 주소를 링크로 연결하자.」","mis":"SC6-1-u1-X39"}],"explanation":["출처를 떠올려요.","남의 자료예요.","은찬이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_basic#10','sci',6,1,'u1','L08','g6_1_sci_u1_L08_basic','lesson_basic','SC6-1-u1-C23',3,'mc','auto','토양 환경 과학자가 토양 산성화를 막으려고 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X40']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C23","difficulty":3,"kind":"mc","stem":"토양 환경 과학자가 토양 산성화를 막으려고 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"화학 비료·농약을 줄이는 방법과 친환경 퇴비 등을 연구해 안내한다","correct":true},{"t":"대기 중 오염 물질의 배출원을 파악한다","mis":"SC6-1-u1-X40"},{"t":"하천의 수질을 측정한다","mis":"SC6-1-u1-X40"},{"t":"알림 동영상만 편집한다","mis":"SC6-1-u1-X40"}],"explanation":["흙을 연구해요.","비료와 농약이 원인이에요.","줄이는 방법을 연구해요."],"asset":{"type":"passage","lines":["토양 환경 과학자 — 흙의 산성도 등 상태를 분석하고 식물이 잘 자랄 환경을 연구","대기 환경 과학자 — 공기의 상태를 재고 산성 대기 오염 물질과 배출원을 찾음","수질 환경 과학자 — 하천·호수의 수질과 물의 산성도를 재고 정화 방법을 연구"],"title":"환경 과학자가 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#1','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C22',2,'sa','auto','조사한 자료를 공유할 때 꼭 밝혀야 하는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"sa","stem":"조사한 자료를 공유할 때 꼭 밝혀야 하는 것을 두 글자로 쓰세요.","answer":["출처"],"explanation":["자료가 어디서 왔나요?","□처예요.","출처예요."],"mis":"SC6-1-u1-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#2','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C23',2,'ox','auto','환경 과학자는 산성화와 관계없는 일만 해요.',ARRAY['SC6-1-u1-X40']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C23","difficulty":2,"kind":"ox","stem":"환경 과학자는 산성화와 관계없는 일만 해요.","answer":"X","reason_options":[{"t":"산성화와 같은 환경 문제의 원인을 찾고 개선하려고 연구하기 때문에","correct":true},{"t":"환경 과학자는 동영상만 만들기 때문에","mis":"SC6-1-u1-X40"}],"mis":"SC6-1-u1-X40","explanation":["하는 일을 떠올려요.","산성화도 연구해요.","관계있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#3','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C22',3,'mc','auto','알림 동영상을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X38']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C22","difficulty":3,"kind":"mc","stem":"알림 동영상을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"조사해요 → 계획해요 → 만들어요 → 공유해요","correct":true},{"t":"만들어요 → 조사해요 → 공유해요 → 계획해요","mis":"SC6-1-u1-X38"},{"t":"공유해요 → 계획해요 → 조사해요 → 만들어요","mis":"SC6-1-u1-X38"},{"t":"계획해요 → 만들어요 → 조사해요 → 공유해요","mis":"SC6-1-u1-X38"}],"explanation":["조사가 먼저예요.","공유가 마지막이에요.","차례대로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
