INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#5','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C22',3,'error','auto','동영상 주제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X35','SC6-1-u1-X38']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C22","difficulty":3,"kind":"error","stem":"동영상 주제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「산성화는 먼 나라 일이라 알릴 필요가 없어.」","correct":true,"mis_target":"SC6-1-u1-X35"},{"t":"하준 — 「피해 사례를 알리면 함께 줄일 수 있어.」","mis":"SC6-1-u1-X35"},{"t":"서하 — 「조사한 내용을 어떻게 표현할지 계획하자.」","mis":"SC6-1-u1-X38"}],"explanation":["산성화는 어디서 일어나나요?","전 세계적인 문제예요.","라온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#6','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C22',3,'mc','auto','산성화 알림 동영상을 만드는 목적으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X39','SC6-1-u1-X35']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C22","difficulty":3,"kind":"mc","stem":"산성화 알림 동영상을 만드는 목적으로 알맞은 것은 어느 것인가요?","options":[{"t":"피해 사례를 소개하고 산성화를 줄이는 노력에 함께하도록 알리기","correct":true},{"t":"화려한 효과를 자랑하기","mis":"SC6-1-u1-X39"},{"t":"다른 모둠보다 조회 수를 많이 얻기","mis":"SC6-1-u1-X39"},{"t":"산성화가 별일이 아님을 알리기","mis":"SC6-1-u1-X35"}],"explanation":["왜 알리나요?","함께 줄이려고요.","피해를 알리고 동참을 이끌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#7','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C23',3,'mc','auto','물의 산성도를 재어 호수·해양 산성화의 원인을 파악하는 환경 과학자는 누구인가요?',ARRAY['SC6-1-u1-X40']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C23","difficulty":3,"kind":"mc","stem":"물의 산성도를 재어 호수·해양 산성화의 원인을 파악하는 환경 과학자는 누구인가요?","options":[{"t":"수질 환경 과학자","correct":true},{"t":"토양 환경 과학자","mis":"SC6-1-u1-X40"},{"t":"대기 환경 과학자","mis":"SC6-1-u1-X40"},{"t":"동영상 편집자","mis":"SC6-1-u1-X40"}],"explanation":["물을 연구해요.","호수와 바다예요.","수질 환경 과학자예요."],"asset":{"type":"passage","lines":["토양 환경 과학자 — 흙의 산성도 등 상태를 분석하고 식물이 잘 자랄 환경을 연구","대기 환경 과학자 — 공기의 상태를 재고 산성 대기 오염 물질과 배출원을 찾음","수질 환경 과학자 — 하천·호수의 수질과 물의 산성도를 재고 정화 방법을 연구"],"title":"환경 과학자가 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#8','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C23',4,'mc','auto','「ㄱ 산성비를 만드는 오염 물질을 찾는다 · ㄴ 호수 물의 산성도를 잰다 · ㄷ 밭 흙의 산성도를 분석한다」를 맡을 과학자를 차례대로 바르게 고른 것은 어느 것인가요?',ARRAY['SC6-1-u1-X40']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C23","difficulty":4,"kind":"mc","stem":"「ㄱ 산성비를 만드는 오염 물질을 찾는다 · ㄴ 호수 물의 산성도를 잰다 · ㄷ 밭 흙의 산성도를 분석한다」를 맡을 과학자를 차례대로 바르게 고른 것은 어느 것인가요?","options":[{"t":"대기 — 수질 — 토양 환경 과학자","correct":true},{"t":"수질 — 대기 — 토양 환경 과학자","mis":"SC6-1-u1-X40"},{"t":"토양 — 수질 — 대기 환경 과학자","mis":"SC6-1-u1-X40"},{"t":"대기 — 토양 — 수질 환경 과학자","mis":"SC6-1-u1-X40"}],"explanation":["ㄱ은 공기예요.","ㄴ은 물이에요.","ㄷ은 흙이에요."],"asset":{"type":"passage","lines":["토양 환경 과학자 — 흙의 산성도 등 상태를 분석하고 식물이 잘 자랄 환경을 연구","대기 환경 과학자 — 공기의 상태를 재고 산성 대기 오염 물질과 배출원을 찾음","수질 환경 과학자 — 하천·호수의 수질과 물의 산성도를 재고 정화 방법을 연구"],"title":"환경 과학자가 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#9','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C22',4,'mc','auto','동영상을 만들고 나누는 태도를 가장 바르게 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X39','SC6-1-u1-X35']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C22","difficulty":4,"kind":"mc","stem":"동영상을 만들고 나누는 태도를 가장 바르게 모은 것은 어느 것인가요?","options":[{"t":"출처를 밝히거나 링크로 연결하고, 역할을 나누어 협력하며, 다른 모둠의 잘한 점을 댓글로 쓴다","correct":true},{"t":"출처는 빼고, 한 사람이 모두 만들며, 못한 점만 골라 댓글을 쓴다","mis":"SC6-1-u1-X39"},{"t":"남의 자료를 그대로 쓰고, 꾸밈에만 시간을 쓴다","mis":"SC6-1-u1-X39"},{"t":"산성화는 우리와 관계없으니 재미있는 장면만 넣는다","mis":"SC6-1-u1-X35"}],"explanation":["출처·협력·댓글이에요.","세 가지가 모두 맞아야 해요.","바른 태도를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_L08_challenge#10','sci',6,1,'u1','L08','g6_1_sci_u1_L08_challenge','lesson_challenge','SC6-1-u1-C22',4,'essay','teacher','우리 모둠의 산성화 알림 동영상 계획을 쓰세요. 주제 하나를 고르고, 조사할 네 가지(원인·현황·전망·대책)를 각각 한 가지씩 쓴 뒤, 자료를 공유할 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u1-C22","difficulty":4,"kind":"essay","stem":"우리 모둠의 산성화 알림 동영상 계획을 쓰세요. 주제 하나를 고르고, 조사할 네 가지(원인·현황·전망·대책)를 각각 한 가지씩 쓴 뒤, 자료를 공유할 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 주제는 토양 산성화이다. 원인 — 화학 비료나 농약의 과도한 사용과 산성비. 현황 — 흙이 산성을 띠어 식물이 잘 자라지 못하고 미생물 활동이 줄어든 사례. 전망 — 계속되면 농작물과 숲이 더 큰 피해를 입을 수 있다. 대책 — 화학 비료·농약을 줄이고 친환경 퇴비를 쓴다. 자료를 공유할 때는 출처를 밝히거나 인터넷 주소를 링크로 연결하고, 다른 모둠 동영상에는 잘한 점을 댓글로 쓴다.","scoring_points":["주제를 정했는가","원인·현황·전망·대책을 모두 썼는가","출처 밝히기 등 공유할 때 지킬 점을 썼는가"]},"explanation":["주제를 골라요.","네 가지를 채워요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#1','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C9',1,'mc','auto','나래반 일지 ①에서 산성 용액끼리 모은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X15']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C9","difficulty":1,"kind":"mc","stem":"나래반 일지 ①에서 산성 용액끼리 모은 것은 어느 것인가요?","options":[{"t":"㉠, ㉡, ㉤","correct":true},{"t":"㉢, ㉣","mis":"SC6-1-u1-X15"},{"t":"㉠, ㉢","mis":"SC6-1-u1-X15"},{"t":"㉡, ㉣, ㉤","mis":"SC6-1-u1-X15"}],"explanation":["붉은색 계열을 찾아요.","산성은 붉은색 계열이에요.","㉠·㉡·㉤이에요."],"asset":{"type":"passage","lines":["㉠ 식초 — 붉은색 계열","㉡ 레몬즙 — 붉은색 계열","㉢ 제빵 소다 용액 — 푸른색 계열","㉣ 빨랫비누 물 — 푸른색이나 노란색 계열","㉤ 구연산 용액 — 붉은색 계열"],"title":"나래반 일지 ① 붉은 양배추 용액을 떨어뜨린 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#2','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C7',1,'mc','auto','염기성 용액에 붉은색 리트머스 시험지를 대면 어떻게 되나요?',ARRAY['SC6-1-u1-X11']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C7","difficulty":1,"kind":"mc","stem":"염기성 용액에 붉은색 리트머스 시험지를 대면 어떻게 되나요?","options":[{"t":"푸른색으로 변한다","correct":true},{"t":"변화가 없다","mis":"SC6-1-u1-X11"},{"t":"붉은색이 더 진해진다","mis":"SC6-1-u1-X11"},{"t":"노란색으로 변한다","mis":"SC6-1-u1-X11"}],"explanation":["붉은색 시험지예요.","염기성에서 변해요.","푸른색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#3','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C10',1,'mc','auto','묽은 염산에 넣으면 기포가 발생하며 녹는 것은 어느 것인가요?',ARRAY['SC6-1-u1-X17']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C10","difficulty":1,"kind":"mc","stem":"묽은 염산에 넣으면 기포가 발생하며 녹는 것은 어느 것인가요?","options":[{"t":"조개껍데기","correct":true},{"t":"삶은 달걀흰자","mis":"SC6-1-u1-X17"},{"t":"삶은 닭 가슴살","mis":"SC6-1-u1-X17"},{"t":"아무것도 녹지 않는다","mis":"SC6-1-u1-X17"}],"explanation":["산성 용액이에요.","탄산 칼슘이 든 것이에요.","조개껍데기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#4','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C14',1,'mc','auto','염기성 용액에 산성 용액을 계속 넣을 때 일어나는 변화로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X24']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C14","difficulty":1,"kind":"mc","stem":"염기성 용액에 산성 용액을 계속 넣을 때 일어나는 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"염기성이 약해지다가 산성으로 변한다","correct":true},{"t":"염기성이 더 강해진다","mis":"SC6-1-u1-X23"},{"t":"처음 성질 그대로이다","mis":"SC6-1-u1-X23"},{"t":"용액이 사라진다","mis":"SC6-1-u1-X24"}],"explanation":["반대 성질을 넣어요.","처음 성질이 약해져요.","산성으로 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#5','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C16',1,'mc','auto','나래반 일지 ⑤에서 산성 용액을 이용한 것은 어느 것인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C16","difficulty":1,"kind":"mc","stem":"나래반 일지 ⑤에서 산성 용액을 이용한 것은 어느 것인가요?","options":[{"t":"할머니가 도마를 식초로 닦으신 것","correct":true},{"t":"삼촌이 제산제를 드신 것","mis":"SC6-1-u1-X27"},{"t":"엄마가 하수구 세정제를 쓰신 것","mis":"SC6-1-u1-X27"},{"t":"세 가지 모두 염기성 용액을 이용했다","mis":"SC6-1-u1-X27"}],"explanation":["식초의 성질이에요.","산성이에요.","할머니예요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#6','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C19',1,'mc','auto','보통 때보다 산성을 띠는 비를 무엇이라고 하나요?',ARRAY['SC6-1-u1-X31','SC6-1-u1-X30']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C19","difficulty":1,"kind":"mc","stem":"보통 때보다 산성을 띠는 비를 무엇이라고 하나요?","options":[{"t":"산성비","correct":true},{"t":"해양 산성화","mis":"SC6-1-u1-X31"},{"t":"토양 산성화","mis":"SC6-1-u1-X31"},{"t":"지시약","mis":"SC6-1-u1-X30"}],"explanation":["비예요.","산성을 띠어요.","산성비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#7','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C21',1,'mc','auto','산성화를 줄이려고 우리 사회가 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X37','SC6-1-u1-X36']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C21","difficulty":1,"kind":"mc","stem":"산성화를 줄이려고 우리 사회가 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"친환경 에너지를 이용한다","correct":true},{"t":"화석 연료를 더 많이 태운다","mis":"SC6-1-u1-X37"},{"t":"농약을 지나치게 쓴다","mis":"SC6-1-u1-X37"},{"t":"저절로 사라질 때까지 기다린다","mis":"SC6-1-u1-X36"}],"explanation":["오염 물질을 줄여요.","깨끗한 에너지예요.","친환경 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#8','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C22',1,'mc','auto','나래반 일지 ⑧에서 사진의 출처와 주소를 적은 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X39']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C22","difficulty":1,"kind":"mc","stem":"나래반 일지 ⑧에서 사진의 출처와 주소를 적은 까닭은 무엇인가요?","options":[{"t":"자료를 만든 사람을 존중하고 믿을 수 있게 하려고","correct":true},{"t":"동영상을 더 화려하게 꾸미려고","mis":"SC6-1-u1-X39"},{"t":"동영상을 더 빨리 만들려고","mis":"SC6-1-u1-X39"},{"t":"다른 모둠이 못 보게 하려고","mis":"SC6-1-u1-X39"}],"explanation":["남이 만든 자료예요.","존중해요.","믿을 수 있어요."],"asset":{"type":"passage","lines":["주제 — 토양 산성화","조사 — 원인·현황·전망·대책을 모둠원이 나누어 맡음","자료 — 누리집 사진을 쓸 때 출처와 주소를 함께 적음","공유 — 학급 누리집에 올리고 다른 모둠의 잘한 점을 댓글로 씀"],"title":"나래반 일지 ⑧ 알림 동영상 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#9','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C4',2,'mc','auto','나래반 일지 ⑥에서 도윤의 말을 바로잡을 수 있는 예는 어느 것인가요?',ARRAY['SC6-1-u1-X06','SC6-1-u1-X05']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C4","difficulty":2,"kind":"mc","stem":"나래반 일지 ⑥에서 도윤의 말을 바로잡을 수 있는 예는 어느 것인가요?","options":[{"t":"식초는 노란색이지만 투명하다","correct":true},{"t":"석회수는 색깔이 없고 투명하다","mis":"SC6-1-u1-X06"},{"t":"레몬즙은 불투명하다","mis":"SC6-1-u1-X06"},{"t":"빨랫비누 물은 거품이 유지된다","mis":"SC6-1-u1-X05"}],"explanation":["색깔이 있는데 투명한 것을 찾아요.","노란색이에요.","식초예요."],"asset":{"type":"passage","lines":["도윤 — 「투명한 용액은 색깔이 없는 거야.」","서아 — 「지시약이 다르면 나뉘는 무리도 달라.」","은호 — 「산성 용액과 염기성 용액은 섞어도 그대로야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"나래반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#10','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C9',2,'mc','auto','나래반 일지 ②에서 컵 ㉮의 용액은 어떤 용액인가요?',ARRAY['SC6-1-u1-X15','SC6-1-u1-X09','SC6-1-u1-X08']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C9","difficulty":2,"kind":"mc","stem":"나래반 일지 ②에서 컵 ㉮의 용액은 어떤 용액인가요?","options":[{"t":"염기성 용액","correct":true},{"t":"산성 용액","mis":"SC6-1-u1-X15"},{"t":"지시약","mis":"SC6-1-u1-X09"},{"t":"투명하니 알 수 없다","mis":"SC6-1-u1-X08"}],"explanation":["페놀프탈레인이 붉어졌어요.","염기성에서 붉어요.","염기성 용액이에요."],"asset":{"type":"passage","lines":["컵 ㉮와 ㉯에 든 용액은 둘 다 색깔이 없고 투명하다.","㉮에 페놀프탈레인 용액 — 붉은색으로 변함","㉯에 페놀프탈레인 용액 — 변화 없음","㉯에 푸른색 리트머스 시험지 — 붉은색으로 변함"],"title":"나래반 일지 ② 투명한 두 컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#11','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C10',2,'mc','auto','나래반 일지 ③에서 날달걀의 껍데기가 녹은 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X18','SC6-1-u1-X20','SC6-1-u1-X17']::text[],false,'{"seq":11,"concept":"SC6-1-u1-C10","difficulty":2,"kind":"mc","stem":"나래반 일지 ③에서 날달걀의 껍데기가 녹은 까닭은 무엇인가요?","options":[{"t":"껍데기의 주요 성분인 탄산 칼슘이 산성인 식초와 반응했기 때문에","correct":true},{"t":"식초가 염기성이기 때문에","mis":"SC6-1-u1-X18"},{"t":"껍데기의 주요 성분이 단백질이기 때문에","mis":"SC6-1-u1-X20"},{"t":"식초가 차갑기 때문에","mis":"SC6-1-u1-X17"}],"explanation":["껍데기의 성분이에요.","식초는 산성이에요.","탄산 칼슘이 반응했어요."],"asset":{"type":"passage","lines":["날달걀을 식초에 담가 두었다 — 껍데기에서 기포가 생기며 껍데기가 녹았다.","삶은 달걀흰자 조각을 식초에 담가 두었다 — 변화가 없었다.","선생님이 묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣어 보여 주셨다","　　— 시간이 지나면서 흐물흐물해졌다."],"title":"나래반 일지 ③ 달걀 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#12','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C13',2,'mc','auto','나래반 일지 ④에서 색이 붉은색 계열에서 노란색 계열로 바뀐 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u1-X22','SC6-1-u1-X23','SC6-1-u1-X24']::text[],false,'{"seq":12,"concept":"SC6-1-u1-C13","difficulty":2,"kind":"mc","stem":"나래반 일지 ④에서 색이 붉은색 계열에서 노란색 계열로 바뀐 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"산성이 약해지다가 염기성으로 변했다","correct":true},{"t":"염기성이 약해지다가 산성으로 변했다","mis":"SC6-1-u1-X22"},{"t":"성질은 그대로이다","mis":"SC6-1-u1-X23"},{"t":"용액이 물이 되었다","mis":"SC6-1-u1-X24"}],"explanation":["처음은 산성이에요.","노란색 계열은 염기성이에요.","염기성으로 변했어요."],"asset":{"type":"passage","lines":["선생님 시범 — 붉은 양배추 용액을 넣은 묽은 염산에","묽은 수산화 나트륨 용액을 조금씩 넣으셨다.","처음: 붉은색 계열 → 넣을수록 색이 바뀜 → 마지막: 노란색 계열"],"title":"나래반 일지 ④ 섞기 시범"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#13','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C18',2,'mc','auto','나래반 일지 ⑤에서 할머니가 식초로 도마를 닦으시는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X28','SC6-1-u1-X27']::text[],false,'{"seq":13,"concept":"SC6-1-u1-C18","difficulty":2,"kind":"mc","stem":"나래반 일지 ⑤에서 할머니가 식초로 도마를 닦으시는 까닭은 무엇인가요?","options":[{"t":"염기성인 비린내를 산성인 식초가 약하게 하기 때문에","correct":true},{"t":"비린내도 산성이기 때문에","mis":"SC6-1-u1-X28"},{"t":"식초가 염기성이기 때문에","mis":"SC6-1-u1-X27"},{"t":"식초가 도마를 녹이기 때문에","mis":"SC6-1-u1-X28"}],"explanation":["비린내의 성질이에요.","식초는 반대 성질이에요.","약하게 해요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#14','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C20',2,'mc','auto','나래반 일지 ⑦에서 바닷물이 산성을 띠면 조개껍데기가 얇아지는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X41','SC6-1-u1-X20','SC6-1-u1-X36']::text[],false,'{"seq":14,"concept":"SC6-1-u1-C20","difficulty":2,"kind":"mc","stem":"나래반 일지 ⑦에서 바닷물이 산성을 띠면 조개껍데기가 얇아지는 까닭은 무엇인가요?","options":[{"t":"조개껍데기의 주요 성분인 탄산 칼슘이 산성에 녹기 때문에","correct":true},{"t":"바닷물이 염기성이 되기 때문에","mis":"SC6-1-u1-X41"},{"t":"조개껍데기가 단백질이기 때문에","mis":"SC6-1-u1-X20"},{"t":"조개껍데기는 저절로 얇아지기 때문에","mis":"SC6-1-u1-X36"}],"explanation":["안내판 둘째 줄이에요.","탄산 칼슘이에요.","산성에 녹아요."],"asset":{"type":"passage","lines":["바닷물이 산성을 띠면 조개껍데기가 얇아지고 산호가 피해를 입어요.","조개껍데기와 산호의 주요 성분은 탄산 칼슘이에요.","과학관 앞 대리암 조각상도 산성비로 조금씩 훼손되고 있어요.","우리의 약속 — 가까운 곳은 걸어서, 먼 곳은 대중교통으로!"],"title":"나래반 일지 ⑦ 바닷가 과학관 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#15','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C19',2,'mc','auto','나래반 일지 ⑦의 바다 피해를 일으키는 해양 산성화의 주된 원인은 무엇인가요?',ARRAY['SC6-1-u1-X31']::text[],false,'{"seq":15,"concept":"SC6-1-u1-C19","difficulty":2,"kind":"mc","stem":"나래반 일지 ⑦의 바다 피해를 일으키는 해양 산성화의 주된 원인은 무엇인가요?","options":[{"t":"이산화 탄소","correct":true},{"t":"화학 비료","mis":"SC6-1-u1-X31"},{"t":"대리암","mis":"SC6-1-u1-X31"},{"t":"바닷모래","mis":"SC6-1-u1-X31"}],"explanation":["바닷물을 산성으로 만들어요.","기체예요.","이산화 탄소예요."],"asset":{"type":"passage","lines":["바닷물이 산성을 띠면 조개껍데기가 얇아지고 산호가 피해를 입어요.","조개껍데기와 산호의 주요 성분은 탄산 칼슘이에요.","과학관 앞 대리암 조각상도 산성비로 조금씩 훼손되고 있어요.","우리의 약속 — 가까운 곳은 걸어서, 먼 곳은 대중교통으로!"],"title":"나래반 일지 ⑦ 바닷가 과학관 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#16','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C22',2,'mc','auto','알림 동영상 만들기에서 「조사해요」 다음에 할 일은 어느 것인가요?',ARRAY['SC6-1-u1-X38']::text[],false,'{"seq":16,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"mc","stem":"알림 동영상 만들기에서 「조사해요」 다음에 할 일은 어느 것인가요?","options":[{"t":"제작 방법과 넣을 내용을 모둠 친구들과 계획하기","correct":true},{"t":"곧바로 누리집에 공유하기","mis":"SC6-1-u1-X38"},{"t":"다른 모둠 동영상에 댓글 쓰기","mis":"SC6-1-u1-X38"},{"t":"주제를 처음부터 다시 정하기","mis":"SC6-1-u1-X38"}],"explanation":["차례를 떠올려요.","조사 → 계획이에요.","계획하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#17','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C9',3,'mc','auto','나래반 일지 ②의 컵 ㉯ 용액과 같은 무리에 드는 것은 어느 것인가요?',ARRAY['SC6-1-u1-X15']::text[],false,'{"seq":17,"concept":"SC6-1-u1-C9","difficulty":3,"kind":"mc","stem":"나래반 일지 ②의 컵 ㉯ 용액과 같은 무리에 드는 것은 어느 것인가요?","options":[{"t":"일지 ①의 ㉠ 식초","correct":true},{"t":"일지 ①의 ㉢ 제빵 소다 용액","mis":"SC6-1-u1-X15"},{"t":"일지 ①의 ㉣ 빨랫비누 물","mis":"SC6-1-u1-X15"},{"t":"석회수","mis":"SC6-1-u1-X15"}],"explanation":["㉯의 성질을 찾아요.","산성이에요.","식초예요."],"asset":{"type":"passage","lines":["컵 ㉮와 ㉯에 든 용액은 둘 다 색깔이 없고 투명하다.","㉮에 페놀프탈레인 용액 — 붉은색으로 변함","㉯에 페놀프탈레인 용액 — 변화 없음","㉯에 푸른색 리트머스 시험지 — 붉은색으로 변함"],"title":"나래반 일지 ② 투명한 두 컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#18','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C12',3,'mc','auto','두 용액의 성질을 공정하게 견주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X21','SC6-1-u1-X19']::text[],false,'{"seq":18,"concept":"SC6-1-u1-C12","difficulty":3,"kind":"mc","stem":"두 용액의 성질을 공정하게 견주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 용액에 같은 크기의 같은 물질을 넣고 같은 시간 동안 관찰한다","correct":true},{"t":"한 용액에만 큰 조각을 넣는다","mis":"SC6-1-u1-X21"},{"t":"한 용액은 짧게, 다른 용액은 오래 관찰한다","mis":"SC6-1-u1-X19"},{"t":"용액마다 서로 다른 물질을 넣는다","mis":"SC6-1-u1-X21"}],"explanation":["다르게 할 것은 하나예요.","용액만 달라요.","나머지는 같게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#19','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C14',3,'mc','auto','나래반 일지 ⑥의 은호의 말을 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X28','SC6-1-u1-X33']::text[],false,'{"seq":19,"concept":"SC6-1-u1-C14","difficulty":3,"kind":"mc","stem":"나래반 일지 ⑥의 은호의 말을 바로잡는 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일지 ④에서 붉은 양배추 용액의 색이 변해 성질이 변했음을 확인했다","correct":true},{"t":"일지 ③에서 껍데기가 녹았다","mis":"SC6-1-u1-X17"},{"t":"일지 ⑤에서 도마를 식초로 닦았다","mis":"SC6-1-u1-X28"},{"t":"일지 ⑦에서 조각상이 훼손되었다","mis":"SC6-1-u1-X33"}],"explanation":["섞은 기록을 찾아요.","일지 ④예요.","색이 변했어요."],"asset":{"type":"passage","lines":["도윤 — 「투명한 용액은 색깔이 없는 거야.」","서아 — 「지시약이 다르면 나뉘는 무리도 달라.」","은호 — 「산성 용액과 염기성 용액은 섞어도 그대로야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"나래반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#20','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C18',3,'mc','auto','「없애려는 물질과 반대 성질의 용액을 이용한다」로 설명할 수 없는 것은 어느 것인가요?',ARRAY['SC6-1-u1-X28']::text[],false,'{"seq":20,"concept":"SC6-1-u1-C18","difficulty":3,"kind":"mc","stem":"「없애려는 물질과 반대 성질의 용액을 이용한다」로 설명할 수 없는 것은 어느 것인가요?","options":[{"t":"레몬즙으로 음식에 신맛을 낸다","correct":true},{"t":"식초로 도마의 비린내를 약하게 한다","mis":"SC6-1-u1-X28"},{"t":"제산제로 속 쓰림을 약하게 한다","mis":"SC6-1-u1-X28"},{"t":"변기 청소용 세제로 변기의 때를 없앤다","mis":"SC6-1-u1-X28"}],"explanation":["없애려는 것이 있는지 봐요.","신맛은 성질을 직접 써요.","레몬즙 신맛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#21','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C20',3,'mc','auto','산성비가 내린 숲의 피해와 그 원인을 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u1-X31','SC6-1-u1-X36','SC6-1-u1-X33']::text[],false,'{"seq":21,"concept":"SC6-1-u1-C20","difficulty":3,"kind":"mc","stem":"산성비가 내린 숲의 피해와 그 원인을 바르게 말한 것은 어느 것인가요?","options":[{"t":"대기 중 오염 물질이 빗물에 녹아 산성비가 되어 삼림이 황폐해진다","correct":true},{"t":"바닷물이 산성을 띠어 숲이 황폐해진다","mis":"SC6-1-u1-X31"},{"t":"숲은 저절로 황폐해지며 산성비와 관계없다","mis":"SC6-1-u1-X36"},{"t":"산성비는 문화재에만 피해를 준다","mis":"SC6-1-u1-X33"}],"explanation":["산성비의 원인이에요.","오염 물질이에요.","삼림이 황폐해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#22','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C2',3,'mc','auto','보물 찾기에서 「용액을 섞으면 색깔이 변하는 경우도 있고 변하지 않는 경우도 있다」의 근거는 어느 것인가요?',ARRAY['SC6-1-u1-X03','SC6-1-u1-X01']::text[],false,'{"seq":22,"concept":"SC6-1-u1-C2","difficulty":3,"kind":"mc","stem":"보물 찾기에서 「용액을 섞으면 색깔이 변하는 경우도 있고 변하지 않는 경우도 있다」의 근거는 어느 것인가요?","options":[{"t":"제빵 소다 용액 자리는 붉게 변하고 물 자리는 그대로였다","correct":true},{"t":"두 자리가 모두 붉게 변했다","mis":"SC6-1-u1-X03"},{"t":"두 자리가 모두 그대로였다","mis":"SC6-1-u1-X03"},{"t":"물 자리만 붉게 변했다","mis":"SC6-1-u1-X01"}],"explanation":["두 자리를 견줘요.","한 자리만 변했어요.","제빵 소다 용액 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#23','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C9',4,'mc','auto','나래반 일지 ①과 ②를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SC6-1-u1-X08','SC6-1-u1-X16','SC6-1-u1-X10']::text[],false,'{"seq":23,"concept":"SC6-1-u1-C9","difficulty":4,"kind":"mc","stem":"나래반 일지 ①과 ②를 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"겉보기 성질이 비슷한 용액도 여러 지시약으로 산성과 염기성으로 나눌 수 있다","correct":true},{"t":"투명한 용액은 지시약으로 나눌 수 없다","mis":"SC6-1-u1-X08"},{"t":"지시약마다 나뉘는 무리가 다르다","mis":"SC6-1-u1-X16"},{"t":"지시약은 붉은 양배추 용액 하나뿐이다","mis":"SC6-1-u1-X10"}],"explanation":["①은 양배추, ②는 다른 지시약이에요.","투명해도 나뉘었어요.","여러 지시약으로 나눠요."],"asset":{"type":"passage","lines":["컵 ㉮와 ㉯에 든 용액은 둘 다 색깔이 없고 투명하다.","㉮에 페놀프탈레인 용액 — 붉은색으로 변함","㉯에 페놀프탈레인 용액 — 변화 없음","㉯에 푸른색 리트머스 시험지 — 붉은색으로 변함"],"title":"나래반 일지 ② 투명한 두 컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#24','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C9',4,'essay','teacher','나래반 일지 ②의 두 컵 ㉮·㉯가 각각 어떤 성질의 용액인지 근거를 들어 쓰고, 두 컵에 붉은 양배추 용액을 떨어뜨리면 어떤 색 계열로 변할지 예상하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u1-C9","difficulty":4,"kind":"essay","stem":"나래반 일지 ②의 두 컵 ㉮·㉯가 각각 어떤 성질의 용액인지 근거를 들어 쓰고, 두 컵에 붉은 양배추 용액을 떨어뜨리면 어떤 색 계열로 변할지 예상하세요.","answer_guide":{"answer":"예: ㉮는 페놀프탈레인 용액이 붉은색으로 변했으므로 염기성 용액이다. ㉯는 페놀프탈레인 용액에 변화가 없고 푸른색 리트머스 시험지가 붉은색으로 변했으므로 산성 용액이다. 붉은 양배추 용액을 떨어뜨리면 ㉮는 푸른색이나 노란색 계열로, ㉯는 붉은색 계열로 변할 것이다. 두 용액은 겉보기로는 구별하기 어렵지만 지시약으로 나눌 수 있다.","scoring_points":["㉮를 염기성으로 근거와 함께 썼는가","㉯를 산성으로 근거와 함께 썼는가","붉은 양배추 용액의 색 계열을 바르게 예상했는가"]},"explanation":["㉮부터 판단해요.","㉯를 판단해요.","양배추 색을 예상해요."],"asset":{"type":"passage","lines":["컵 ㉮와 ㉯에 든 용액은 둘 다 색깔이 없고 투명하다.","㉮에 페놀프탈레인 용액 — 붉은색으로 변함","㉯에 페놀프탈레인 용액 — 변화 없음","㉯에 푸른색 리트머스 시험지 — 붉은색으로 변함"],"title":"나래반 일지 ② 투명한 두 컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_a#25','sci',6,1,'u1','','g6_1_sci_u1_review_a','unit_review','SC6-1-u1-C4',4,'essay','teacher','나래반 일지 ⑥의 도윤의 말이 옳지 않은 까닭을 예를 들어 쓰고, 여섯 가지 용액을 나눌 수 있는 알맞은 분류 기준 두 가지와 그것이 알맞은 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u1-C4","difficulty":4,"kind":"essay","stem":"나래반 일지 ⑥의 도윤의 말이 옳지 않은 까닭을 예를 들어 쓰고, 여섯 가지 용액을 나눌 수 있는 알맞은 분류 기준 두 가지와 그것이 알맞은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「투명하다」는 속까지 환히 비치도록 맑다는 뜻으로 「색깔이 없다」와 다르다. 식초는 노란색이지만 투명하므로 도윤의 말은 옳지 않다. 알맞은 분류 기준으로는 「투명한가?」와 「흔들었을 때 거품이 5초 이상 유지되는가?」가 있다. 이 기준들은 객관적이고 명확한 질문이라 누가 분류해도 같은 결과가 나온다.","scoring_points":["투명함과 색깔이 다름을 썼는가","식초 같은 예를 들었는가","알맞은 기준 두 가지와 그 까닭을 썼는가"]},"explanation":["도윤의 말을 따져요.","예를 들어요.","기준과 까닭을 써요."],"asset":{"type":"passage","lines":["도윤 — 「투명한 용액은 색깔이 없는 거야.」","서아 — 「지시약이 다르면 나뉘는 무리도 달라.」","은호 — 「산성 용액과 염기성 용액은 섞어도 그대로야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"나래반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#1','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C8',1,'ox','auto','붉은 양배추 용액은 염기성 용액에서 붉은색 계열로 변해요.',ARRAY['SC6-1-u1-X13']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C8","difficulty":1,"kind":"ox","stem":"붉은 양배추 용액은 염기성 용액에서 붉은색 계열로 변해요.","answer":"X","reason_options":[{"t":"염기성 용액에서는 푸른색이나 노란색 계열로 변하기 때문에","correct":true},{"t":"붉은 양배추 용액은 어느 용액에서나 붉은색이기 때문에","mis":"SC6-1-u1-X13"}],"mis":"SC6-1-u1-X13","explanation":["염기성 용액이에요.","푸른색이나 노란색 계열이에요.","붉은색 계열이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#2','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C7',1,'ox','auto','산성 용액에 페놀프탈레인 용액을 떨어뜨리면 붉은색으로 변해요.',ARRAY['SC6-1-u1-X12']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C7","difficulty":1,"kind":"ox","stem":"산성 용액에 페놀프탈레인 용액을 떨어뜨리면 붉은색으로 변해요.","answer":"X","reason_options":[{"t":"산성 용액에서는 페놀프탈레인 용액에 변화가 없기 때문에","correct":true},{"t":"페놀프탈레인 용액은 산성 용액에서 붉어지기 때문에","mis":"SC6-1-u1-X12"}],"mis":"SC6-1-u1-X12","explanation":["페놀프탈레인 용액이에요.","염기성에서만 붉어요.","산성에서는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#3','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C11',1,'ox','auto','염기성 용액은 삶은 닭 가슴살을 녹여요.',ARRAY['SC6-1-u1-X17']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C11","difficulty":1,"kind":"ox","stem":"염기성 용액은 삶은 닭 가슴살을 녹여요.","answer":"O","reason_options":[{"t":"염기성 용액은 닭 가슴살의 주요 성분인 단백질과 반응하기 때문에","correct":true},{"t":"닭 가슴살은 산성 용액에서만 녹기 때문에","mis":"SC6-1-u1-X17"}],"mis":"SC6-1-u1-X17","explanation":["닭 가슴살의 성분이에요.","단백질이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#4','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C14',1,'ox','auto','산성 용액과 염기성 용액을 섞으면 처음의 성질이 점점 약해져요.',ARRAY['SC6-1-u1-X23']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C14","difficulty":1,"kind":"ox","stem":"산성 용액과 염기성 용액을 섞으면 처음의 성질이 점점 약해져요.","answer":"O","reason_options":[{"t":"두 용액이 만나면 서로의 성질이 약해지기 때문에","correct":true},{"t":"섞으면 두 성질이 모두 더 강해지기 때문에","mis":"SC6-1-u1-X23"}],"mis":"SC6-1-u1-X23","explanation":["섞을 때의 변화예요.","약해져요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#5','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C17',1,'ox','auto','하수구 세정제는 염기성 용액이에요.',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C17","difficulty":1,"kind":"ox","stem":"하수구 세정제는 염기성 용액이에요.","answer":"O","reason_options":[{"t":"단백질인 머리카락을 녹이는 염기성 용액이기 때문에","correct":true},{"t":"하수구 세정제는 산성 용액이기 때문에","mis":"SC6-1-u1-X27"}],"mis":"SC6-1-u1-X27","explanation":["머리카락은 단백질이에요.","단백질은 염기성과 반응해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#6','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C19',1,'ox','auto','토양 산성화는 땅(흙)이 산성을 띠는 현상이에요.',ARRAY['SC6-1-u1-X31']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C19","difficulty":1,"kind":"ox","stem":"토양 산성화는 땅(흙)이 산성을 띠는 현상이에요.","answer":"O","reason_options":[{"t":"토양은 땅(흙)을 뜻하기 때문에","correct":true},{"t":"토양 산성화는 바닷물이 산성을 띠는 현상이기 때문에","mis":"SC6-1-u1-X31"}],"mis":"SC6-1-u1-X31","explanation":["토양은 흙이에요.","흙이 산성을 띠어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#7','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C21',1,'ox','auto','화석 연료를 태우면 대기에 오염 물질이 늘어나 산성비의 원인이 될 수 있어요.',ARRAY['SC6-1-u1-X36']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C21","difficulty":1,"kind":"ox","stem":"화석 연료를 태우면 대기에 오염 물질이 늘어나 산성비의 원인이 될 수 있어요.","answer":"O","reason_options":[{"t":"사람의 활동으로 늘어난 오염 물질이 빗물에 녹기 때문에","correct":true},{"t":"화석 연료는 산성화와 관계없기 때문에","mis":"SC6-1-u1-X36"}],"mis":"SC6-1-u1-X36","explanation":["산성비의 원인이에요.","오염 물질이 늘어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#8','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C22',1,'ox','auto','나래반 일지 ⑧의 모둠이 원인·현황·전망·대책을 나누어 맡은 것은 알맞아요.',ARRAY['SC6-1-u1-X39']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C22","difficulty":1,"kind":"ox","stem":"나래반 일지 ⑧의 모둠이 원인·현황·전망·대책을 나누어 맡은 것은 알맞아요.","answer":"O","reason_options":[{"t":"역할을 나누어 협력하며 조사하기 때문에","correct":true},{"t":"한 사람이 모두 조사해야 정확하기 때문에","mis":"SC6-1-u1-X39"}],"mis":"SC6-1-u1-X39","explanation":["조사 방법이에요.","역할을 나눠요.","맞는 말이에요."],"asset":{"type":"passage","lines":["주제 — 토양 산성화","조사 — 원인·현황·전망·대책을 모둠원이 나누어 맡음","자료 — 누리집 사진을 쓸 때 출처와 주소를 함께 적음","공유 — 학급 누리집에 올리고 다른 모둠의 잘한 점을 댓글로 씀"],"title":"나래반 일지 ⑧ 알림 동영상 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#9','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C4',2,'ox','auto','나래반 일지 ⑥의 도윤의 말처럼 투명한 용액은 모두 색깔이 없어요.',ARRAY['SC6-1-u1-X06']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C4","difficulty":2,"kind":"ox","stem":"나래반 일지 ⑥의 도윤의 말처럼 투명한 용액은 모두 색깔이 없어요.","answer":"X","reason_options":[{"t":"식초처럼 색깔이 있어도 투명한 용액이 있기 때문에","correct":true},{"t":"「투명하다」는 「색깔이 없다」와 같은 뜻이기 때문에","mis":"SC6-1-u1-X06"}],"mis":"SC6-1-u1-X06","explanation":["두 낱말의 뜻을 견줘요.","투명은 맑게 비치는 것이에요.","모두는 아니에요."],"asset":{"type":"passage","lines":["도윤 — 「투명한 용액은 색깔이 없는 거야.」","서아 — 「지시약이 다르면 나뉘는 무리도 달라.」","은호 — 「산성 용액과 염기성 용액은 섞어도 그대로야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"나래반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#10','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C8',2,'mc','auto','나래반 일지 ②의 컵 ㉯에 붉은 양배추 용액을 떨어뜨리면 어떻게 될까요?',ARRAY['SC6-1-u1-X13']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C8","difficulty":2,"kind":"mc","stem":"나래반 일지 ②의 컵 ㉯에 붉은 양배추 용액을 떨어뜨리면 어떻게 될까요?","options":[{"t":"붉은색 계열로 변한다","correct":true},{"t":"푸른색이나 노란색 계열로 변한다","mis":"SC6-1-u1-X13"},{"t":"아무 변화가 없다","mis":"SC6-1-u1-X13"},{"t":"투명해진다","mis":"SC6-1-u1-X13"}],"explanation":["먼저 ㉯의 성질을 찾아요.","산성 용액이에요.","붉은색 계열이에요."],"asset":{"type":"passage","lines":["컵 ㉮와 ㉯에 든 용액은 둘 다 색깔이 없고 투명하다.","㉮에 페놀프탈레인 용액 — 붉은색으로 변함","㉯에 페놀프탈레인 용액 — 변화 없음","㉯에 푸른색 리트머스 시험지 — 붉은색으로 변함"],"title":"나래반 일지 ② 투명한 두 컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#11','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C11',2,'mc','auto','나래반 일지 ③에서 삶은 달걀흰자가 식초에서는 그대로였지만 묽은 수산화 나트륨 용액에서는 흐물흐물해진 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X20','SC6-1-u1-X19']::text[],false,'{"seq":11,"concept":"SC6-1-u1-C11","difficulty":2,"kind":"mc","stem":"나래반 일지 ③에서 삶은 달걀흰자가 식초에서는 그대로였지만 묽은 수산화 나트륨 용액에서는 흐물흐물해진 까닭은 무엇인가요?","options":[{"t":"흰자의 주요 성분인 단백질은 염기성 용액과 반응하기 때문에","correct":true},{"t":"단백질은 산성 용액과 반응하기 때문에","mis":"SC6-1-u1-X17"},{"t":"흰자의 주요 성분이 탄산 칼슘이기 때문에","mis":"SC6-1-u1-X20"},{"t":"흰자를 너무 오래 삶았기 때문에","mis":"SC6-1-u1-X19"}],"explanation":["흰자의 성분이에요.","단백질이에요.","염기성과 반응해요."],"asset":{"type":"passage","lines":["날달걀을 식초에 담가 두었다 — 껍데기에서 기포가 생기며 껍데기가 녹았다.","삶은 달걀흰자 조각을 식초에 담가 두었다 — 변화가 없었다.","선생님이 묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣어 보여 주셨다","　　— 시간이 지나면서 흐물흐물해졌다."],"title":"나래반 일지 ③ 달걀 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#12','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C13',2,'mc','auto','나래반 일지 ④와 반대로 묽은 수산화 나트륨 용액에 묽은 염산을 계속 넣으면 붉은 양배추 용액의 색은 어떻게 될까요?',ARRAY['SC6-1-u1-X22','SC6-1-u1-X23']::text[],false,'{"seq":12,"concept":"SC6-1-u1-C13","difficulty":2,"kind":"mc","stem":"나래반 일지 ④와 반대로 묽은 수산화 나트륨 용액에 묽은 염산을 계속 넣으면 붉은 양배추 용액의 색은 어떻게 될까요?","options":[{"t":"노란색 계열에서 붉은색 계열로 변한다","correct":true},{"t":"붉은색 계열에서 노란색 계열로 변한다","mis":"SC6-1-u1-X22"},{"t":"노란색 계열 그대로이다","mis":"SC6-1-u1-X23"},{"t":"붉은색 계열 그대로이다","mis":"SC6-1-u1-X23"}],"explanation":["처음은 염기성이에요.","산성을 넣어요.","붉은색 계열 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#13','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C18',2,'mc','auto','나래반 일지 ⑤에서 아빠가 쓰신 변기 청소용 세제가 산성인 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X28','SC6-1-u1-X20']::text[],false,'{"seq":13,"concept":"SC6-1-u1-C18","difficulty":2,"kind":"mc","stem":"나래반 일지 ⑤에서 아빠가 쓰신 변기 청소용 세제가 산성인 까닭은 무엇인가요?","options":[{"t":"변기의 때와 냄새가 염기성 물질이기 때문에","correct":true},{"t":"변기의 때가 산성이기 때문에","mis":"SC6-1-u1-X28"},{"t":"산성 세제는 모든 때를 없애기 때문에","mis":"SC6-1-u1-X28"},{"t":"변기가 단백질로 되어 있기 때문에","mis":"SC6-1-u1-X20"}],"explanation":["없애려는 것의 성질이에요.","변기의 때는 염기성이에요.","반대 성질을 써요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#14','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C20',2,'mc','auto','나래반 일지 ⑦의 대리암 조각상과 조개껍데기의 공통점은 어느 것인가요?',ARRAY['SC6-1-u1-X20','SC6-1-u1-X33','SC6-1-u1-X18']::text[],false,'{"seq":14,"concept":"SC6-1-u1-C20","difficulty":2,"kind":"mc","stem":"나래반 일지 ⑦의 대리암 조각상과 조개껍데기의 공통점은 어느 것인가요?","options":[{"t":"둘 다 주요 성분이 탄산 칼슘이라 산성에 녹을 수 있다","correct":true},{"t":"둘 다 주요 성분이 단백질이다","mis":"SC6-1-u1-X20"},{"t":"둘 다 산성화와 관계없다","mis":"SC6-1-u1-X33"},{"t":"둘 다 염기성 용액에만 녹는다","mis":"SC6-1-u1-X18"}],"explanation":["성분을 떠올려요.","탄산 칼슘이에요.","산성에 녹아요."],"asset":{"type":"passage","lines":["바닷물이 산성을 띠면 조개껍데기가 얇아지고 산호가 피해를 입어요.","조개껍데기와 산호의 주요 성분은 탄산 칼슘이에요.","과학관 앞 대리암 조각상도 산성비로 조금씩 훼손되고 있어요.","우리의 약속 — 가까운 곳은 걸어서, 먼 곳은 대중교통으로!"],"title":"나래반 일지 ⑦ 바닷가 과학관 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#15','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C21',2,'mc','auto','산성화의 원인과 대책을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X37']::text[],false,'{"seq":15,"concept":"SC6-1-u1-C21","difficulty":2,"kind":"mc","stem":"산성화의 원인과 대책을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"자동차 배기가스 — 대중교통 이용하기","correct":true},{"t":"화학 비료의 과도한 사용 — 화학 비료 더 쓰기","mis":"SC6-1-u1-X37"},{"t":"화석 연료 연소 — 화석 연료 더 태우기","mis":"SC6-1-u1-X37"},{"t":"대중교통 이용 — 자동차 더 타기","mis":"SC6-1-u1-X37"}],"explanation":["원인을 줄이는 것이 대책이에요.","배기가스를 줄여요.","대중교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#16','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C23',2,'mc','auto','나래반 일지 ⑧의 주제와 가장 관계 깊은 환경 과학자는 누구인가요?',ARRAY['SC6-1-u1-X40']::text[],false,'{"seq":16,"concept":"SC6-1-u1-C23","difficulty":2,"kind":"mc","stem":"나래반 일지 ⑧의 주제와 가장 관계 깊은 환경 과학자는 누구인가요?","options":[{"t":"토양 환경 과학자","correct":true},{"t":"대기 환경 과학자","mis":"SC6-1-u1-X40"},{"t":"수질 환경 과학자","mis":"SC6-1-u1-X40"},{"t":"동영상 편집자","mis":"SC6-1-u1-X40"}],"explanation":["주제를 읽어요.","토양 산성화예요.","토양 환경 과학자예요."],"asset":{"type":"passage","lines":["주제 — 토양 산성화","조사 — 원인·현황·전망·대책을 모둠원이 나누어 맡음","자료 — 누리집 사진을 쓸 때 출처와 주소를 함께 적음","공유 — 학급 누리집에 올리고 다른 모둠의 잘한 점을 댓글로 씀"],"title":"나래반 일지 ⑧ 알림 동영상 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#17','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C9',3,'mc','auto','붉은 양배추 용액으로 나눈 일지 ①의 결과와 리트머스 시험지로 나눈 결과가 같은 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X16','SC6-1-u1-X10']::text[],false,'{"seq":17,"concept":"SC6-1-u1-C9","difficulty":3,"kind":"mc","stem":"붉은 양배추 용액으로 나눈 일지 ①의 결과와 리트머스 시험지로 나눈 결과가 같은 까닭은 무엇인가요?","options":[{"t":"지시약마다 색은 달라도 산성과 염기성으로 나뉘는 결과는 같기 때문에","correct":true},{"t":"지시약이 다르면 나뉘는 결과도 다르기 때문에","mis":"SC6-1-u1-X16"},{"t":"두 지시약은 같은 용액에서 같은 색으로 변하기 때문에","mis":"SC6-1-u1-X10"},{"t":"붉은 양배추 용액만 진짜 지시약이기 때문에","mis":"SC6-1-u1-X10"}],"explanation":["지시약은 여러 가지예요.","색은 달라요.","분류 결과는 같아요."],"asset":{"type":"passage","lines":["㉠ 식초 — 붉은색 계열","㉡ 레몬즙 — 붉은색 계열","㉢ 제빵 소다 용액 — 푸른색 계열","㉣ 빨랫비누 물 — 푸른색이나 노란색 계열","㉤ 구연산 용액 — 붉은색 계열"],"title":"나래반 일지 ① 붉은 양배추 용액을 떨어뜨린 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#18','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C10',3,'mc','auto','알 수 없는 용액에 조개껍데기를 넣었더니 기포가 생기며 녹았고, 삶은 닭 가슴살은 오래 두어도 변화가 없었어요. 이 용액은 어떤 용액인가요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X20','SC6-1-u1-X19']::text[],false,'{"seq":18,"concept":"SC6-1-u1-C10","difficulty":3,"kind":"mc","stem":"알 수 없는 용액에 조개껍데기를 넣었더니 기포가 생기며 녹았고, 삶은 닭 가슴살은 오래 두어도 변화가 없었어요. 이 용액은 어떤 용액인가요?","options":[{"t":"산성 용액","correct":true},{"t":"염기성 용액","mis":"SC6-1-u1-X17"},{"t":"껍데기와 닭 가슴살을 모두 녹이는 용액","mis":"SC6-1-u1-X20"},{"t":"알 수 없다","mis":"SC6-1-u1-X19"}],"explanation":["껍데기를 녹였어요.","단백질은 그대로예요.","산성 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#19','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C14',3,'ox','auto','나래반 일지 ⑥의 은호의 말은 옳아요.',ARRAY['SC6-1-u1-X23']::text[],false,'{"seq":19,"concept":"SC6-1-u1-C14","difficulty":3,"kind":"ox","stem":"나래반 일지 ⑥의 은호의 말은 옳아요.","answer":"X","reason_options":[{"t":"섞으면 처음의 성질이 약해지다가 반대 성질로 변하기 때문에","correct":true},{"t":"산성과 염기성은 섞어도 서로 영향을 주지 않기 때문에","mis":"SC6-1-u1-X23"}],"mis":"SC6-1-u1-X23","explanation":["일지 ④를 떠올려요.","성질이 변했어요.","옳지 않아요."],"asset":{"type":"passage","lines":["도윤 — 「투명한 용액은 색깔이 없는 거야.」","서아 — 「지시약이 다르면 나뉘는 무리도 달라.」","은호 — 「산성 용액과 염기성 용액은 섞어도 그대로야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"나래반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#20','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C18',3,'mc','auto','머리카락이 막은 하수구에는 식초보다 하수구 세정제가 알맞은 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X27','SC6-1-u1-X17','SC6-1-u1-X28']::text[],false,'{"seq":20,"concept":"SC6-1-u1-C18","difficulty":3,"kind":"mc","stem":"머리카락이 막은 하수구에는 식초보다 하수구 세정제가 알맞은 까닭은 무엇인가요?","options":[{"t":"머리카락의 단백질은 염기성 용액과 반응하는데 식초는 산성이기 때문에","correct":true},{"t":"식초가 염기성이기 때문에","mis":"SC6-1-u1-X27"},{"t":"식초가 단백질을 가장 잘 녹이기 때문에","mis":"SC6-1-u1-X17"},{"t":"하수구 세정제는 지시약이기 때문에","mis":"SC6-1-u1-X28"}],"explanation":["머리카락은 단백질이에요.","단백질은 염기성과 반응해요.","세정제가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#21','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C21',3,'mc','auto','산성화된 호수에 염기성 물질을 뿌리는 것과 같은 원리를 이용한 예는 어느 것인가요?',ARRAY['SC6-1-u1-X26','SC6-1-u1-X37']::text[],false,'{"seq":21,"concept":"SC6-1-u1-C21","difficulty":3,"kind":"mc","stem":"산성화된 호수에 염기성 물질을 뿌리는 것과 같은 원리를 이용한 예는 어느 것인가요?","options":[{"t":"산성이 강해진 흙에 석회 가루를 뿌린다","correct":true},{"t":"호수에 산성 물질을 더 넣는다","mis":"SC6-1-u1-X26"},{"t":"호수 물을 끓인다","mis":"SC6-1-u1-X26"},{"t":"호수 둘레에 자동차를 더 다니게 한다","mis":"SC6-1-u1-X37"}],"explanation":["반대 성질로 약하게 해요.","석회 가루는 염기성이에요.","흙에 뿌려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#22','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C8',3,'mc','auto','붉은 양배추 용액의 색을 관찰할 때 비슷한 계열의 색으로 보는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X14','SC6-1-u1-X13']::text[],false,'{"seq":22,"concept":"SC6-1-u1-C8","difficulty":3,"kind":"mc","stem":"붉은 양배추 용액의 색을 관찰할 때 비슷한 계열의 색으로 보는 까닭은 무엇인가요?","options":[{"t":"같은 지시약이라도 용액의 농도에 따라 색에 차이가 있기 때문에","correct":true},{"t":"지시약이 오래되어 색이 바래기 때문에","mis":"SC6-1-u1-X14"},{"t":"색깔은 성질과 관계없기 때문에","mis":"SC6-1-u1-X14"},{"t":"산성과 염기성에서 같은 색이 나오기 때문에","mis":"SC6-1-u1-X13"}],"explanation":["진하기가 달라요.","색도 조금씩 달라요.","계열로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#23','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C11',4,'mc','auto','나래반 일지 ③을 정리한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X20','SC6-1-u1-X17','SC6-1-u1-X19']::text[],false,'{"seq":23,"concept":"SC6-1-u1-C11","difficulty":4,"kind":"mc","stem":"나래반 일지 ③을 정리한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산성 용액은 탄산 칼슘이 주성분인 껍데기를, 염기성 용액은 단백질이 주성분인 흰자를 녹이므로 두 용액은 성질이 다르다","correct":true},{"t":"두 용액은 같은 물질을 녹이므로 성질이 같다","mis":"SC6-1-u1-X20"},{"t":"식초는 껍데기와 흰자를 모두 녹인다","mis":"SC6-1-u1-X17"},{"t":"염기성 용액은 넣자마자 흰자를 녹인다","mis":"SC6-1-u1-X19"}],"explanation":["세 기록을 모아요.","녹인 것이 달라요.","성질이 서로 달라요."],"asset":{"type":"passage","lines":["날달걀을 식초에 담가 두었다 — 껍데기에서 기포가 생기며 껍데기가 녹았다.","삶은 달걀흰자 조각을 식초에 담가 두었다 — 변화가 없었다.","선생님이 묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣어 보여 주셨다","　　— 시간이 지나면서 흐물흐물해졌다."],"title":"나래반 일지 ③ 달걀 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#24','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C11',4,'essay','teacher','나래반 일지 ③의 세 가지 결과를 정리하고, 산성 용액과 염기성 용액이 서로 다른 물질을 녹인 까닭을 주요 성분으로 설명하세요. 결과를 볼 때 주의할 점도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u1-C11","difficulty":4,"kind":"essay","stem":"나래반 일지 ③의 세 가지 결과를 정리하고, 산성 용액과 염기성 용액이 서로 다른 물질을 녹인 까닭을 주요 성분으로 설명하세요. 결과를 볼 때 주의할 점도 쓰세요.","answer_guide":{"answer":"예: 날달걀을 식초에 담그면 껍데기에서 기포가 생기며 녹았고, 삶은 달걀흰자는 식초에서 변화가 없었다. 묽은 수산화 나트륨 용액에 넣은 삶은 달걀흰자는 시간이 지나면서 흐물흐물해졌다. 달걀 껍데기의 주요 성분은 탄산 칼슘이라 산성 용액과 반응하고, 흰자의 주요 성분은 단백질이라 염기성 용액과 반응하기 때문이다. 단백질과의 반응은 오래 걸릴 수 있으므로 넣자마자 판단하지 말고 시간을 두고 관찰해야 한다.","scoring_points":["세 가지 결과를 바르게 정리했는가","탄산 칼슘·단백질로 까닭을 설명했는가","시간을 두고 관찰해야 한다는 등 주의점을 썼는가"]},"explanation":["결과를 모아요.","성분으로 설명해요.","주의점을 써요."],"asset":{"type":"passage","lines":["날달걀을 식초에 담가 두었다 — 껍데기에서 기포가 생기며 껍데기가 녹았다.","삶은 달걀흰자 조각을 식초에 담가 두었다 — 변화가 없었다.","선생님이 묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣어 보여 주셨다","　　— 시간이 지나면서 흐물흐물해졌다."],"title":"나래반 일지 ③ 달걀 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_b#25','sci',6,1,'u1','','g6_1_sci_u1_review_b','unit_review','SC6-1-u1-C20',4,'essay','teacher','나래반 일지 ⑦의 피해 두 가지를 쓰고, 두 피해가 생기는 공통 까닭을 주요 성분으로 설명하세요. 안내판의 약속이 왜 필요한지도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u1-C20","difficulty":4,"kind":"essay","stem":"나래반 일지 ⑦의 피해 두 가지를 쓰고, 두 피해가 생기는 공통 까닭을 주요 성분으로 설명하세요. 안내판의 약속이 왜 필요한지도 쓰세요.","answer_guide":{"answer":"예: 바닷물이 산성을 띠면 조개껍데기가 얇아지고, 산성비로 대리암 조각상이 조금씩 훼손된다. 조개껍데기와 대리암의 주요 성분은 모두 탄산 칼슘인데, 탄산 칼슘은 산성 용액에 녹는 성질이 있기 때문이다. 가까운 곳은 걷고 먼 곳은 대중교통을 이용하면 자동차에서 나오는 오염 물질과 이산화 탄소가 줄어 산성화를 줄일 수 있으므로 이 약속이 필요하다.","scoring_points":["피해 두 가지를 썼는가","탄산 칼슘이 산성에 녹는다는 공통 까닭을 썼는가","약속이 산성화를 줄이는 까닭을 썼는가"]},"explanation":["피해를 써요.","성분으로 묶어요.","약속의 까닭을 써요."],"asset":{"type":"passage","lines":["바닷물이 산성을 띠면 조개껍데기가 얇아지고 산호가 피해를 입어요.","조개껍데기와 산호의 주요 성분은 탄산 칼슘이에요.","과학관 앞 대리암 조각상도 산성비로 조금씩 훼손되고 있어요.","우리의 약속 — 가까운 곳은 걸어서, 먼 곳은 대중교통으로!"],"title":"나래반 일지 ⑦ 바닷가 과학관 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#1','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C9',1,'sa','auto','나래반 일지 ①의 ㉢ 제빵 소다 용액은 어떤 성질의 용액인가요? (□□□ 용액)','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u1-C9","difficulty":1,"kind":"sa","stem":"나래반 일지 ①의 ㉢ 제빵 소다 용액은 어떤 성질의 용액인가요? (□□□ 용액)","answer":["염기성","염기성 용액"],"explanation":["푸른색 계열이에요.","산성의 반대예요.","염기성 용액이에요."],"asset":{"type":"passage","lines":["㉠ 식초 — 붉은색 계열","㉡ 레몬즙 — 붉은색 계열","㉢ 제빵 소다 용액 — 푸른색 계열","㉣ 빨랫비누 물 — 푸른색이나 노란색 계열","㉤ 구연산 용액 — 붉은색 계열"],"title":"나래반 일지 ① 붉은 양배추 용액을 떨어뜨린 결과"},"mis":"SC6-1-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#2','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C7',1,'mc','auto','페놀프탈레인 용액을 붉은색으로 변하게 하는 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X12']::text[],false,'{"seq":2,"concept":"SC6-1-u1-C7","difficulty":1,"kind":"mc","stem":"페놀프탈레인 용액을 붉은색으로 변하게 하는 용액은 어느 것인가요?","options":[{"t":"석회수","correct":true},{"t":"식초","mis":"SC6-1-u1-X12"},{"t":"레몬즙","mis":"SC6-1-u1-X12"},{"t":"묽은 염산","mis":"SC6-1-u1-X12"}],"explanation":["염기성 용액을 찾아요.","식초·레몬즙·묽은 염산은 산성이에요.","석회수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#3','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C10',1,'sa','auto','산성 용액과 반응하는 달걀 껍데기의 주요 성분을 쓰세요. (□□ 칼슘)','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u1-C10","difficulty":1,"kind":"sa","stem":"산성 용액과 반응하는 달걀 껍데기의 주요 성분을 쓰세요. (□□ 칼슘)","answer":["탄산","탄산 칼슘","탄산칼슘"],"explanation":["조개껍데기와 같아요.","두 글자예요.","탄산 칼슘이에요."],"mis":"SC6-1-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#4','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C14',1,'mc','auto','나래반 일지 ④에서 마지막 용액은 어떤 성질을 띠나요?',ARRAY['SC6-1-u1-X22','SC6-1-u1-X23']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C14","difficulty":1,"kind":"mc","stem":"나래반 일지 ④에서 마지막 용액은 어떤 성질을 띠나요?","options":[{"t":"염기성","correct":true},{"t":"산성","mis":"SC6-1-u1-X22"},{"t":"처음과 같은 산성","mis":"SC6-1-u1-X23"},{"t":"알 수 없다","mis":"SC6-1-u1-X23"}],"explanation":["마지막 색을 봐요.","노란색 계열이에요.","염기성이에요."],"asset":{"type":"passage","lines":["선생님 시범 — 붉은 양배추 용액을 넣은 묽은 염산에","묽은 수산화 나트륨 용액을 조금씩 넣으셨다.","처음: 붉은색 계열 → 넣을수록 색이 바뀜 → 마지막: 노란색 계열"],"title":"나래반 일지 ④ 섞기 시범"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#5','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C17',1,'sa','auto','나래반 일지 ⑤에서 삼촌이 속이 쓰릴 때 드신 것은 무엇인가요?','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u1-C17","difficulty":1,"kind":"sa","stem":"나래반 일지 ⑤에서 삼촌이 속이 쓰릴 때 드신 것은 무엇인가요?","answer":["제산제"],"explanation":["염기성 약이에요.","세 글자예요.","제산제예요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"},"mis":"SC6-1-u1-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#6','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C19',1,'sa','auto','어떤 물질이 기존의 성질에서 점차 산성으로 변하는 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u1-C19","difficulty":1,"kind":"sa","stem":"어떤 물질이 기존의 성질에서 점차 산성으로 변하는 것을 세 글자로 쓰세요.","answer":["산성화"],"explanation":["점차 변해요.","세 글자예요.","산성화예요."],"mis":"SC6-1-u1-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#7','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C21',1,'mc','auto','나래반 일지 ⑦의 약속이 산성화를 줄이는 데 도움이 되는 까닭은 무엇인가요?',ARRAY['SC6-1-u1-X37','SC6-1-u1-X35']::text[],false,'{"seq":7,"concept":"SC6-1-u1-C21","difficulty":1,"kind":"mc","stem":"나래반 일지 ⑦의 약속이 산성화를 줄이는 데 도움이 되는 까닭은 무엇인가요?","options":[{"t":"자동차 이용을 줄여 대기로 나가는 오염 물질을 줄이기 때문에","correct":true},{"t":"걸으면 바닷물이 차가워지기 때문에","mis":"SC6-1-u1-X37"},{"t":"산성화는 걷기와 관계없기 때문에","mis":"SC6-1-u1-X35"},{"t":"대중교통을 타면 비가 오지 않기 때문에","mis":"SC6-1-u1-X37"}],"explanation":["약속을 읽어요.","자동차를 덜 타요.","오염 물질이 줄어요."],"asset":{"type":"passage","lines":["바닷물이 산성을 띠면 조개껍데기가 얇아지고 산호가 피해를 입어요.","조개껍데기와 산호의 주요 성분은 탄산 칼슘이에요.","과학관 앞 대리암 조각상도 산성비로 조금씩 훼손되고 있어요.","우리의 약속 — 가까운 곳은 걸어서, 먼 곳은 대중교통으로!"],"title":"나래반 일지 ⑦ 바닷가 과학관 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#8','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C23',1,'sa','auto','흙의 산성도를 분석하는 환경 과학자를 무엇이라고 하나요? (□□ 환경 과학자)','{}'::text[],false,'{"seq":8,"concept":"SC6-1-u1-C23","difficulty":1,"kind":"sa","stem":"흙의 산성도를 분석하는 환경 과학자를 무엇이라고 하나요? (□□ 환경 과학자)","answer":["토양","토양 환경 과학자"],"explanation":["흙을 연구해요.","두 글자예요.","토양 환경 과학자예요."],"mis":"SC6-1-u1-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#9','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C5',2,'mc','auto','여러 사람이 분류해도 같은 결과를 얻을 수 있는 분류 기준은 어느 것인가요?',ARRAY['SC6-1-u1-X07']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C5","difficulty":2,"kind":"mc","stem":"여러 사람이 분류해도 같은 결과를 얻을 수 있는 분류 기준은 어느 것인가요?","options":[{"t":"흔들었을 때 거품이 5초 이상 유지되는가?","correct":true},{"t":"냄새가 좋은가?","mis":"SC6-1-u1-X07"},{"t":"보기에 예쁜가?","mis":"SC6-1-u1-X07"},{"t":"내가 좋아하는 색인가?","mis":"SC6-1-u1-X07"}],"explanation":["객관적인 질문이에요.","누가 봐도 같아요.","거품 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#10','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C9',2,'ox','auto','나래반 일지 ②의 두 컵은 겉보기로는 구별하기 어렵지만 지시약으로는 구별할 수 있어요.',ARRAY['SC6-1-u1-X08']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C9","difficulty":2,"kind":"ox","stem":"나래반 일지 ②의 두 컵은 겉보기로는 구별하기 어렵지만 지시약으로는 구별할 수 있어요.","answer":"O","reason_options":[{"t":"지시약의 색깔 변화로 산성과 염기성을 나눌 수 있기 때문에","correct":true},{"t":"색깔이 없는 용액에는 지시약을 쓸 수 없기 때문에","mis":"SC6-1-u1-X08"}],"mis":"SC6-1-u1-X08","explanation":["둘 다 투명해요.","지시약 결과가 달랐어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["컵 ㉮와 ㉯에 든 용액은 둘 다 색깔이 없고 투명하다.","㉮에 페놀프탈레인 용액 — 붉은색으로 변함","㉯에 페놀프탈레인 용액 — 변화 없음","㉯에 푸른색 리트머스 시험지 — 붉은색으로 변함"],"title":"나래반 일지 ② 투명한 두 컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#11','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C11',2,'ox','auto','묽은 수산화 나트륨 용액에 넣은 흰자를 넣자마자 보고 변화가 없다고 결론 지어도 돼요.',ARRAY['SC6-1-u1-X19']::text[],false,'{"seq":11,"concept":"SC6-1-u1-C11","difficulty":2,"kind":"ox","stem":"묽은 수산화 나트륨 용액에 넣은 흰자를 넣자마자 보고 변화가 없다고 결론 지어도 돼요.","answer":"X","reason_options":[{"t":"단백질과의 반응은 시간이 지나면서 나타나기 때문에","correct":true},{"t":"염기성 용액의 반응은 언제나 곧바로 끝나기 때문에","mis":"SC6-1-u1-X19"}],"mis":"SC6-1-u1-X19","explanation":["반응 시간을 떠올려요.","오래 걸릴 수 있어요.","기다려야 해요."],"asset":{"type":"passage","lines":["날달걀을 식초에 담가 두었다 — 껍데기에서 기포가 생기며 껍데기가 녹았다.","삶은 달걀흰자 조각을 식초에 담가 두었다 — 변화가 없었다.","선생님이 묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣어 보여 주셨다","　　— 시간이 지나면서 흐물흐물해졌다."],"title":"나래반 일지 ③ 달걀 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#12','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C14',2,'ox','auto','나래반 일지 ④에서 묽은 수산화 나트륨 용액을 아주 조금만 넣었다면 용액은 곧바로 염기성이 되었을 거예요.',ARRAY['SC6-1-u1-X25']::text[],false,'{"seq":12,"concept":"SC6-1-u1-C14","difficulty":2,"kind":"ox","stem":"나래반 일지 ④에서 묽은 수산화 나트륨 용액을 아주 조금만 넣었다면 용액은 곧바로 염기성이 되었을 거예요.","answer":"X","reason_options":[{"t":"넣은 양에 따라 성질이 차례로 변하고, 더 많이 넣은 쪽의 성질을 나타내기 때문에","correct":true},{"t":"한 방울만 넣어도 언제나 곧바로 반대 성질이 되기 때문에","mis":"SC6-1-u1-X25"}],"mis":"SC6-1-u1-X25","explanation":["조금씩 넣었어요.","색이 차례로 변했어요.","곧바로는 아니에요."],"asset":{"type":"passage","lines":["선생님 시범 — 붉은 양배추 용액을 넣은 묽은 염산에","묽은 수산화 나트륨 용액을 조금씩 넣으셨다.","처음: 붉은색 계열 → 넣을수록 색이 바뀜 → 마지막: 노란색 계열"],"title":"나래반 일지 ④ 섞기 시범"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#13','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C16',2,'ox','auto','나래반 일지 ⑤의 네 가지는 모두 같은 성질의 용액을 이용한 예예요.',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":13,"concept":"SC6-1-u1-C16","difficulty":2,"kind":"ox","stem":"나래반 일지 ⑤의 네 가지는 모두 같은 성질의 용액을 이용한 예예요.","answer":"X","reason_options":[{"t":"식초·변기 청소용 세제는 산성, 제산제·하수구 세정제는 염기성이기 때문에","correct":true},{"t":"생활에서는 한 가지 성질의 용액만 쓰기 때문에","mis":"SC6-1-u1-X27"}],"mis":"SC6-1-u1-X27","explanation":["넷을 둘로 나눠요.","산성 둘, 염기성 둘이에요.","같지 않아요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#14','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C20',2,'ox','auto','나래반 일지 ⑦처럼 산성화는 생태계뿐 아니라 건물과 문화재에도 피해를 줘요.',ARRAY['SC6-1-u1-X33']::text[],false,'{"seq":14,"concept":"SC6-1-u1-C20","difficulty":2,"kind":"ox","stem":"나래반 일지 ⑦처럼 산성화는 생태계뿐 아니라 건물과 문화재에도 피해를 줘요.","answer":"O","reason_options":[{"t":"산성비로 대리암 조각상이나 건축물이 훼손되기 때문에","correct":true},{"t":"산성화는 살아 있는 생물에게만 피해를 주기 때문에","mis":"SC6-1-u1-X33"}],"mis":"SC6-1-u1-X33","explanation":["조각상을 떠올려요.","훼손되고 있어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["바닷물이 산성을 띠면 조개껍데기가 얇아지고 산호가 피해를 입어요.","조개껍데기와 산호의 주요 성분은 탄산 칼슘이에요.","과학관 앞 대리암 조각상도 산성비로 조금씩 훼손되고 있어요.","우리의 약속 — 가까운 곳은 걸어서, 먼 곳은 대중교통으로!"],"title":"나래반 일지 ⑦ 바닷가 과학관 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#15','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C21',2,'ox','auto','산성화는 시간이 지나면 저절로 모두 사라지므로 노력하지 않아도 돼요.',ARRAY['SC6-1-u1-X36']::text[],false,'{"seq":15,"concept":"SC6-1-u1-C21","difficulty":2,"kind":"ox","stem":"산성화는 시간이 지나면 저절로 모두 사라지므로 노력하지 않아도 돼요.","answer":"X","reason_options":[{"t":"사람의 활동으로 생기므로 원인을 줄이는 노력이 필요하기 때문에","correct":true},{"t":"산성화는 자연히 없어지기 때문에","mis":"SC6-1-u1-X36"}],"mis":"SC6-1-u1-X36","explanation":["원인을 떠올려요.","사람의 활동이에요.","노력이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#16','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C22',2,'ox','auto','나래반 일지 ⑧에서 사진을 쓸 때 출처와 주소를 적은 것은 바른 태도예요.',ARRAY['SC6-1-u1-X39']::text[],false,'{"seq":16,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"ox","stem":"나래반 일지 ⑧에서 사진을 쓸 때 출처와 주소를 적은 것은 바른 태도예요.","answer":"O","reason_options":[{"t":"자료를 만든 사람을 존중하고 믿을 수 있게 하기 때문에","correct":true},{"t":"누리망 자료는 누구나 출처 없이 써도 되기 때문에","mis":"SC6-1-u1-X39"}],"mis":"SC6-1-u1-X39","explanation":["출처를 밝혔어요.","바른 태도예요.","맞는 말이에요."],"asset":{"type":"passage","lines":["주제 — 토양 산성화","조사 — 원인·현황·전망·대책을 모둠원이 나누어 맡음","자료 — 누리집 사진을 쓸 때 출처와 주소를 함께 적음","공유 — 학급 누리집에 올리고 다른 모둠의 잘한 점을 댓글로 씀"],"title":"나래반 일지 ⑧ 알림 동영상 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#17','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C7',3,'ox','auto','나래반 일지 ①의 ㉠~㉤에 페놀프탈레인 용액을 떨어뜨리면 ㉢과 ㉣만 붉은색으로 변할 거예요.',ARRAY['SC6-1-u1-X12']::text[],false,'{"seq":17,"concept":"SC6-1-u1-C7","difficulty":3,"kind":"ox","stem":"나래반 일지 ①의 ㉠~㉤에 페놀프탈레인 용액을 떨어뜨리면 ㉢과 ㉣만 붉은색으로 변할 거예요.","answer":"O","reason_options":[{"t":"㉢과 ㉣은 염기성 용액이고 페놀프탈레인 용액은 염기성에서만 붉어지기 때문에","correct":true},{"t":"페놀프탈레인 용액은 산성 용액에서 붉어지기 때문에","mis":"SC6-1-u1-X12"}],"mis":"SC6-1-u1-X12","explanation":["염기성 용액을 찾아요.","㉢과 ㉣이에요.","맞는 말이에요."],"asset":{"type":"passage","lines":["㉠ 식초 — 붉은색 계열","㉡ 레몬즙 — 붉은색 계열","㉢ 제빵 소다 용액 — 푸른색 계열","㉣ 빨랫비누 물 — 푸른색이나 노란색 계열","㉤ 구연산 용액 — 붉은색 계열"],"title":"나래반 일지 ① 붉은 양배추 용액을 떨어뜨린 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#18','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C12',3,'ox','auto','성질 비교 실험은 좀 더 진한 용액을 쓰므로 실험복·보안경·실험용 장갑을 꼭 착용해요.',ARRAY['SC6-1-u1-X04']::text[],false,'{"seq":18,"concept":"SC6-1-u1-C12","difficulty":3,"kind":"ox","stem":"성질 비교 실험은 좀 더 진한 용액을 쓰므로 실험복·보안경·실험용 장갑을 꼭 착용해요.","answer":"O","reason_options":[{"t":"진한 용액이 피부나 눈에 닿으면 위험하기 때문에","correct":true},{"t":"묽은 용액이라 보호 장비가 필요 없기 때문에","mis":"SC6-1-u1-X04"}],"mis":"SC6-1-u1-X04","explanation":["용액의 진하기예요.","더 조심해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#19','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C15',3,'mc','auto','섞을 때의 성질 변화를 생활에 이용한 예로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X26']::text[],false,'{"seq":19,"concept":"SC6-1-u1-C15","difficulty":3,"kind":"mc","stem":"섞을 때의 성질 변화를 생활에 이용한 예로 알맞은 것은 어느 것인가요?","options":[{"t":"산성이 강해진 흙에 석회 가루를 뿌린다","correct":true},{"t":"투명한 용액을 흰 종이에 대어 본다","mis":"SC6-1-u1-X26"},{"t":"지시약으로 용액을 나눈다","mis":"SC6-1-u1-X26"},{"t":"달걀을 식초에 담가 본다","mis":"SC6-1-u1-X26"}],"explanation":["섞는 것을 찾아요.","반대 성질이에요.","석회 가루예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#20','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C18',3,'ox','auto','위액이 많이 나와 속이 쓰릴 때 레몬즙을 마시면 제산제처럼 속 쓰림이 약해져요.',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":20,"concept":"SC6-1-u1-C18","difficulty":3,"kind":"ox","stem":"위액이 많이 나와 속이 쓰릴 때 레몬즙을 마시면 제산제처럼 속 쓰림이 약해져요.","answer":"X","reason_options":[{"t":"레몬즙은 산성이라 산성인 위액을 약하게 하지 못하기 때문에","correct":true},{"t":"레몬즙도 위액과 반대 성질이기 때문에","mis":"SC6-1-u1-X27"}],"mis":"SC6-1-u1-X27","explanation":["레몬즙의 성질이에요.","위액과 같은 산성이에요.","약해지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#21','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C21',3,'ox','auto','산성화는 전 세계적으로 발생하는 환경 문제예요.',ARRAY['SC6-1-u1-X35']::text[],false,'{"seq":21,"concept":"SC6-1-u1-C21","difficulty":3,"kind":"ox","stem":"산성화는 전 세계적으로 발생하는 환경 문제예요.","answer":"O","reason_options":[{"t":"산성비·해양 산성화·토양 산성화가 세계 곳곳에서 나타나기 때문에","correct":true},{"t":"특정한 먼 나라에서만 생기기 때문에","mis":"SC6-1-u1-X35"}],"mis":"SC6-1-u1-X35","explanation":["어디서 일어나나요?","세계 곳곳이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#22','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C1',3,'ox','auto','보물 찾기에서 제빵 소다 용액과 물이 다 마른 뒤 지도를 바꾸는 것은 숨긴 곳을 맨눈으로 알 수 없게 하려는 거예요.',ARRAY['SC6-1-u1-X01']::text[],false,'{"seq":22,"concept":"SC6-1-u1-C1","difficulty":3,"kind":"ox","stem":"보물 찾기에서 제빵 소다 용액과 물이 다 마른 뒤 지도를 바꾸는 것은 숨긴 곳을 맨눈으로 알 수 없게 하려는 거예요.","answer":"O","reason_options":[{"t":"젖은 자국이 남아 있으면 숨긴 곳이 드러날 수 있기 때문에","correct":true},{"t":"마르면 페놀프탈레인 용액이 더 잘 붉어지기 때문에","mis":"SC6-1-u1-X01"}],"mis":"SC6-1-u1-X01","explanation":["젖어 있으면 티가 나요.","마르면 구별이 어려워요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#23','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C18',4,'mc','auto','나래반 일지 ④와 ⑤를 함께 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X28','SC6-1-u1-X23','SC6-1-u1-X29']::text[],false,'{"seq":23,"concept":"SC6-1-u1-C18","difficulty":4,"kind":"mc","stem":"나래반 일지 ④와 ⑤를 함께 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 용액이 만나면 성질이 약해지므로, 없애려는 물질과 반대 성질의 용액을 생활에 이용한다","correct":true},{"t":"섞어도 성질이 그대로라 같은 성질의 용액을 이용한다","mis":"SC6-1-u1-X28"},{"t":"섞으면 성질이 강해지므로 생활에 쓰지 않는다","mis":"SC6-1-u1-X23"},{"t":"산성과 염기성 용액은 생활에 쓰이지 않는다","mis":"SC6-1-u1-X29"}],"explanation":["④는 섞을 때예요.","⑤는 생활 이용이에요.","반대 성질을 써요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#24','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C14',4,'essay','teacher','나래반 일지 ④의 결과로 알 수 있는 성질 변화를 쓰고, 이를 근거로 일지 ⑥의 은호의 말을 바로잡으세요. 이 성질 변화를 생활에서 이용하는 예도 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u1-C14","difficulty":4,"kind":"essay","stem":"나래반 일지 ④의 결과로 알 수 있는 성질 변화를 쓰고, 이를 근거로 일지 ⑥의 은호의 말을 바로잡으세요. 이 성질 변화를 생활에서 이용하는 예도 하나 쓰세요.","answer_guide":{"answer":"예: 붉은 양배추 용액을 넣은 묽은 염산에 묽은 수산화 나트륨 용액을 넣을수록 붉은색 계열에서 노란색 계열로 변했으므로, 산성이 점점 약해지다가 염기성으로 변했다. 은호야, 산성 용액과 염기성 용액은 섞으면 그대로가 아니라 처음의 성질이 약해지다가 많이 넣은 용액의 성질로 변해. 생활에서는 산성이 강해진 흙에 염기성인 석회 가루를 뿌려 식물이 잘 자라게 한다.","scoring_points":["일지 ④의 성질 변화를 썼는가","근거를 들어 은호의 말을 바로잡았는가","생활 속 이용 예를 썼는가"]},"explanation":["색 변화를 성질로 바꿔요.","은호에게 설명해요.","이용 예를 들어요."],"asset":{"type":"passage","lines":["선생님 시범 — 붉은 양배추 용액을 넣은 묽은 염산에","묽은 수산화 나트륨 용액을 조금씩 넣으셨다.","처음: 붉은색 계열 → 넣을수록 색이 바뀜 → 마지막: 노란색 계열"],"title":"나래반 일지 ④ 섞기 시범"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_c#25','sci',6,1,'u1','','g6_1_sci_u1_review_c','unit_review','SC6-1-u1-C22',4,'essay','teacher','나래반 일지 ⑧의 동영상 계획에서 잘한 점 세 가지를 찾아 까닭과 함께 쓰고, 이 동영상을 더 좋게 만들 방법을 한 가지 제안하세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u1-C22","difficulty":4,"kind":"essay","stem":"나래반 일지 ⑧의 동영상 계획에서 잘한 점 세 가지를 찾아 까닭과 함께 쓰고, 이 동영상을 더 좋게 만들 방법을 한 가지 제안하세요.","answer_guide":{"answer":"예: 첫째, 원인·현황·전망·대책을 모두 조사해 피해를 빠짐없이 알릴 수 있다. 둘째, 모둠원이 역할을 나누어 맡아 협력했다. 셋째, 사진의 출처와 주소를 적어 자료를 만든 사람을 존중하고 믿을 수 있게 했다. 다른 모둠의 잘한 점을 댓글로 쓴 것도 좋다. 더 좋게 하려면 토양 환경 과학자가 하는 일(화학 비료·농약을 줄이는 방법 연구)을 넣어 우리가 할 수 있는 대책을 함께 알리면 좋겠다.","scoring_points":["잘한 점 세 가지를 찾았는가","각각의 까닭을 썼는가","더 좋게 만들 방법을 제안했는가"]},"explanation":["계획을 하나씩 살펴요.","까닭을 붙여요.","제안을 해요."],"asset":{"type":"passage","lines":["주제 — 토양 산성화","조사 — 원인·현황·전망·대책을 모둠원이 나누어 맡음","자료 — 누리집 사진을 쓸 때 출처와 주소를 함께 적음","공유 — 학급 누리집에 올리고 다른 모둠의 잘한 점을 댓글로 씀"],"title":"나래반 일지 ⑧ 알림 동영상 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#1','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C6',1,'blank','auto','「지시약은 용액의 (    )에 따라 색깔 변화가 나타나는 물질입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X09']::text[],false,'{"seq":1,"concept":"SC6-1-u1-C6","difficulty":1,"kind":"blank","stem":"「지시약은 용액의 (    )에 따라 색깔 변화가 나타나는 물질입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"성질","correct":true},{"t":"양","mis":"SC6-1-u1-X09"},{"t":"온도","mis":"SC6-1-u1-X09"},{"t":"냄새","mis":"SC6-1-u1-X09"}],"explanation":["지시약의 뜻이에요.","산성·염기성이에요.","성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#2','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C7',1,'sa','auto','산성 용액을 만나면 붉은색으로 변하는 리트머스 시험지는 무슨 색인가요? (□□□ 리트머스 시험지)','{}'::text[],false,'{"seq":2,"concept":"SC6-1-u1-C7","difficulty":1,"kind":"sa","stem":"산성 용액을 만나면 붉은색으로 변하는 리트머스 시험지는 무슨 색인가요? (□□□ 리트머스 시험지)","answer":["푸른색","푸른색 리트머스 시험지"],"explanation":["산성에서 변해요.","처음 색은 붉지 않아요.","푸른색이에요."],"mis":"SC6-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#3','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C11',1,'mc','auto','나래반 일지 ③에서 삶은 달걀흰자를 흐물흐물하게 만든 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X17']::text[],false,'{"seq":3,"concept":"SC6-1-u1-C11","difficulty":1,"kind":"mc","stem":"나래반 일지 ③에서 삶은 달걀흰자를 흐물흐물하게 만든 용액은 어느 것인가요?","options":[{"t":"묽은 수산화 나트륨 용액","correct":true},{"t":"식초","mis":"SC6-1-u1-X17"},{"t":"레몬즙","mis":"SC6-1-u1-X17"},{"t":"구연산 용액","mis":"SC6-1-u1-X17"}],"explanation":["흰자는 단백질이에요.","염기성 용액이에요.","묽은 수산화 나트륨 용액이에요."],"asset":{"type":"passage","lines":["날달걀을 식초에 담가 두었다 — 껍데기에서 기포가 생기며 껍데기가 녹았다.","삶은 달걀흰자 조각을 식초에 담가 두었다 — 변화가 없었다.","선생님이 묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣어 보여 주셨다","　　— 시간이 지나면서 흐물흐물해졌다."],"title":"나래반 일지 ③ 달걀 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#4','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C14',1,'blank','auto','「산성 용액에 염기성 용액을 계속 넣으면 산성이 점점 (    ) 염기성으로 변합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X24']::text[],false,'{"seq":4,"concept":"SC6-1-u1-C14","difficulty":1,"kind":"blank","stem":"「산성 용액에 염기성 용액을 계속 넣으면 산성이 점점 (    ) 염기성으로 변합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"약해지다가","correct":true},{"t":"강해지다가","mis":"SC6-1-u1-X23"},{"t":"그대로이다가","mis":"SC6-1-u1-X23"},{"t":"사라지다가","mis":"SC6-1-u1-X24"}],"explanation":["처음 성질이 어떻게 되나요?","약해져요.","약해지다가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#5','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C16',1,'mc','auto','음식에 신맛을 낼 때 쓰는 산성 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":5,"concept":"SC6-1-u1-C16","difficulty":1,"kind":"mc","stem":"음식에 신맛을 낼 때 쓰는 산성 용액은 어느 것인가요?","options":[{"t":"레몬즙","correct":true},{"t":"제산제","mis":"SC6-1-u1-X27"},{"t":"하수구 세정제","mis":"SC6-1-u1-X27"},{"t":"욕실 청소용 표백제","mis":"SC6-1-u1-X27"}],"explanation":["요리에 써요.","신맛이 나요.","레몬즙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#6','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C20',1,'mc','auto','나래반 일지 ⑦의 안내판에서 바닷물이 산성을 띠어 생기는 피해는 어느 것인가요?',ARRAY['SC6-1-u1-X32']::text[],false,'{"seq":6,"concept":"SC6-1-u1-C20","difficulty":1,"kind":"mc","stem":"나래반 일지 ⑦의 안내판에서 바닷물이 산성을 띠어 생기는 피해는 어느 것인가요?","options":[{"t":"조개껍데기가 얇아진다","correct":true},{"t":"식물의 생장이 억제된다","mis":"SC6-1-u1-X32"},{"t":"토양의 미생물 활동이 줄어든다","mis":"SC6-1-u1-X32"},{"t":"바닷물이 늘 깨끗해진다","mis":"SC6-1-u1-X32"}],"explanation":["바다를 골라요.","안내판 첫 줄이에요.","조개껍데기예요."],"asset":{"type":"passage","lines":["바닷물이 산성을 띠면 조개껍데기가 얇아지고 산호가 피해를 입어요.","조개껍데기와 산호의 주요 성분은 탄산 칼슘이에요.","과학관 앞 대리암 조각상도 산성비로 조금씩 훼손되고 있어요.","우리의 약속 — 가까운 곳은 걸어서, 먼 곳은 대중교통으로!"],"title":"나래반 일지 ⑦ 바닷가 과학관 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#7','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C21',1,'sa','auto','산성화를 줄이려고 자동차 대신 이용하는 버스·지하철 같은 것을 무엇이라고 하나요? (□□교통)','{}'::text[],false,'{"seq":7,"concept":"SC6-1-u1-C21","difficulty":1,"kind":"sa","stem":"산성화를 줄이려고 자동차 대신 이용하는 버스·지하철 같은 것을 무엇이라고 하나요? (□□교통)","answer":["대중","대중교통"],"explanation":["여럿이 함께 타요.","두 글자를 넣어요.","대중교통이에요."],"mis":"SC6-1-u1-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#8','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C1',1,'mc','auto','보물 찾기 활동에서 보물을 숨긴 곳에 떨어뜨린 용액은 어느 것인가요?',ARRAY['SC6-1-u1-X01']::text[],false,'{"seq":8,"concept":"SC6-1-u1-C1","difficulty":1,"kind":"mc","stem":"보물 찾기 활동에서 보물을 숨긴 곳에 떨어뜨린 용액은 어느 것인가요?","options":[{"t":"제빵 소다 용액","correct":true},{"t":"물","mis":"SC6-1-u1-X01"},{"t":"식초","mis":"SC6-1-u1-X01"},{"t":"페놀프탈레인 용액","mis":"SC6-1-u1-X01"}],"explanation":["숨길 때 쓴 용액이에요.","찾을 때는 페놀프탈레인이에요.","제빵 소다 용액이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#9','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C5',2,'error','auto','분류 기준을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X07','SC6-1-u1-X08']::text[],false,'{"seq":9,"concept":"SC6-1-u1-C5","difficulty":2,"kind":"error","stem":"분류 기준을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「「예쁜가?」로 나누면 누구나 같은 결과가 나와.」","correct":true,"mis_target":"SC6-1-u1-X07"},{"t":"지온 — 「「투명한가?」는 알맞은 기준이야.」","mis":"SC6-1-u1-X07"},{"t":"하경 — 「겉보기가 비슷한 용액은 나누기 어려워.」","mis":"SC6-1-u1-X08"}],"explanation":["예쁜 것은 사람마다 달라요.","객관적이지 않아요.","윤슬이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#10','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C7',2,'error','auto','나래반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X11','SC6-1-u1-X15']::text[],false,'{"seq":10,"concept":"SC6-1-u1-C7","difficulty":2,"kind":"error","stem":"나래반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시온 — 「㉯에 붉은색 리트머스 시험지를 대면 푸르게 변할 거야.」","correct":true,"mis_target":"SC6-1-u1-X11"},{"t":"라윤 — 「㉮는 염기성 용액이야.」","mis":"SC6-1-u1-X15"},{"t":"태하 — 「㉯는 산성 용액이야.」","mis":"SC6-1-u1-X15"}],"explanation":["㉯는 산성이에요.","붉은색 시험지는 염기성에서 변해요.","시온이 잘못 말했어요."],"asset":{"type":"passage","lines":["컵 ㉮와 ㉯에 든 용액은 둘 다 색깔이 없고 투명하다.","㉮에 페놀프탈레인 용액 — 붉은색으로 변함","㉯에 페놀프탈레인 용액 — 변화 없음","㉯에 푸른색 리트머스 시험지 — 붉은색으로 변함"],"title":"나래반 일지 ② 투명한 두 컵"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#11','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C11',2,'error','auto','나래반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X17','SC6-1-u1-X20']::text[],false,'{"seq":11,"concept":"SC6-1-u1-C11","difficulty":2,"kind":"error","stem":"나래반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"해온 — 「흰자가 녹았으니 묽은 수산화 나트륨 용액은 산성이야.」","correct":true,"mis_target":"SC6-1-u1-X17"},{"t":"나린 — 「껍데기가 녹았으니 식초는 산성이야.」","mis":"SC6-1-u1-X17"},{"t":"준우 — 「두 용액은 서로 다른 것을 녹였어.」","mis":"SC6-1-u1-X20"}],"explanation":["흰자를 녹이는 용액이에요.","염기성이에요.","해온이 잘못 말했어요."],"asset":{"type":"passage","lines":["날달걀을 식초에 담가 두었다 — 껍데기에서 기포가 생기며 껍데기가 녹았다.","삶은 달걀흰자 조각을 식초에 담가 두었다 — 변화가 없었다.","선생님이 묽은 수산화 나트륨 용액에 삶은 달걀흰자를 넣어 보여 주셨다","　　— 시간이 지나면서 흐물흐물해졌다."],"title":"나래반 일지 ③ 달걀 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#12','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C14',2,'error','auto','나래반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X23','SC6-1-u1-X22']::text[],false,'{"seq":12,"concept":"SC6-1-u1-C14","difficulty":2,"kind":"error","stem":"나래반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로하 — 「두 용액을 섞어도 성질은 변하지 않아.」","correct":true,"mis_target":"SC6-1-u1-X23"},{"t":"가온 — 「색이 변했으니 성질도 변했어.」","mis":"SC6-1-u1-X23"},{"t":"미르 — 「붉은 양배추 용액 덕분에 변화를 볼 수 있었어.」","mis":"SC6-1-u1-X22"}],"explanation":["색이 변했어요.","성질이 변했어요.","로하가 잘못 말했어요."],"asset":{"type":"passage","lines":["선생님 시범 — 붉은 양배추 용액을 넣은 묽은 염산에","묽은 수산화 나트륨 용액을 조금씩 넣으셨다.","처음: 붉은색 계열 → 넣을수록 색이 바뀜 → 마지막: 노란색 계열"],"title":"나래반 일지 ④ 섞기 시범"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#13','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C18',2,'error','auto','속 쓰림을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X28','SC6-1-u1-X27']::text[],false,'{"seq":13,"concept":"SC6-1-u1-C18","difficulty":2,"kind":"error","stem":"속 쓰림을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다올 — 「위액이 산성이니까 산성인 약을 먹어야 속이 편해져.」","correct":true,"mis_target":"SC6-1-u1-X28"},{"t":"하은 — 「위액은 산성이라 염기성인 제산제를 먹어.」","mis":"SC6-1-u1-X28"},{"t":"이찬 — 「하수구 세정제는 머리카락을 녹여.」","mis":"SC6-1-u1-X27"}],"explanation":["위액은 산성이에요.","반대 성질이 필요해요.","다올이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#14','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C20',2,'error','auto','산호의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X34']::text[],false,'{"seq":14,"concept":"SC6-1-u1-C20","difficulty":2,"kind":"error","stem":"산호의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「산호가 하얗게 변하는 건 오직 해양 산성화 때문이야.」","correct":true,"mis_target":"SC6-1-u1-X34"},{"t":"소미 — 「해양 산성화도 산호가 하얗게 변하는 원인 가운데 하나야.」","mis":"SC6-1-u1-X34"},{"t":"유찬 — 「바다 수온이 오르는 것도 원인이 될 수 있어.」","mis":"SC6-1-u1-X34"}],"explanation":["원인이 하나일까요?","여러 가지예요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#15','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C21',2,'error','auto','산성화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X35','SC6-1-u1-X31']::text[],false,'{"seq":15,"concept":"SC6-1-u1-C21","difficulty":2,"kind":"error","stem":"산성화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준혁 — 「바다에서 먼 우리 동네는 산성화와 관계없어.」","correct":true,"mis_target":"SC6-1-u1-X35"},{"t":"아라 — 「산성비는 우리 동네에도 내릴 수 있어.」","mis":"SC6-1-u1-X35"},{"t":"다현 — 「흙도 산성을 띨 수 있어.」","mis":"SC6-1-u1-X31"}],"explanation":["산성비와 흙을 떠올려요.","어디서나 생겨요.","준혁이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#16','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C22',2,'error','auto','공유를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X39']::text[],false,'{"seq":16,"concept":"SC6-1-u1-C22","difficulty":2,"kind":"error","stem":"공유를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세온 — 「다른 모둠 동영상에는 못한 점만 골라 댓글을 달자.」","correct":true,"mis_target":"SC6-1-u1-X39"},{"t":"보민 — 「잘한 점을 찾아 댓글로 써 주자.」","mis":"SC6-1-u1-X39"},{"t":"찬희 — 「조사한 자료의 주소를 링크로 연결하자.」","mis":"SC6-1-u1-X39"}],"explanation":["댓글 쓰는 법이에요.","잘한 점을 써요.","세온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#17','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C9',3,'error','auto','나래반 일지 ⑥의 서아의 말을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X16','SC6-1-u1-X10']::text[],false,'{"seq":17,"concept":"SC6-1-u1-C9","difficulty":3,"kind":"error","stem":"나래반 일지 ⑥의 서아의 말을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나 — 「서아 말이 맞아, 지시약마다 다른 무리가 생겨.」","correct":true,"mis_target":"SC6-1-u1-X16"},{"t":"건희 — 「리트머스든 양배추든 나뉘는 무리는 같아.」","mis":"SC6-1-u1-X16"},{"t":"도아 — 「색깔 변화는 지시약마다 달라.」","mis":"SC6-1-u1-X10"}],"explanation":["분류 결과를 견줘요.","무리는 같았어요.","유나가 잘못 말했어요."],"asset":{"type":"passage","lines":["도윤 — 「투명한 용액은 색깔이 없는 거야.」","서아 — 「지시약이 다르면 나뉘는 무리도 달라.」","은호 — 「산성 용액과 염기성 용액은 섞어도 그대로야.」","선생님 — 세 친구의 말을 실험 결과로 하나씩 따져 보자."],"title":"나래반 일지 ⑥ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#18','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C11',3,'error','auto','성질 비교 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X20','SC6-1-u1-X19']::text[],false,'{"seq":18,"concept":"SC6-1-u1-C11","difficulty":3,"kind":"error","stem":"성질 비교 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「달걀 껍데기와 삶은 달걀흰자는 같은 용액에서 녹아.」","correct":true,"mis_target":"SC6-1-u1-X20"},{"t":"하랑 — 「껍데기는 산성, 흰자는 염기성 용액에서 녹아.」","mis":"SC6-1-u1-X20"},{"t":"지율 — 「흰자의 반응은 오래 걸릴 수 있어.」","mis":"SC6-1-u1-X19"}],"explanation":["성분이 달라요.","녹이는 용액도 달라요.","수호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
