INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#20','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C17',3,'error','auto','욕실 청소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":20,"concept":"SC6-1-u1-C17","difficulty":3,"kind":"error","stem":"욕실 청소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하진 — 「욕실의 때와 세균은 산성 표백제로 없애.」","correct":true,"mis_target":"SC6-1-u1-X27"},{"t":"우림 — 「욕실 청소용 표백제는 염기성이야.」","mis":"SC6-1-u1-X27"},{"t":"서율 — 「표백제는 단백질을 녹여 때를 없애.」","mis":"SC6-1-u1-X27"}],"explanation":["표백제의 성질이에요.","염기성이에요.","하진이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
