INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#22','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C8',3,'error','auto','붉은 양배추 용액을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X14','SC6-1-u1-X13']::text[],false,'{"seq":22,"concept":"SC6-1-u1-C8","difficulty":3,"kind":"error","stem":"붉은 양배추 용액을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「양배추 용액이 연한 붉은색이면 산성이 아니야.」","correct":true,"mis_target":"SC6-1-u1-X14"},{"t":"초아 — 「붉은색 계열이면 산성이야.」","mis":"SC6-1-u1-X13"},{"t":"윤재 — 「푸른색이나 노란색 계열이면 염기성이야.」","mis":"SC6-1-u1-X13"}],"explanation":["연해도 계열은 같아요.","붉은색 계열이에요.","태민이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#23','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C21',4,'mc','auto','나래반 일지 ⑦과 ⑧을 함께 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X35','SC6-1-u1-X36','SC6-1-u1-X39']::text[],false,'{"seq":23,"concept":"SC6-1-u1-C21","difficulty":4,"kind":"mc","stem":"나래반 일지 ⑦과 ⑧을 함께 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산성화는 조개껍데기·조각상 등에 피해를 주므로 원인을 줄이고, 출처를 밝혀 피해를 알리는 노력을 함께 해야 한다","correct":true},{"t":"산성화는 먼 곳의 일이라 알릴 필요가 없다","mis":"SC6-1-u1-X35"},{"t":"산성화는 저절로 사라지므로 기다리면 된다","mis":"SC6-1-u1-X36"},{"t":"출처 없이 빠르게 퍼뜨리는 것이 가장 중요하다","mis":"SC6-1-u1-X39"}],"explanation":["⑦은 피해와 약속이에요.","⑧은 알리기예요.","둘을 함께 해요."],"asset":{"type":"passage","lines":["주제 — 토양 산성화","조사 — 원인·현황·전망·대책을 모둠원이 나누어 맡음","자료 — 누리집 사진을 쓸 때 출처와 주소를 함께 적음","공유 — 학급 누리집에 올리고 다른 모둠의 잘한 점을 댓글로 씀"],"title":"나래반 일지 ⑧ 알림 동영상 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#24','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C18',4,'essay','teacher','나래반 일지 ⑤의 네 가지 예를 산성 용액을 이용한 것과 염기성 용액을 이용한 것으로 나누고, 그중 두 가지를 골라 없애려는 물질의 성질과 함께 왜 그 용액을 쓰는지 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u1-C18","difficulty":4,"kind":"essay","stem":"나래반 일지 ⑤의 네 가지 예를 산성 용액을 이용한 것과 염기성 용액을 이용한 것으로 나누고, 그중 두 가지를 골라 없애려는 물질의 성질과 함께 왜 그 용액을 쓰는지 설명하세요.","answer_guide":{"answer":"예: 산성 용액을 이용한 것은 할머니의 식초, 아빠의 변기 청소용 세제이고, 염기성 용액을 이용한 것은 삼촌의 제산제, 엄마의 하수구 세정제이다. 도마의 비린내는 염기성 물질이라 산성인 식초로 닦으면 성질이 약해져 냄새가 줄어든다. 위액은 산성이라 염기성인 제산제를 먹으면 산성이 약해져 속 쓰림이 줄어든다. 이처럼 없애려는 물질과 반대되는 성질의 용액을 이용한다.","scoring_points":["네 가지를 바르게 나누었는가","두 가지 예에서 없애려는 물질의 성질을 썼는가","반대 성질의 용액을 쓰는 까닭을 설명했는가"]},"explanation":["둘로 나눠요.","두 가지를 골라요.","반대 성질로 설명해요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u1_review_d#25','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C21',4,'essay','teacher','「산과 염기」에서 배운 것을 바탕으로 우리 반 「산성화 줄이기 약속」 세 가지를 만들고, 각 약속이 어떤 과학적 사실과 이어지는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u1-C21","difficulty":4,"kind":"essay","stem":"「산과 염기」에서 배운 것을 바탕으로 우리 반 「산성화 줄이기 약속」 세 가지를 만들고, 각 약속이 어떤 과학적 사실과 이어지는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 가까운 곳은 걷거나 자전거를 탄다 — 자동차 배기가스 같은 대기 오염 물질이 빗물에 녹으면 산성비가 되기 때문이다. 둘째, 먼 곳은 대중교통을 이용한다 — 이산화 탄소가 줄면 해양 산성화로 조개껍데기가 얇아지는 피해를 줄일 수 있기 때문이다. 셋째, 산성화 피해를 출처와 함께 친구들에게 알린다 — 산성화는 전 세계적인 문제라 여러 사람이 함께 노력해야 하기 때문이다.","scoring_points":["약속 세 가지를 썼는가","각 약속을 산성비·해양 산성화 등 과학적 사실과 이었는가","우리가 실천할 수 있는 약속인가"]},"explanation":["약속을 셋 정해요.","과학적 사실과 이어요.","실천할 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
